def _fusion_later_studies() -> list[dict[str, Any]]:
    out = []
    cache: dict[tuple[str, str], Any] = {}
    for study, name, pair, label in FUSION_LATER_STUDIES:
        if (study, name) not in cache:
            try:
                cache[(study, name)] = json.loads(
                    (ROOT / "docs" / "research" / study / name).read_text(encoding="utf-8")
                )
            except (OSError, ValueError):
                cache[(study, name)] = None
        data = cache[(study, name)]
        row = ((data or {}).get("pairs") or {}).get(pair)
        if not row:
            continue
        out.append({
            "label": label, "study": study, "pair": pair,
            "station_days": row.get("station_days"),
            "days": len((data or {}).get("days_scored") or []),
            "d_logscore": row.get("d_logscore"), "ci_logscore": row.get("ci_logscore"),
            "d_brier": row.get("d_brier"), "ci_brier": row.get("ci_brier"),
            "d_crps": row.get("d_crps"), "ci_crps": row.get("ci_crps"),
            "passes": bool(row.get("lower")),
        })
    try:
        logloss = json.loads(
            (ROOT / "docs" / "research" / "fusion199_logloss_20260925" / "results.json")
            .read_text(encoding="utf-8")
        ).get("pooled") or {}
    except (OSError, ValueError):
        logloss = {}
    if logloss.get("delta"):
        out.append({
            "label": "训练目标改桶 LogLoss", "study": "fusion199_logloss_20260925",
            "pair": "logloss_vs_current",
            "station_days": logloss.get("station_days"), "days": logloss.get("days"),
            "d_logscore": logloss["delta"].get("nll"), "ci_logscore": (logloss.get("ci95") or {}).get("nll"),
            "d_brier": logloss["delta"].get("brier"), "ci_brier": (logloss.get("ci95") or {}).get("brier"),
            "d_crps": None, "ci_crps": None, "passes": bool(logloss.get("holds")),
        })
    return out


def _fusion_blend_mode() -> str | None:
    try:
        from bayes_basket_target import fusion_blend  # noqa: PLC0415
    except ImportError:
        return None
    return str(fusion_blend.FUSION_BLEND_MODE)


def _scorecard_window(conn: sqlite3.Connection) -> dict[str, Any]:
    """Where the scored sample starts: P0's serving-arithmetic anchor.

    The scorecard read a calendar window over an append-only table, so a
    rule change never reached it: on 2026-09-17 the stable pool (charter
    134) had served for three days while 95% of the scored station-day-leads
    were decided under the contest it replaced, and the retired rule's too-
    wide book (width/error 1.53) painted the sharpness, PIT and calibration
    lamps for a book serving at 1.00.  The anchor is the same boundary the
    band audit and the fitting lanes already cut at.  The calendar window
    stays as an outer cap, and is the whole window only when no anchor can
    be read -- which the header then says.
    """

    try:
        from bayes_basket_target.center_width_store import (  # noqa: PLC0415
            evidence_anchor,
        )
    except ImportError:
        return {"anchor": None, "anchor_state": "unavailable"}
    try:
        anchor = evidence_anchor(conn, stage="P0")
    except Exception:  # noqa: BLE001 -- a broken anchor store is a reading, not a crash
        return {"anchor": None, "anchor_state": "error"}
    if not anchor:
        return {"anchor": None, "anchor_state": "missing"}
    return {"anchor": str(anchor), "anchor_state": "ok"}


def _parse_utc(stamp: str) -> datetime | None:
    try:
        parsed = datetime.fromisoformat(str(stamp).replace("Z", "+00:00"))
    except ValueError:
        return None
    return parsed if parsed.tzinfo else parsed.replace(tzinfo=timezone.utc)


def collect_calibration_scorecard(
    conn: sqlite3.Connection,
    *,
    window_override: Mapping[str, str] | None = None,
) -> dict[str, Any]:
    """Six layers of calibration quality, each reduced to one verdict.

    The scores already existed in pieces across the page; what was missing
    was a judgement.  Every layer here answers "is this good" with a colour
    and a sentence, and keeps the number beside it as the evidence rather
    than the headline.

    Two rules on the sample, both from the 2026-09-17 review.  It starts at
    P0's serving-arithmetic anchor (``_scorecard_window``).  And each
    station x event day x lead counts once: the evaluation table writes a
    row per candidate view, cycle, season bin and re-evaluation, a median 59
    rows per station-day and up to 1,459, so an unweighted mean was a vote
    of whichever scopes the pool happened to mint most.  Weighted equally,
    the calibration lamp's worst bin moved from ">=50% under-claimed by 7.7
    points" to "25-30% under-claimed by 5.6", and the >=50% bin read 58.5%
    promised against 58.2% happened.
    """

    if not _table_exists(
        conn, "calibration_cross_native_ensemble_oos_prediction"
    ):
        return {"available": False}
    truth: dict[tuple[str, str], float] = {}
    for station, day, tmax in conn.execute(
        "SELECT station_id, local_date, official_tmax_c"
        " FROM calibration_station_daily_high_truth"
        " WHERE qc_status='ACCEPTED' ORDER BY revision_no"
    ):
        truth[(str(station), str(day))] = float(tmax)
    if not truth:
        return {"available": False}

    # ``window_override`` scores an earlier version's span, [since, until),
    # beside the current one (user, 2026-09-18: 显示，做对比).
    window = (
        {"anchor": str(window_override["since"]), "anchor_state": "previous_version",
         "until": str(window_override["until"]),
         "version": window_override.get("version")}
        if window_override else _scorecard_window(conn)
    )
    until_at = (
        _parse_utc(str(window_override["until"])) if window_override else None
    )
    anchor_at = _parse_utc(window["anchor"]) if window["anchor"] else None
    if window["anchor"] and anchor_at is None:
        window = {"anchor": None, "anchor_state": "unparseable"}
    window["max_days"] = SCORECARD_MAX_WINDOW_DAYS
    # The SQL bound is the anchor's whole second, which can only admit a few
    # rows too many; the exact comparison below drops them.
    anchor_prefix = (
        anchor_at.astimezone(timezone.utc).strftime("%Y-%m-%dT%H:%M:%S")
        if anchor_at is not None else ""
    )

    scored: list[dict[str, Any]] = []
    stations: set[str] = set()
    latest = ""
    # The flat reference depends only on the ladder and the truth, so it is
    # scored once per (ladder, truth), not once per row: half of the
    # 1.34M scorings of 2026-10-02 were this one number recomputed.
    flat_by_ladder: dict[tuple[str, float], dict[str, Any] | None] = {}
    # No ORDER BY: nothing below depends on row order, and sorting the
    # window (668k rows, 318 MB of JSON on 2026-10-02) was a temp B-tree
    # the size of the window, spilled to disk on every build.
    for (
        station, day, lead, probabilities_json, centers_json, decided
    ) in conn.execute(
        "SELECT station_id, event_date, lead_bucket, probabilities_json,"
        " bucket_centers_c_json, decision_at_utc"
        " FROM calibration_cross_native_ensemble_oos_prediction"
        " WHERE event_date>=date('now',?) AND decision_at_utc>=?",
        (f"-{SCORECARD_MAX_WINDOW_DAYS} days", anchor_prefix),
    ):
        actual = truth.get((str(station), str(day)))
        if actual is None:
            continue
        # Calendar leads (d0/d1/d2) were retired for hour buckets; rows under
        # the old vocabulary stop in mid-August and would drag stale scopes
        # into a board that is meant to read as current.
        if not str(lead).startswith("h"):
            continue
        if anchor_at is not None:
            decided_at = _parse_utc(str(decided))
            if decided_at is None or decided_at < anchor_at:
                continue
            if until_at is not None and decided_at >= until_at:
                continue
        try:
            probability = json.loads(probabilities_json)
            centers = {
                str(key): float(value)
                for key, value in json.loads(centers_json).items()
            }
        except (ValueError, TypeError, AttributeError):
            continue
        scores = _prediction_scores(probability, centers, actual)
        if scores is None:
            continue
        # The no-skill reference, a flat forecast over the same ladder.  It
        # is not the gate's climatology, but measured on the 2026-09-17
        # sample it scores alike (mean CRPS 2.05 against 2.06 for a 60-day
        # kernel climatology built with the gate's own function), because a
        # summer window drifts off an autumn event as far as flat does.
        flat_key = (str(centers_json), actual)
        if flat_key in flat_by_ladder:
            flat_scores = flat_by_ladder[flat_key]
        else:
            order = _bucket_order(centers)
            flat_scores = _prediction_scores(
                {key: 1.0 / len(order) for key in order}, centers, actual
            )
            flat_by_ladder[flat_key] = flat_scores
        if flat_scores is None:
            continue
        scores["flat_crps"] = flat_scores["crps"]
        scores["flat_brier"] = flat_scores["brier"]
        scores["station"] = str(station)
        scores["event_date"] = str(day)
        scores["lead"] = str(lead)
        scored.append(scores)
        stations.add(str(station))
        latest = max(latest, str(decided))

    if not scored:
        return {"available": False, "window": window}
    copies = Counter(
        (row["station"], row["event_date"], row["lead"]) for row in scored
    )
    for row in scored:
        row["weight"] = 1.0 / copies[
            (row["station"], row["event_date"], row["lead"])
        ]
    row_count = len(scored)
    reliability_input = [
        (promised, happened, row["weight"])
        for row in scored for promised, happened in row["reliability_pairs"]
    ]
    # Every lamp below is a weighted mean, sum(w*x)/sum(w), with w one over
    # the copies of its (station, day, lead) -- so each of those groups
    # contributes exactly its own mean at weight one.  Collapsed here, the
    # ~210 passes below walk a few thousand groups instead of every row
    # (668k on 2026-10-02, 63 s of _mean alone); the numbers are the same up
    # to the order of a float sum.  Reliability keeps its per-row pairs.
    grouped: dict[tuple[str, str, str], dict[str, Any]] = {}
    for row in scored:
        key = (row["station"], row["event_date"], row["lead"])
        slot = grouped.get(key)
        if slot is None:
            slot = grouped[key] = {
                "station": row["station"], "event_date": row["event_date"],
                "lead": row["lead"], "weight": 1.0,
                "pit_bins": [0.0] * PIT_BIN_COUNT,
                **{name: 0.0 for name in _SCORECARD_LINEAR_KEYS},
            }
        share = row["weight"]
        for name in _SCORECARD_LINEAR_KEYS:
            slot[name] += share * row[name]
        bins = slot["pit_bins"]
        for index, value in enumerate(row["pit_bins"]):
            bins[index] += share * value
    scored = list(grouped.values())
    station_days = {(row["station"], row["event_date"]) for row in scored}
    event_days = {row["event_date"] for row in scored}
    accumulating = len(event_days) < SCORECARD_MIN_EVENT_DAYS

    def _mean(rows: list[dict[str, Any]], key: str) -> float | None:
        weight = sum(row["weight"] for row in rows)
        if weight <= 0:
            return None
        return sum(row["weight"] * row[key] for row in rows) / weight

    def _skill(rows: list[dict[str, Any]], key: str) -> float | None:
        ours, theirs = _mean(rows, key), _mean(rows, f"flat_{key}")
        if ours is None or theirs is None or theirs <= 0:
            return None
        return 1.0 - ours / theirs

    def _width_ratio(rows: list[dict[str, Any]]) -> float | None:
        variance = _mean(rows, "variance_rungs")
        square = _mean(rows, "square_error")
        if variance is None or not square:
            return None
        return (variance ** 0.5) / (square ** 0.5)

    def _day_clusters(key: str) -> dict[str, tuple[float, float]]:
        clusters: dict[str, list[float]] = defaultdict(lambda: [0.0, 0.0])
        for row in scored:
            slot = clusters[row["event_date"]]
            slot[0] += row["weight"] * row[key]
            slot[1] += row["weight"]
        return {day: (slot[0], slot[1]) for day, slot in clusters.items()}

    # ---- layer 1: point forecast --------------------------------------
    bias = _mean(scored, "error")
    mae = _mean(scored, "abs_error")
    rmse = (_mean(scored, "square_error") or 0.0) ** 0.5
    bias_c = _mean(scored, "error_c")
    mae_c = _mean(scored, "abs_error_c")
    rmse_c = (_mean(scored, "square_error_c") or 0.0) ** 0.5
    point_health = _worst([
        _grade(abs(bias) if bias is not None else None, "bias_rungs"),
        _grade(mae, "mae_rungs"),
    ])

    # ---- layer 2: probability -----------------------------------------
    crps_skill = _skill(scored, "crps")
    brier_skill = _skill(scored, "brier")
    total_weight = sum(row["weight"] for row in scored)
    pit_bins = [
        sum(row["weight"] * row["pit_bins"][index] for row in scored)
        / total_weight
        for index in range(PIT_BIN_COUNT)
    ]
    pit_deviation = max(
        abs(value - 1.0 / PIT_BIN_COUNT) for value in pit_bins
    )
    probability_health = _worst([
        _grade(crps_skill, "crps_skill", higher_better=True),
        _grade(brier_skill, "brier_skill", higher_better=True),
        _grade(pit_deviation, "pit_deviation"),
    ])

    # ---- layer 3: calibration -----------------------------------------
    decomposition = _reliability_decomposition(reliability_input)
    ece = decomposition["ece"]
    # ECE alone hides the shape.  Four fifths of all (rung, day) pairs sit in
    # the 0-10% bin, where the gap is tiny, so a weighted average stays small
    # even when every confident forecast is off by ten points.  The worst
    # well-populated bin is what says whether a number can be acted on.
    # ``n`` is summed weight: 100 station-day-lead rungs, not 100 rows.
    populated = [
        row for row in decomposition["bins"] if float(row["n"]) >= 100
    ]
    conditional_gap = max(
        (abs(row["promised"] - row["happened"]) for row in populated),
        default=None,
    )
    conditional_signed = None
    if populated:
        worst = max(
            populated, key=lambda row: abs(row["promised"] - row["happened"])
        )
        conditional_signed = worst["happened"] - worst["promised"]
    calibration_health = _worst([
        _grade(ece, "ece"),
        _grade(conditional_gap, "conditional_gap"),
    ])
    # Interval coverage: empirical against nominal per level, the most
    # operational of the three calibration diagnostics.  Diagnostic only --
    # no lamp reads it.
    interval_coverage = [
        {
            "nominal": level,
            "empirical": _mean(scored, f"coverage_{round(level * 100)}"),
            "ci_half_width": _cluster_bootstrap_half_width(
                _day_clusters(f"coverage_{round(level * 100)}")
            ),
        }
        for level in COVERAGE_LEVELS
    ]

    # ---- layer 5: sharpness (read against realised error) --------------
    width_rungs = (_mean(scored, "variance_rungs") or 0.0) ** 0.5
    width_c = (_mean(scored, "variance_c") or 0.0) ** 0.5
    spread_skill = _width_ratio(scored)
    sharpness_health = _grade(
        abs(spread_skill - 1.0) if spread_skill is not None else None,
        "spread_skill",
    )

    # ---- layer 6: stability --------------------------------------------
    mae_ci = _cluster_bootstrap_half_width(_day_clusters("abs_error"))
    crps_ci = _cluster_bootstrap_half_width(_day_clusters("crps"))
    ci_relative = None
    if mae_ci is not None and mae:
        ci_relative = mae_ci / mae
    stability_health = _grade(ci_relative, "ci_relative")

    rows = []
    order = {name: index for index, (name, _label) in enumerate(LEAD_LABELS)}
    by_lead: dict[str, list[dict[str, Any]]] = defaultdict(list)
    for row in scored:
        by_lead[row["lead"]].append(row)
    for lead in sorted(by_lead, key=lambda name: order.get(name, 9)):
        group = by_lead[lead]
        group_bias = _mean(group, "error")
        group_mae = _mean(group, "abs_error")
        group_rmse = (_mean(group, "square_error") or 0.0) ** 0.5
        group_ratio = _width_ratio(group)
        group_crps_skill = _skill(group, "crps")
        rows.append({
            "lead_bucket": lead,
            "lead_label": dict(LEAD_LABELS).get(lead, lead),
            "station_days": len({
                (row["station"], row["event_date"]) for row in group
            }),
            "bias_rungs": group_bias,
            "mae_rungs": group_mae,
            "rmse_rungs": group_rmse,
            "bias_c": _mean(group, "error_c"),
            "mae_c": _mean(group, "abs_error_c"),
            "crps_skill": group_crps_skill,
            "brier_skill": _skill(group, "brier"),
            "spread_skill": group_ratio,
            "coverage": {
                str(round(level * 100)): _mean(
                    group, f"coverage_{round(level * 100)}"
                )
                for level in COVERAGE_LEVELS
            },
            "bias_health": _grade(
                abs(group_bias) if group_bias is not None else None,
                "bias_rungs",
            ),
            "mae_health": _grade(group_mae, "mae_rungs"),
            "crps_health": _grade(
                group_crps_skill, "crps_skill", higher_better=True
            ),
            "spread_health": _grade(
                abs(group_ratio - 1.0) if group_ratio is not None else None,
                "spread_skill",
            ),
        })

    fusion = _collect_fusion_layer(conn)
    layers = [
        {
            "key": "point",
            "name": "点预测",
            "question": "中心到底准不准",
            "health": point_health,
            "verdict": _point_verdict(bias, mae),
            "detail": (
                f"偏差 {bias:+.2f} 档（{bias_c:+.2f}°C） · "
                f"平均误差 {mae:.2f} 档（{mae_c:.2f}°C） · "
                f"均方根 {rmse:.2f} 档（{rmse_c:.2f}°C）"
            ) if bias is not None and mae is not None else "证据不足",
        },
        {
            "key": "probability",
            "name": "概率预测",
            "question": "概率说得准不准",
            "health": probability_health,
            "verdict": _probability_verdict(crps_skill, pit_deviation),
            "detail": (
                f"CRPS 比气候好 {crps_skill:.0%} · "
                f"Brier 好 {brier_skill:.0%} · "
                f"PIT 最大偏离 {pit_deviation:.1%}"
            ) if crps_skill is not None and brier_skill is not None
            else "证据不足",
        },
        {
            "key": "calibration",
            "name": "校准",
            "question": "说 70% 是不是真的 70%",
            "health": calibration_health,
            "verdict": _calibration_verdict(
                decomposition, conditional_gap, conditional_signed
            ),
            "detail": (
                f"整体 ECE {ece:.1%} · 最差分箱偏离 {conditional_gap:.1%} · "
                f"分辨力 {decomposition['resolution']:.4f}"
            ) if ece is not None and conditional_gap is not None
            else "证据不足",
        },
        {
            "key": "fusion",
            "name": "模型融合",
            "question": "几家模型的权重分对了吗",
            "health": fusion["health"],
            "verdict": fusion["verdict"],
            "detail": fusion["detail"],
        },
        {
            "key": "sharpness",
            "name": "分布锐度",
            "question": "分布宽窄配不配它的准度",
            "health": sharpness_health,
            "verdict": _sharpness_verdict(spread_skill),
            "detail": (
                f"宽度 {width_rungs:.2f} 档（{width_c:.2f}°C，方差均值开方） · "
                f"实际误差 {rmse:.2f} 档 · 宽度/误差 {spread_skill:.2f}"
            ) if spread_skill is not None else "证据不足",
        },
        {
            "key": "stability",
            "name": "稳定性",
            "question": "上面这些数字靠不靠得住",
            "health": stability_health,
            "verdict": _stability_verdict(
                ci_relative, len(station_days), len(event_days)
            ),
            "detail": (
                # mae_ci bootstraps `abs_error`, which is rung-denominated so
                # a Celsius and a Fahrenheit book average together honestly.
                # Labelling it °C read one rung as one degree, which is only
                # true on the 34 Celsius stations.
                f"{len(station_days):,} 个站日 · {len(event_days)} 个事件日"
                f" · 按事件日重采样，平均误差 95% 区间 ±{mae_ci:.3f} 档"
                f" · CRPS ±{crps_ci:.3f}"
            ) if mae_ci is not None and crps_ci is not None
            else f"{len(station_days):,} 个站日 · {len(event_days)} 个事件日",
        },
    ]
    if accumulating:
        # Every lamp but fusion reads this sample; fusion reads the served
        # seats and keeps its own colour.  The numbers stay in ``detail`` so
        # the reading is visible while it cannot yet be judged.
        for layer in layers:
            if layer["key"] == "fusion":
                continue
            layer["health"] = "muted"
            layer["verdict"] = (
                f"攒证据 {len(event_days)}/{SCORECARD_MIN_EVENT_DAYS} 个事件日："
                "证据起点（宪章 202：跨版本不清零）之后的已结算样本还不够下结论，下面的数字只作参考"
            )
    # Per event day, for the accuracy board's trend lines (user, 2026-09-18:
    # 把模型准不准、中心、宽度等集中到一个看板…能直观的看各项指标及趋势).  The
    # same weighted rows as every lamp above; nothing re-scored.
    by_day_rows: dict[str, list[dict[str, Any]]] = defaultdict(list)
    for row in scored:
        by_day_rows[row["event_date"]].append(row)
    daily = []
    for day in sorted(by_day_rows):
        group = by_day_rows[day]
        daily.append({
            "event_date": day,
            "station_days": len({row["station"] for row in group}),
            "bias_c": _mean(group, "error_c"),
            "mae_c": _mean(group, "abs_error_c"),
            "bias_rungs": _mean(group, "error"),
            "crps_skill": _skill(group, "crps"),
            "spread_skill": _width_ratio(group),
            "width_c": (_mean(group, "variance_c") or 0.0) ** 0.5,
        })
    metrics = {
        "bias_rungs": bias, "bias_c": bias_c, "mae_rungs": mae, "mae_c": mae_c,
        "rmse_c": rmse_c, "crps_skill": crps_skill, "brier_skill": brier_skill,
        "pit_deviation": pit_deviation, "ece": ece,
        "conditional_gap": conditional_gap, "width_c": width_c,
        "spread_skill": spread_skill, "station_days": len(station_days),
        "event_days": len(event_days),
    }
    return {
        "available": True,
        "overall": _worst([layer["health"] for layer in layers]),
        "layers": layers,
        "metrics": metrics,
        "daily": daily,
        "rows": rows,
        "pit_bins": pit_bins,
        "reliability_bins": decomposition["bins"],
        "interval_coverage": interval_coverage,
        "fusion_pairs": fusion["pairs"],
        "fusion_summary": fusion["summary"],
        "window": window,
        "accumulating": accumulating,
        "min_event_days": SCORECARD_MIN_EVENT_DAYS,
        "row_count": row_count,
        "station_day_count": len(station_days),
        "station_day_lead_count": len(copies),
        "event_day_count": len(event_days),
        "station_count": len(stations),
        "latest_decision_at_utc": latest or None,
        "latest_age_hours": _age_hours(latest or None),
    }


def _point_verdict(bias: float | None, mae: float | None) -> str:
    """All figures in rungs, so Celsius and Fahrenheit books read alike."""

    if bias is None or mae is None:
        return "还没有足够的已结算日可以判断"
    side = "偏热" if bias > 0 else "偏冷"
    if abs(bias) <= 0.3 and mae <= 1.0:
        return f"中心站得住：系统性{side}不到 {abs(bias):.2f} 档，平均误差在一档内"
    if abs(bias) > 0.8:
        return f"中心系统性{side} {abs(bias):.2f} 档，接近整整一档，会持续押错桶"
    if mae > 1.5:
        return f"单日平均差 {mae:.2f} 档，超过一档半，选桶方向常常不对"
    return f"中心略{side} {abs(bias):.2f} 档，平均误差 {mae:.2f} 档，尚在容忍范围"


def _probability_verdict(skill: float | None, pit: float | None) -> str:
    """Worded on the same lines the lamp is graded on.

    The PIT sentence used to start at 8% while the lamp turned amber at 4%,
    so an amber lamp read "分布形状匀称，概率可以直接用" (2026-09-17).
    """

    if skill is None or pit is None:
        return "还没有足够的已结算日可以判断"
    if skill < 0:
        return f"概率比直接用气候还差 {abs(skill):.0%}，这一层目前是负价值"
    pit_good, pit_warn = SCORECARD_THRESHOLDS["pit_deviation"]
    skill_good, _skill_warn = SCORECARD_THRESHOLDS["crps_skill"]
    head = f"比气候基准好 {skill:.0%}"
    if pit > pit_warn:
        return f"{head}，但概率分布形状明显歪（PIT 偏离 {pit:.1%}），尾部不可信"
    if pit > pit_good:
        return f"{head}，但分布形状有点歪（PIT 偏离 {pit:.1%}），尾部别压满"
    if skill < skill_good:
        return f"{head}，优势很薄，接近没有信息"
    return f"{head}，且分布形状匀称，概率可以直接用"


def _calibration_verdict(
    decomposition: dict[str, Any],
    conditional_gap: float | None,
    conditional_signed: float | None,
) -> str:
    """Judged on the worst usable bin, not on the flattering average."""

    ece = decomposition["ece"]
    if ece is None or conditional_gap is None:
        return "还没有足够的已结算日可以判断"
    resolution = decomposition["resolution"] or 0.0
    reliability = decomposition["reliability"] or 0.0
    direction = (
        "说少了" if (conditional_signed or 0.0) > 0 else "说多了"
    )
    points = abs(conditional_signed or 0.0) * 100.0
    if conditional_gap > 0.10:
        return (
            f"能下注的那一段不可信：概率高的时候{direction} "
            f"{points:.0f} 个百分点，整体 ECE {ece:.1%} 是被低概率段拉平的"
        )
    if conditional_gap > 0.05:
        return (
            f"低概率段准，但概率一上来就{direction} {points:.0f} 个百分点"
            f"——真要下注的那一段有系统性偏差"
        )
    if resolution <= reliability:
        return f"偏差小（{ece:.1%}），但分辨力不足——概率总在基准率附近晃"
    return f"说 70% 就真是 70%（各段偏离都在 {conditional_gap:.1%} 内），可以直接用"


def _sharpness_verdict(ratio: float | None) -> str:
    if ratio is None:
        return "还没有足够的已结算日可以判断"
    if abs(ratio - 1.0) <= 0.20:
        return f"宽度配得上准度（宽度/误差 {ratio:.2f}），既不吹牛也不含糊"
    if ratio < 0.55:
        return f"分布太窄（只有实际误差的 {ratio:.2f} 倍）——过度自信，尾部会被打脸"
    if ratio > 1.45:
        return f"分布太宽（实际误差的 {ratio:.2f} 倍）——过于保守，等于没给信息"
    if ratio < 1.0:
        return f"分布偏窄（{ratio:.2f} 倍），可以用但别压满"
    return f"分布偏宽（{ratio:.2f} 倍），信息量打了折扣"


def _stability_verdict(
    relative: float | None, station_days: int, event_days: int
) -> str:
    """Resampled by event day, so it says so in days, not rows."""

    sample = f"{station_days:,} 个站日、{event_days} 个事件日"
    if relative is None:
        return f"只有 {sample}，还不足以按事件日重采样出区间"
    if relative <= 0.15:
        return f"{sample}，整天整天重采样，平均误差区间在数值的 {relative:.0%} 以内，结论稳"
    if relative <= 0.30:
        return f"{sample}，结论大方向可信，但小差距（几个百分点）别当真"
    return f"只有 {sample}，区间比数值本身还宽——上面每个判断都是暂定的"


def _scorecard_salt(conn: sqlite3.Connection) -> str:
    """What the scorecard cache must also expire on.

    ``_section_fingerprint`` hashes only the collector it is handed.  The
    scorecard's arithmetic lives in the helpers it calls, and the sample
    starts at P0's serving anchor, which moves when a version is declared.
    A change to any of them changes what the lamps read.
    """

    sources = "\n".join(
        _loaded_source(function)
        for function in (
            _bucket_order,
            _truth_bucket,
            _grade,
            _worst,
            _prediction_scores,
            _cluster_bootstrap_half_width,
            _reliability_decomposition,
            _scorecard_window,
            _parse_utc,
            _point_verdict,
            _probability_verdict,
            _calibration_verdict,
            _sharpness_verdict,
            _stability_verdict,
            _collect_fusion_layer,
        )
    )
    return "\n".join((
        json.dumps(_scorecard_window(conn), sort_keys=True),
        repr(sorted(SCORECARD_THRESHOLDS.items())),
        repr((SCORECARD_MIN_EVENT_DAYS, SCORECARD_MAX_WINDOW_DAYS,
              PIT_BIN_COUNT)),
        sources,
    ))


def _collect_fusion_layer(conn: sqlite3.Connection) -> dict[str, Any]:
    """Whether each served blend carries the weights production's rule gives.

    Read, not computed (user rulings 2026-10-02 「只读是读后端算出来的」 /
    「新开一个后端读数任务」): the backend board-readings job re-solves every
    served seat from what the SSOT kept, by production's own weighting
    functions (``board_readings.fusion_resolved_seats``), and this grades
    what it wrote -- the distance where the diagonal is recovered exactly,
    the residual correlation as before.  Until the job has written its
    reading the layer reads the stored weights and correlation alone
    (``_fusion_stored_seats``) and grades on the correlation.
    """

    from bayes_basket_target.board_readings import load_reading  # noqa: PLC0415

    reading = load_reading("fusion_resolve")
    if reading is None:
        return _fusion_stored_seats(conn)
    rows = list((reading.get("value") or {}).get("rows") or [])
    unread = int((reading.get("value") or {}).get("unread") or 0)
    correlations = [
        row["max_correlation"] for row in rows
        if row["max_correlation"] is not None
    ]
    if not correlations:
        return {
            "health": "muted",
            "verdict": "还没有两家以上模型同时在座的在役组合",
            "detail": "证据不足",
            "pairs": [],
            "summary": {"served_count": len(rows), "unread_count": unread},
        }
    exact = [
        row for row in rows
        if row["basis"] == "exact" and row["distance"] is not None
    ]
    approximate = [row for row in rows if row not in exact]
    approximate_distances = sorted(
        row["distance"] for row in approximate if row["distance"] is not None
    )
    mean_correlation = sum(correlations) / len(correlations)
    mean_distance = (
        sum(row["distance"] for row in exact) / len(exact) if exact else None
    )
    correlation_health = _grade(mean_correlation, "residual_correlation")
    distance_health = _grade(mean_distance, "weight_distance")
    health = _worst([correlation_health, distance_health])
    if mean_distance is None:
        verdict = (
            f"模型之间残差相关 {mean_correlation:.2f}，"
            "但没有一份在役权重能从存档精确重解，自检做不了"
        )
    elif distance_health != "green":
        verdict = (
            f"在役权重和存档证据重解对不上（平均差 {mean_distance:.1%}）"
            "——先查数据再查解法"
        )
    elif correlation_health == "green":
        verdict = (
            f"在役权重与生产算术重解一致（平均差 {mean_distance:.1%}），"
            f"几家模型残差也互相独立（相关 {mean_correlation:.2f}）"
        )
    else:
        verdict = (
            f"在役权重与生产算术重解一致（平均差 {mean_distance:.1%}）；"
            f"灯色来自模型残差相关 {mean_correlation:.2f}，几家模型在犯相近的错"
        )
    return {
        "health": health,
        "verdict": verdict,
        "detail": (
            f"{len(rows)} 份在役权重 · 精确重解 {len(exact)} 份"
            f" · 平均最大相关 {mean_correlation:.2f}"
            + (f" · 离重解 {mean_distance:.1%}"
               if mean_distance is not None else "")
        ),
        "pairs": sorted(
            exact, key=lambda row: row["distance"], reverse=True
        )[:12],
        "summary": {
            "served_count": len(rows),
            "exact_count": len(exact),
            "unread_count": unread,
            "approximate_by_basis": dict(
                Counter(row["basis"] for row in approximate)
            ),
            "approximate_median_distance": (
                median(approximate_distances)
                if approximate_distances else None
            ),
            "approximate_max_distance": (
                approximate_distances[-1] if approximate_distances else None
            ),
        },
    }



def _fusion_stored_seats(conn: sqlite3.Connection) -> dict[str, Any]:
    """The served blends as stored: each seat's weights and the residual
    correlation its selection evidence kept.

    Read-only (user ruling 2026-10-02 「所有前端都改为只读」).  Until then
    every served seat was re-solved here by production's own weighting
    functions and graded on its distance from the stored weights -- the
    production rule run again on the board, with a member-artifact and an
    evaluation lookup per seat.  The lamp now reads what the evidence
    stored: how alike the seated systems' errors were.
    """

    from bayes_basket_target.board_readings import served_p0_seats  # noqa: PLC0415

    served_rows = [
        (
            seat["station_id"], seat["season_bin"], seat["lead_bucket"],
            seat["run_cycle"], seat["combination_method"],
            seat["selected_weights_json"], seat["correlation_json"],
        )
        for seat in served_p0_seats(conn)
        if int(seat.get("selected_system_count") or 0) > 1
    ]

    rows: list[dict[str, Any]] = []
    unread = 0
    for (
        station, season, lead, cycle, method, weights_json, correlation_json,
    ) in served_rows:
        try:
            served = {
                str(system): float(value)
                for system, value in json.loads(weights_json).items()
            }
            correlation = json.loads(correlation_json)
        except (AttributeError, TypeError, ValueError):
            unread += 1
            continue
        systems = sorted(served)
        if len(systems) < 2 or not isinstance(correlation, dict):
            unread += 1
            continue
        off_diagonal = []
        for left in systems:
            for right in systems:
                if left == right:
                    continue
                try:
                    off_diagonal.append(float(correlation[left][right]))
                except (KeyError, TypeError, ValueError):
                    pass
        parts = str(method or "").split("::")
        kappa = next(
            (part.split("=", 1)[1] for part in parts[1:]
             if part.startswith("stable_pool_kappa=")),
            None,
        )
        rows.append({
            "station_id": str(station),
            "season_bin": str(season),
            "lead_bucket": str(lead),
            "run_cycle": str(cycle),
            "rule": f"稳定池 κ={kappa}" if kappa is not None else parts[0],
            "max_correlation": max(off_diagonal) if off_diagonal else None,
            "served": served,
        })

    correlations = [
        row["max_correlation"] for row in rows
        if row["max_correlation"] is not None
    ]
    if not correlations:
        return {
            "health": "muted",
            "verdict": "还没有两家以上模型同时在座的在役组合",
            "detail": "证据不足",
            "pairs": [],
            "summary": {"served_count": len(rows), "unread_count": unread},
        }
    mean_correlation = sum(correlations) / len(correlations)
    health = _grade(mean_correlation, "residual_correlation")
    verdict = (
        f"几家在座模型的残差互相独立（平均最大相关 {mean_correlation:.2f}），"
        "融合能互相抵消误差"
        if health == "green" else
        f"几家在座模型的残差相关 {mean_correlation:.2f}，在犯相近的错，"
        "融合能抵消的误差有限"
    )
    return {
        "health": health,
        "verdict": verdict,
        "detail": (
            f"{len(rows)} 份在役权重 · 平均最大相关 {mean_correlation:.2f}"
        ),
        "pairs": sorted(
            (row for row in rows if row["max_correlation"] is not None),
            key=lambda row: row["max_correlation"], reverse=True,
        )[:12],
        "summary": {"served_count": len(rows), "unread_count": unread},
    }

def collect_gaps(
    conn: sqlite3.Connection,
    members: list[dict[str, Any]],
    tables: dict[str, Any],
) -> list[dict[str, Any]]:
    """Named holes, each with what it costs and whether it self-heals."""

    gaps = []
    for member in members:
        if member["health"] == "green":
            continue
        gaps.append({
            "severity": "high" if member["health"] == "red" else "medium",
            "what": f"{member['label']} 模型数据{member['note']}",
            "cost": (
                "该模型无法参与融合，少一路独立意见"
                + ("；此源无历史档案，丢一天永久丢一天"
                   if not member["backfillable"] else "")
            ),
            "self_heals": member["backfillable"],
        })
    # A family that arrives daily can still be near-useless to the fit if its
    # archive only goes back a few days -- the weight ramp prices it down and
    # the gate can refuse the combinations it appears in.
    deepest = max((m["training_days"] or 0) for m in members)
    for member in members:
        days = member["training_days"] or 0
        if deepest <= 0 or days >= deepest * 0.5:
            continue
        gaps.append({
            "severity": "medium",
            "what": (
                f"{member['label']} 的训练历史只有 {days} 天，"
                f"最深的同行有 {deepest} 天"
            ),
            "cost": (
                "样本浅的模型权重会被自动调低，参与融合的分量有限；"
                + ("可从公开档案回补" if member["backfillable"]
                   else "此源无历史档案，只能靠今后每天积累")
            ),
            "self_heals": True,
        })
    if tables.get("weight_lag_scopes"):
        gaps.append({
            "severity": "medium",
            "what": (
                (f"{100 * tables['weight_lag_scopes'] / tables['weight_scopes']:.0f}%"
                 f"（{tables['weight_lag_scopes']} / {tables['weight_scopes']}）"
                 if tables.get("weight_scopes") else f"{tables['weight_lag_scopes']} 个")
                + "站×提前量的融合权重落后于偏差订正 3 天以上"
            ),
            "cost": "这些格子的权重仍是旧证据算的，融合比例可能不是当前最优",
            "self_heals": True,
        })
    stations = conn.execute(
        "SELECT COUNT(*) FROM calibration_station_registry"
    ).fetchone()[0]
    # From the capture table: the TAF member rows this used to count stopped
    # being written when that lane was retired (charter 133).
    taf = conn.execute(
        "SELECT COUNT(DISTINCT station_id)"
        " FROM calibration_forward_taf_capture WHERE tx_available=1"
    ).fetchone()[0]
    if taf < stations:
        gaps.append({
            "severity": "low",
            "what": f"{stations} 个站里只有 {taf} 个站的人工预报带温度组",
            "cost": "其余站的 P0-M 确认环节没有人工预报可用，是数据源本身的限制",
            "self_heals": False,
        })
    return gaps


LIVE_STATION_EXCLUSIONS_PATH = (
    ROOT / "config/trading/live_station_exclusions_v1.json"
)


def barred_station_set() -> set[str]:
    """Stations the live lane may not trade -- hand-ruled and automatic.

    One reader on purpose.  The live-readiness panel and the money board's
    bar sides both need this list, and two copies of the same file read is
    how two panels come to disagree about who is barred.
    """

    try:
        doc = json.loads(
            LIVE_STATION_EXCLUSIONS_PATH.read_text(encoding="utf-8")
        )
    except (OSError, ValueError):
        return set()
    return {
        str(row.get("station") or "").strip().upper()
        for key in ("excluded_stations", "auto_excluded_stations")
        for row in (doc.get(key) or [])
        if isinstance(row, dict) and row.get("station")
    }


# What a scope refusal means, for the one surface a person reads it on.
#
# The board printed these codes verbatim, and one of them is actively
# misleading: ``complete_basket_target_not_activated`` reads as "a feature
# is switched off" and means the opposite -- the target-inventory argmax
# chose the no-new-action baseline, which is an economic HOLD by a working
# engine.  On 2026-09-08 it was 11 of one batch's 15 refusals, and it cost
# an hour of misdiagnosis: the code was read as a disabled completion path
# while the engine was in fact declining to buy, on purpose, every time.
#
# Renamed nowhere.  The string is the charter's own spelling for clause 66
# (乙), clause 96 cites it as evidence, a doctrine test binds it to the
# kernel source, and 13,915 decision rows carry it -- so the identifier is
# constitutional and this is a reading fix, not a rename.  The raw codes
# stay untouched in ``blocked_scope_reasons`` for anything that greps.
#
# ``.get(name, name)`` on purpose: an unmapped code shows raw rather than
# being hidden or guessed at.
BLOCKED_SCOPE_REASON_LABELS = {
    "complete_basket_target_not_activated": "经济性持有（不新建仓最优）",
    "complete_basket_candidate_missing": "缺候选腿",
    "complete_basket_delta_not_positive": "增量不为正",
    "delta_v2_support_empty": "无可选支撑窗口",
    "exchange_minimum_lot_unaffordable": "交易所最小手买不起",
    "production_quote_expired": "报价过期",
    "p1_entry_window_not_open": "P1 入场窗未开",
    "preliminary_no_live_p1_pending": "P1 待定（初步）",
    "sizing_clamped_below_authorized_clip": "定量被砍到授权额以下",
    "bundle_rescore_refused": "重评拒绝",
    "support_floor_after_lift": "抬手后支持集地板拒",
    "no_decision_moment": "非决策时刻",
}
# The refusals that are the cycle working, not failing: a scope whose window
# has not opened or that is not at a decision moment, a P1 still pending,
# and a basket the economics chose not to build.  ``_production_health``
# names them but does not light the lamp for them.
BLOCKED_SCOPE_EXPECTED_REASONS = frozenset({
    "p1_entry_window_not_open",
    "no_decision_moment",
    "preliminary_no_live_p1_pending",
    "complete_basket_target_not_activated",
    "complete_basket_delta_not_positive",
})


def _risk_metrics_from_days(
    rows: Sequence[Sequence[Any]], initial_capital_usdc: float
) -> dict[str, Any]:
    """The book as a portfolio: Sharpe against its target, and its cousins.

    ``rows`` are one per event day, oldest first: day, stake, pnl, claimed
    EV, stake-weighted odds, stake-weighted cost, stake-weighted hits, the
    settlement count and the hit count.  Either book can supply them -- the
    live book does, since the 2026-09-16 ruling made the paper ledger a rule
    comparator -- so the arithmetic below exists once.

    One return per event day -- the day's settled P&L over the equity the
    book opened that day with -- which is the series the equity curve is
    actually built from, so the chart and the ratios cannot disagree.
    Annualised at 365, not 252: this book trades every calendar day it has
    a market for, weekends included.

    The honest part is the error bar.  A Sharpe estimated on a handful of
    days is almost pure noise, and the classical standard error says so:
    ``sqrt((1 + S^2/2) / n)`` per period, which annualises by the same
    root-365 the ratio does.  On this book that error bar is several times
    the estimate, so the section leads with the interval and with how many
    days it would take to tell the number from zero -- otherwise a reader
    sees "1.54" beside a target of 2 and thinks the gap is the finding.
    """

    # Claimed EV comes along for the ride: a basket costing C pays 1 when
    # the truth lands inside, so a unit of stake buys 1/C of payout and
    # expects p/C - 1 back.  That is the same ``ev_per_usdc`` the coverage
    # section reports, summed in money instead of averaged per seat, so
    # the board has exactly one definition of EV and not a second one
    # wearing the same name.
    if len(rows) < 3:
        return {"available": False, "days": len(rows)}
    equity = initial_capital_usdc
    series: list[dict[str, Any]] = []
    returns: list[float] = []
    claimed_ev_total = 0.0
    claimed_equity = initial_capital_usdc
    odds_weighted = 0.0
    cost_weighted = 0.0
    hit_weighted = 0.0
    chain_count = 0
    hit_count = 0
    for day, staked, pnl, claimed_ev, odds_w, cost_w, hit_w, n, hits in rows:
        odds_weighted += float(odds_w or 0.0)
        cost_weighted += float(cost_w or 0.0)
        hit_weighted += float(hit_w or 0.0)
        chain_count += int(n or 0)
        hit_count += int(hits or 0)
        opening = equity
        value = float(pnl or 0.0)
        expected = float(claimed_ev or 0.0)
        returns.append(value / opening if opening > 0 else 0.0)
        equity = opening + value
        claimed_ev_total += expected
        claimed_equity += expected
        series.append({
            "event_date": str(day),
            "staked_usdc": round(float(staked or 0.0), 2),
            "pnl_usdc": round(value, 2),
            "claimed_ev_usdc": round(expected, 2),
            "opening_equity_usdc": round(opening, 2),
            "equity_usdc": round(equity, 2),
            "claimed_equity_usdc": round(claimed_equity, 2),
            "return": returns[-1],
        })
    count = len(returns)
    mean = sum(returns) / count
    variance = sum((r - mean) ** 2 for r in returns) / count
    sigma = math.sqrt(variance)
    # Downside deviation against a zero target: the losing days only, and
    # divided by the whole count -- the winning days are not evidence that
    # the downside is small, they are evidence that there is upside.
    downside = math.sqrt(
        sum(min(0.0, r) ** 2 for r in returns) / count
    )
    annual = 365.0
    root = math.sqrt(annual)
    sharpe = (mean / sigma * root) if sigma > 0 else None
    sortino = (mean / downside * root) if downside > 0 else None
    per_period = (mean / sigma) if sigma > 0 else 0.0
    sharpe_se = math.sqrt((1.0 + 0.5 * per_period ** 2) / count) * root
    # How long until the estimate could clear zero at 95%.  Solving
    # 1.96 * se(n) < |S| for n, with se scaling as 1/sqrt(n).
    days_needed = None
    if sharpe not in (None, 0.0):
        days_needed = int(math.ceil(
            (1.96 ** 2) * (1.0 + 0.5 * per_period ** 2) * annual
            / (sharpe ** 2)
        ))
    # The running peak starts at the capital the book opened with, not at
    # its first closing equity.  Seeded from the series instead, a book
    # that lost on day one had that loss excluded from its own drawdown:
    # this one opened at 1000, closed day one at 947.8, and reported -8.2%
    # where the trough is -9.3% below the money that was actually put in.
    # Value at Risk and its conditional cousin, from the empirical tail --
    # no distribution assumed, because fifteen points cannot support one.
    #
    # The honest part is the tail count.  Expected shortfall at 95% asks
    # for the mean of the worst 5% of days; on fifteen days that is the
    # worst 0.75 of a day, which rounds to exactly one observation.  Both
    # the 95% and 90% levels therefore report the same number and it is
    # not an estimate of a tail -- it is the worst day this book has had.
    # A tail needs its own sample: five observations in the tail wants
    # 100 days at 95%, 50 at 90%, 25 at 80%.  So each level is published
    # WITH the count standing behind it, and the section refuses to let a
    # one-observation number wear the same weight as the others.
    ordered = sorted(returns)

    def tail_at(level: float) -> dict[str, Any]:
        wanted = math.floor((1.0 - level) * count)
        size = max(1, wanted)
        tail = ordered[:size]
        return {
            "level": level,
            "tail_days": size,
            "tail_days_wanted": wanted,
            "var": tail[-1],
            "cvar": sum(tail) / size,
            "days_for_five_in_tail": int(math.ceil(5.0 / (1.0 - level))),
        }

    tails = [tail_at(level) for level in (0.95, 0.90, 0.80)]
    daily_ratios = [
        row["pnl_usdc"] / row["claimed_ev_usdc"]
        for row in series if row["claimed_ev_usdc"] > 0
    ]
    window = series[-7:]
    window_claim = sum(row["claimed_ev_usdc"] for row in window)
    trailing_7d = (
        sum(row["pnl_usdc"] for row in window) / window_claim
        if window_claim > 0 else None
    )
    losing = [r for r in returns if r < 0]
    peak = float(initial_capital_usdc)
    max_drawdown = 0.0
    trough_day = ""
    peak_day = ""
    running_peak_day = "开仓前"
    for row in series:
        if row["equity_usdc"] > peak:
            peak = row["equity_usdc"]
            running_peak_day = row["event_date"]
        drop = (row["equity_usdc"] - peak) / peak if peak > 0 else 0.0
        if drop < max_drawdown:
            max_drawdown = drop
            trough_day = row["event_date"]
            peak_day = running_peak_day
    # Least squares on cumulative P&L: the straight line a reader draws by
    # eye, made explicit so the eye is not doing the fitting.
    xs = list(range(1, count + 1))
    ys = [row["equity_usdc"] - initial_capital_usdc for row in series]
    mean_x = sum(xs) / count
    mean_y = sum(ys) / count
    denominator = sum((x - mean_x) ** 2 for x in xs)
    slope = (
        sum((x - mean_x) * (y - mean_y) for x, y in zip(xs, ys)) / denominator
        if denominator else 0.0
    )
    intercept = mean_y - slope * mean_x
    residual = sum(
        (y - (slope * x + intercept)) ** 2 for x, y in zip(xs, ys)
    )
    total_ss = sum((y - mean_y) ** 2 for y in ys)
    total_return = (equity / initial_capital_usdc) - 1.0
    return {
        "available": True,
        "days": count,
        "first_day": series[0]["event_date"],
        "last_day": series[-1]["event_date"],
        "initial_equity_usdc": initial_capital_usdc,
        "final_equity_usdc": round(equity, 2),
        "total_return": total_return,
        "annualised_return_geometric": (
            (equity / initial_capital_usdc) ** (annual / count) - 1.0
            if equity > 0 else None
        ),
        "annualised_return_arithmetic": mean * annual,
        "annualised_volatility": sigma * root,
        "daily_mean_return": mean,
        "daily_volatility": sigma,
        "downside_deviation": downside,
        "sharpe": sharpe,
        "sharpe_target": 2.0,
        "sharpe_standard_error": sharpe_se,
        "sharpe_ci": (
            None if sharpe is None
            else [sharpe - 1.96 * sharpe_se, sharpe + 1.96 * sharpe_se]
        ),
        "days_to_separate_from_zero": days_needed,
        "sortino": sortino,
        # What the book said it would make, against what it made.  Not a
        # forecast score -- the claim is what sized every bet, so a ratio
        # far from 1.0 says the sizing input is wrong, not just the copy.
        "claimed_ev_usdc": claimed_ev_total,
        "total_staked_usdc": sum(row["staked_usdc"] for row in series),
        # (1 - cost) / cost: what a winning USDC pays back on top of itself.
        "odds_mean": (
            odds_weighted / sum(row["staked_usdc"] for row in series)
            if sum(row["staked_usdc"] for row in series) > 0 else None
        ),
        "cost_mean": (
            cost_weighted / sum(row["staked_usdc"] for row in series)
            if sum(row["staked_usdc"] for row in series) > 0 else None
        ),
        # The win rate those odds need just to break even, and what the
        # book actually hit -- the pair that says whether the price was
        # payable at all.
        "realised_win_rate_weighted": (
            hit_weighted / sum(row["staked_usdc"] for row in series)
            if sum(row["staked_usdc"] for row in series) > 0 else None
        ),
        "realised_win_rate": (hit_count / chain_count) if chain_count else None,
        "chain_count": chain_count,
        "breakeven_win_rate": (
            cost_weighted / sum(row["staked_usdc"] for row in series)
            if sum(row["staked_usdc"] for row in series) > 0 else None
        ),
        "claimed_ev_per_usdc": (
            claimed_ev_total / sum(row["staked_usdc"] for row in series)
            if sum(row["staked_usdc"] for row in series) > 0 else None
        ),
        "realised_pnl_usdc": equity - initial_capital_usdc,
        "ev_realisation_ratio": (
            (equity - initial_capital_usdc) / claimed_ev_total
            if claimed_ev_total > 0 else None
        ),
        "days_beating_claim": sum(
            1 for row in series
            if row["pnl_usdc"] >= row["claimed_ev_usdc"]
        ),
        # One ratio cannot answer this.  Money-weighted, a handful of big
        # losing days set the whole number: 0.055x aggregate against 0.343x
        # on the median day, a factor of six apart on the same fifteen days
        # (user challenge, 2026-08-30).  Both are published, plus the
        # trailing window, because they answer different questions -- what
        # happened to the money, what a typical day does, and where it has
        # been lately.  None of the three escapes the sample-size problem
        # the Sharpe tile states.
        "ev_realisation_daily_median": (
            statistics.median(daily_ratios) if daily_ratios else None
        ),
        "ev_realisation_daily_mean": (
            statistics.fmean(daily_ratios) if daily_ratios else None
        ),
        "ev_realisation_trailing_7d": trailing_7d,
        "ev_realisation_daily": daily_ratios,
        "tails": tails,
        "losing_days": len(losing),
        "mean_losing_day": (sum(losing) / len(losing)) if losing else None,
        "worst_day": ordered[0] if ordered else None,
        "worst_day_date": (
            next(
                (row["event_date"] for row in series
                 if abs(row["return"] - ordered[0]) < 1e-12),
                "",
            ) if ordered else ""
        ),
        "max_drawdown": max_drawdown,
        "max_drawdown_peak_day": peak_day,
        "max_drawdown_trough_day": trough_day,
        "trend_slope_usdc_per_day": slope,
        "trend_intercept_usdc": intercept,
        "trend_r_squared": (
            None if total_ss <= 0 else max(0.0, 1.0 - residual / total_ss)
        ),
        "series": series,
    }


# The three ways to average the same nine numbers.  Published together
# because they are three different questions and the book answers them
# differently enough that any one alone reads as the finding: on 2026-09-10
# the claim was 50.5% per chain, 63.5% per USDC and 49.8% per share.
#
# The share column is the one that closes.  Weighting each chain by the
# basket shares it bought makes cost-per-share equal total-money over
# total-shares and realised-EV-per-share equal total-PnL over total-shares,
# so their ratio IS the book's realised return -- the column cannot drift
# from the equity curve without one of them being wrong.  It is the only
# column the page draws (user ruling, 2026-09-13: 不要解释，用数据对比得出结论);
# the other two stay in the payload for the tests that pin them.


def _entry_economics_block(
    rows: list[tuple[Any, ...]],
) -> dict[str, Any] | None:
    """The nine numbers under all three weightings, for one set of chains.

    ``rows`` are settlement rows: stage, claim, hit, intended_hit, cost,
    stake, pnl, event_date.  A row with no recorded basket cost has no
    per-share anything, so it is dropped here and counted by the caller --
    counted rather than silently skipped, because a cost column that
    stopped being written would otherwise read as a smaller book.
    """

    # The same floor the rest of the board reads, from the module that
    # owns it.  A basket costing under a cent is a minimum-tick offer with
    # nothing bid against it -- the ledger itself calls those chains not
    # credible (``chain_credible = chain_cost >= DUST_COST_FLOOR``) and
    # every other section on the page drops them.  Keeping them here made
    # this section the only one counting 249 chains where the daily table
    # counts 239, and seven sub-cent misses moved the per-chain averages
    # more than their 0.25 USDC of stake could ever justify: cost 0.428 ->
    # 0.416, odds 1.34x -> 1.40x, and the plain per-chain odds mean from
    # 5.9x to 14.7x.
    priced = [
        row for row in rows
        if row[4] is not None and float(row[4]) >= DUST_COST_FLOOR
    ]
    if not priced:
        return None
    claim = [float(r[1]) for r in priced]
    hit = [float(r[2]) for r in priced]
    cost = [float(r[4]) for r in priced]
    stake = [float(r[5]) for r in priced]
    pnl = [float(r[6]) for r in priced]
    # The share unit is the basket share the ledger itself prices against:
    # stake / all-in cost, which is expected payout over claimed win
    # probability.  For a basket whose legs hold equal quantity it is the
    # contract count and a hit pays exactly 1.00 of it; for an uneven
    # basket it is a normalised unit and a hit pays a little less, which
    # the section states rather than rounding away.
    shares = [s / c for s, c in zip(stake, cost)]
    profit = [1.0 if p > 0 else 0.0 for p in pnl]
    per_share_pnl = [p / q for p, q in zip(pnl, shares)]
    claimed_edge = [q - c for q, c in zip(claim, cost)]

    def under(weights: list[float]) -> dict[str, Any] | None:
        total = sum(weights)
        if total <= 0:
            return None

        def w(values: list[float]) -> float:
            return sum(a * b for a, b in zip(weights, values)) / total

        def w_over(keep: list[bool], values: list[float]) -> float | None:
            picked = [
                (a, b) for a, b, k in zip(weights, values, keep) if k
            ]
            mass = sum(a for a, _ in picked)
            return (
                sum(a * b for a, b in picked) / mass if mass > 0 else None
            )

        cost_mean = w(cost)
        won = [p > 0 for p in pnl]
        lost = [p < 0 for p in pnl]
        return {
            "claimed_coverage": w(claim),
            "realised_coverage": w(hit),
            "profitable_rate": w(profit),
            # Payout is 1.00 a share, so the win rate that just pays for
            # the basket IS the price of the basket.  Same number as the
            # cost row below, deliberately: two labels, one quantity, and
            # the page says so instead of letting a reader wonder whether
            # they were computed apart and happen to agree.
            "breakeven_hit_rate": cost_mean,
            "cost_per_share": cost_mean,
            "net_odds": (
                (1.0 - cost_mean) / cost_mean if cost_mean > 0 else None
            ),
            "mean_win_per_share": w_over(won, per_share_pnl),
            "mean_loss_per_share": w_over(lost, per_share_pnl),
            "ev_per_share_claimed": w(claimed_edge),
            "ev_per_share_realised": w(per_share_pnl),
            "margin_over_breakeven": w(hit) - cost_mean,
            "realisation_ratio": (
                w(hit) / w(claim) if w(claim) > 0 else None
            ),
        }

    ones = [1.0] * len(priced)
    blocks = {
        "chain": under(ones),
        "stake": under(stake),
        "share": under(shares),
    }
    wins = [p for p in pnl if p > 0]
    losses = [p for p in pnl if p < 0]
    naive_odds = [(1.0 - c) / c for c in cost]
    stake_total = sum(stake)
    hit_payout = sum(
        p + s for p, s, won in zip(pnl, stake, hit) if won > 0
    )
    hit_shares = sum(q for q, won in zip(shares, hit) if won > 0)
    return {
        "chains": len(priced),
        "weightings": blocks,
        # The per-chain money figures.  "平均盈利" in USDC is what a
        # winning chain returned, not a rate, so it has no weighted form
        # worth printing -- the weighted table carries the per-share
        # version of the same pair instead.
        "mean_win_usdc": (sum(wins) / len(wins)) if wins else None,
        "mean_loss_usdc": (sum(losses) / len(losses)) if losses else None,
        "win_count": len(wins),
        "loss_count": len(losses),
        "flat_count": sum(1 for p in pnl if p == 0),
        # A hit that did not pay, and a payer that did not hit.  Both are
        # zero today and the section prints the pair rather than asserting
        # "命中率就是盈利率": they come apart the moment a basket costs
        # more than the 1.00 it can win, and a reader who has been told
        # they are the same number would not look again.
        "hit_not_profitable": sum(
            1 for r, p in zip(priced, pnl) if float(r[2]) > 0 and p <= 0
        ),
        "profitable_not_hit": sum(
            1 for r, p in zip(priced, pnl) if float(r[2]) <= 0 and p > 0
        ),
        "intended_coverage": (
            sum(float(r[3]) for r in priced if r[3] is not None)
            / sum(1 for r in priced if r[3] is not None)
            if any(r[3] is not None for r in priced) else None
        ),
        # The average a reader would compute by hand, and why it is not on
        # a tile: (1-c)/c is convex, and 27 chains priced under five cents
        # drag the plain per-chain mean to 14.7x against a book whose
        # money actually bought 1.5x.  Published WITH its own maximum so
        # the number is visibly an artefact rather than a disagreement.
        "net_odds_chain_naive": (
            sum(naive_odds) / len(naive_odds) if naive_odds else None
        ),
        "net_odds_max": max(naive_odds) if naive_odds else None,
        "cheap_chains": sum(1 for c in cost if c < 0.05),
        "stake_usdc": stake_total,
        "shares": sum(shares),
        "pnl_usdc": sum(pnl),
        "roi": (sum(pnl) / stake_total) if stake_total > 0 else None,
        # What a hit actually pays for one of those shares.  Exactly 1.00
        # when the basket's legs hold equal quantity; a little under when
        # they do not, because the share is normalised on EXPECTED payout
        # and the winning leg may be the smaller one.  Printed so the
        # "每股" unit is not read as a contract it is not.
        "hit_pays_per_share": (
            hit_payout / hit_shares if hit_shares > 0 else None
        ),
    }


def _entry_economics_from_rows(
    rows: Sequence[Sequence[Any]],
) -> dict[str, Any]:
    """The nine numbers one entry is made of, off the settled book.

    ``rows`` are settlement rows -- stage, claim, hit, intended_hit, cost,
    stake, pnl, event_date -- from whichever book is being read.  Since the
    2026-09-16 ruling that is the live book (``live_book.settlement_rows``);
    the arithmetic is written once so the two books cannot drift apart.

    The board already carries most of these one at a time, scattered: the
    claim lives in the coverage section, the hit rate in the basket
    section, the odds and the break-even rate in the portfolio tiles.
    Read apart they answer nothing -- a 41% hit rate is a disaster against
    a 30-cent basket and a gift against a 50-cent one -- so this section
    puts the whole bet in one place: what the model said it covered, what
    it actually covered, what the coverage had to be to pay for itself,
    and what a share cost and returned.

    Every number here is per SETTLED CHAIN, one chain per station-day, and
    the coverage pair is the HELD basket both times: ``claimed_win_
    probability`` is the served probability summed over the buckets the
    chain ended up holding, and ``hit`` is whether the truth landed in one
    of those.  The chosen-basket hit rate is a different set and is
    published beside it, never in its place -- 2026-09-08 measured 60.7%
    chosen against 39.8% held, and the twenty-point gap is legs the
    ladder posted and the market never sold.
    """

    if not rows:
        # Distinguishable from a book that lost everything.
        return {"available": False, "reason": "还没有已结算的仓位",
                "chains": 0}
    overall = _entry_economics_block(rows)
    if overall is None:
        return {"available": False, "reason": "结算行里没有篮子成本",
                "chains": len(rows)}
    stages: list[dict[str, Any]] = []
    for stage in ("P0", "P0-M", "P1"):
        block = _entry_economics_block(
            [r for r in rows if str(r[0]) == stage]
        )
        if block is not None:
            stages.append({"stage": stage, **block})
    days = sorted(str(r[7]) for r in rows)
    return {
        "available": True,
        "first_day": days[0],
        "last_day": days[-1],
        "settled_rows": len(rows),
        "dust_cost_floor": DUST_COST_FLOOR,
        "cost_missing": sum(1 for r in rows if r[4] is None),
        "dust_excluded": sum(
            1 for r in rows
            if r[4] is not None and float(r[4]) < DUST_COST_FLOOR
        ),
        "dust_excluded_stake_usdc": sum(
            float(r[5]) for r in rows
            if r[4] is not None and float(r[4]) < DUST_COST_FLOOR
        ),
        # Published so the two totals on this page can be added back
        # together instead of read as a contradiction: the equity curve is
        # the whole account, every USDC that moved, and this section --
        # like the daily table and the coverage strip -- is the measurable
        # book.  The difference is exactly this.
        "dust_excluded_pnl_usdc": sum(
            float(r[6]) for r in rows
            if r[4] is not None and float(r[4]) < DUST_COST_FLOOR
        ),
        **overall,
        "by_stage": stages,
    }


def _live_runtime_config() -> tuple[Path, dict[str, Any]]:
    """The runtime contract the execution mode selects, and its path.

    The rule production itself follows (weather_basket_yes_daemon.py, and
    the budget read in production_worker.py): the live file in live mode,
    the no-live twin otherwise.  The go-live panel once read the no-live
    file unconditionally and reported live_submit_authorized=false about a
    system whose contract said true; naming the file read is what stops
    that repeating.
    """

    live_mode = _live_execution_mode() == "production_live"
    path = ROOT / "config/bayes_basket_target" / (
        "live_runtime_v1.json" if live_mode else "no_live_runtime_v1.json"
    )
    try:
        return path, json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return path, {}


def collect_live_money(conn: sqlite3.Connection) -> dict[str, Any]:
    """The money board, off the live book (user ruling, 2026-09-16).

    The paper ledger is a rule comparator from that day: it answers whether
    another rule would do better or worse, and it stopped being the account.
    So the board's 总账 / 对比 / 风险 / 曲线 read the live fills, through the
    same two pieces of arithmetic the paper book was read with.

    The capital base is the live budget knob, ``target_remaining_budget_usdc``
    in the runtime contract the execution mode selects (operator ruling, same
    day).  The account has no recorded balance history, so equity, return on
    capital, the annualised return and the percentage drawdown are all
    measured against the budget as it stands now -- a day traded under a
    larger budget reads as a larger return than it was, and the board says
    which number it used.
    """

    book = _render_live_book(conn)
    rows = book["settlements"]
    runtime_path, runtime = _live_runtime_config()
    try:
        capital = float(runtime.get("target_remaining_budget_usdc"))
    except (TypeError, ValueError):
        capital = None
    pending_legs = sum(
        1 for leg in book["legs"]
        if leg["filled_size"] > 0
        and (leg["station_id"], leg["event_date"]) not in book["settled"]
    )
    economics, risk = _live_economics_and_risk(rows, capital)
    # Each lane's own book (user 2026-10-05: 分别按照各个策略统计曲线、对比 ·
    # 按股 · 整本账、风险): the same arithmetic on the settlement rows its
    # legs alone make, against the same capital base so the lanes compare.
    by_lane: dict[str, Any] = {}
    lanes = sorted({live_book.intent_lane(leg["decision_id"]) for leg in book["legs"]
                    if leg["filled_size"] > 0})
    for lane in lanes:
        legs = [leg for leg in book["legs"]
                if live_book.intent_lane(leg["decision_id"]) == lane]
        lane_rows = live_book.settlement_rows(
            legs, book["settled"], None,
            live_book.allocate_sells(legs, book["exit_sells"],
                                     by_intent=book["sold_by_intent"]),
        )
        lane_economics, lane_risk = _live_economics_and_risk(lane_rows, capital)
        by_lane[lane] = {
            "settled_rows": len(lane_rows),
            "pnl_usdc": round(sum(float(r["pnl_usdc"]) for r in lane_rows), 4),
            "stake_usdc": round(sum(float(r["stake_usdc"]) for r in lane_rows), 4),
            "settled_days": len({r["event_date"] for r in lane_rows}),
            "hits": sum(int(r["hit"]) for r in lane_rows),
            "pending_legs": sum(
                1 for leg in legs if leg["filled_size"] > 0
                and (leg["station_id"], leg["event_date"]) not in book["settled"]
            ),
            "economics": lane_economics,
            "risk": lane_risk,
        }
    return {
        "available": bool(rows),
        "reason": "" if rows else "还没有已结算的实盘成交",
        "capital_usdc": capital,
        "capital_source": runtime_path.name,
        "settled_rows": len(rows),
        "pending_legs": pending_legs,
        # Sales on days not settled yet (charter 100 recycle, charter 144
        # exit): realised at the sale, in the settled book from settlement.
        "pending_sales": live_book.pending_sales(book),
        "economics": economics,
        "risk": risk,
        "by_lane": by_lane,
    }


def _live_economics_and_risk(
    rows: list[dict[str, Any]], capital: float | None,
) -> tuple[dict[str, Any], dict[str, Any]]:
    """Entry economics and the day-series risk of one set of settlement rows."""

    economics = _entry_economics_from_rows([
        (r["stage"], r["claimed_win_probability"], r["hit"],
         r["intended_hit"], r["basket_all_in_cost"], r["stake_usdc"],
         r["pnl_usdc"], r["event_date"])
        for r in rows
    ])
    by_day: dict[str, list[float]] = {}
    for r in rows:
        acc = by_day.setdefault(r["event_date"], [0.0] * 8)
        stake = float(r["stake_usdc"])
        cost = r["basket_all_in_cost"]
        claim = r["claimed_win_probability"]
        acc[0] += stake
        acc[1] += float(r["pnl_usdc"])
        # The paper query's CASE WHEN cost > 0, row for row.
        if cost is not None and cost > 0 and claim is not None:
            acc[2] += stake * (claim / cost - 1.0)
        if cost is not None and cost > 0:
            acc[3] += stake * (1.0 - cost) / cost
        if cost is not None:
            acc[4] += stake * cost
        acc[5] += stake * int(r["hit"])
        acc[6] += 1
        acc[7] += int(r["hit"])
    days = [
        (day, acc[0], acc[1], acc[2], acc[3], acc[4], acc[5],
         int(acc[6]), int(acc[7]))
        for day, acc in sorted(by_day.items())
    ]
    if capital is None or capital <= 0:
        risk = {"available": False, "days": len(days),
                "reason": "预算旋钮读不出来，没有本金基数"}
    else:
        risk = _risk_metrics_from_days(days, capital)
    return economics, risk


def collect_live_days(conn: sqlite3.Connection) -> dict[str, Any]:
    """每日统计 and 逐站逐日明细, off the live book (user ruling, 2026-09-16).

    Both tables used to read the paper ledger's seats; the ruling that made
    the ledger a rule comparator moved them to the live fills.  One pass
    builds both, so a day's row and that day's station rows count the same
    legs.

    Two grains, each named where it is used.  A *station-day* is one station
    on one event day, whatever stages it traded; the basket verdicts are
    read at that grain -- 持仓命中 when a filled leg sits on the settled
    bucket, 篮子命中 when any posted leg does, filled or not (user ruling,
    2026-09-14).  A *笔* is one stage of one station-day that filled, the
    settlement row the money board reads; the claim, the hit rate against it
    and the odds are read at that grain, so this table and the board's
    nine numbers agree.
    """

    book = _render_live_book(conn)
    legs = book["legs"]
    rows_by_day: dict[str, list[dict[str, Any]]] = defaultdict(list)
    for row in book["settlements"]:
        rows_by_day[row["event_date"]].append(row)
    legs_by_sd: dict[tuple[str, str], list[dict[str, Any]]] = defaultdict(list)
    for leg in legs:
        legs_by_sd[(leg["station_id"], leg["event_date"])].append(leg)
    slugs = _live_market_slugs(conn, [
        {"station_id": station, "event_date": day}
        for station, day in legs_by_sd
    ])

    # The station-day verdicts are the live book's (``live_book.station_days``),
    # the same records the go-live table counts by station.
    roster: dict[str, list[dict[str, Any]]] = defaultdict(list)
    for entry in live_book.station_days(book):
        station, day = entry["station_id"], entry["event_date"]
        roster[day].append({
            "station_id": station,
            "event_date": day,
            "station_label": STATION_LABELS.get(station, ""),
            "market_slug": slugs.get(f"{station}|{day}", ""),
            **{k: v for k, v in entry.items()
               if k not in ("station_id", "event_date")},
        })

    daily: list[dict[str, Any]] = []
    for day in sorted(roster, reverse=True):
        entries = roster[day]
        rows = rows_by_day.get(day, [])
        by_stage = {stage: 0 for stage in live_book.STAGES}
        for entry in entries:
            for stage, summary in entry["stages"].items():
                by_stage[stage] = by_stage.get(stage, 0) + summary["filled_legs"]
        settled_sd = [e for e in entries if e["settled_bucket"] is not None]
        held_sd = [e for e in settled_sd if e["filled_legs"]]
        claimed = [r for r in rows if r["claimed_win_probability"] is not None]
        costed = [r for r in rows if r["basket_all_in_cost"] is not None]
        settled_stake = sum(r["stake_usdc"] for r in rows)
        pnl = sum(r["pnl_usdc"] for r in rows)
        hit_rate = (
            sum(r["hit"] for r in claimed) / len(claimed) if claimed else None
        )
        claim_mean = (
            sum(r["claimed_win_probability"] for r in claimed) / len(claimed)
            if claimed else None
        )
        # The day's price, stake-weighted, then inverted: the mean of each
        # row's own (1-c)/c is convex and rewards the cheapest basket out of
        # all proportion to its money (14.7x against 1.53x, 2026-09-10).
        cost_stake = sum(r["stake_usdc"] for r in costed)
        cost_mean = (
            sum(r["stake_usdc"] * r["basket_all_in_cost"] for r in costed)
            / cost_stake if cost_stake > 0 else None
        )
        daily.append({
            "event_date": day,
            "stations_posted": len(entries),
            "stations_filled": sum(1 for e in entries if e["filled_legs"]),
            "baskets": len({
                leg["decision_id"] for e in entries
                for leg in legs_by_sd[(e["station_id"], day)]
            }),
            "posted_legs": sum(e["posted_legs"] for e in entries),
            "filled_legs": sum(e["filled_legs"] for e in entries),
            "filled_leg_by_stage": by_stage,
            "staked_usdc": sum(e["staked_usdc"] for e in entries),
            "settled_station_days": len(settled_sd),
            "open_station_days": len(entries) - len(settled_sd),
            "basket_hit_station_days": sum(1 for e in settled_sd if e["basket_hit"]),
            "held_station_days": len(held_sd),
            "held_hit_station_days": sum(1 for e in held_sd if e["held_hit"]),
            "settled_rows": len(rows),
            "hit_rate": hit_rate,
            "claimed_win_probability_mean": claim_mean,
            "calibration_ratio": (
                hit_rate / claim_mean if hit_rate is not None and claim_mean
                else None
            ),
            "odds_mean": (
                (1.0 - cost_mean) / cost_mean if cost_mean else None
            ),
            "settled_staked_usdc": settled_stake,
            "pnl_usdc": pnl if rows else None,
            "roi": (pnl / settled_stake) if settled_stake > 0 else None,
        })
    return {
        "available": bool(legs),
        "daily": daily,
        "roster": {day: roster[day] for day in sorted(roster, reverse=True)},
    }



def _tiebreak_registered_hypotheses(conn: sqlite3.Connection) -> dict[str, Any]:
    """Charter 164's shadow readings: what each registered hypothesis says
    over the whole replay, and over the event days since it was registered.

    The forward window is the one that decides.  A hypothesis measured on
    the sample that suggested it is not evidence -- with 122 candidate cells
    a shuffled label finds a both-halves-confirmed cell every single time,
    and the weaker side of that random cell reaches +24.0% ROI -- so the
    board prints the registration reading as context and the forward reading
    as the answer.
    """

    out: dict[str, Any] = {"available": False, "rows": [], "as_of_date": None}
    try:
        from bayes_basket_target.tiebreak_cell_shadow import (  # noqa: PLC0415
            HYPOTHESIS_TABLE, REPLAY_TABLE, SHADOW_SCHEMA, attach_shadow,
        )
    except Exception:  # noqa: BLE001
        return out
    if not attach_shadow(conn):
        return out
    try:
        as_of = conn.execute(
            f"SELECT MAX(as_of_date) FROM {SHADOW_SCHEMA}.{HYPOTHESIS_TABLE}"
        ).fetchone()[0]
        if not as_of:
            return out
        rows = conn.execute(
            "SELECT hypothesis_id,title,prediction,at_registration,registered_at_utc,"
            " reading_window,n_treatment,n_control,event_days,roi_treatment,roi_control,"
            " contrast,ci_lo,ci_hi,p_at_or_below_zero,p_permutation"
            f" FROM {SHADOW_SCHEMA}.{HYPOTHESIS_TABLE} WHERE as_of_date=?"
            " ORDER BY hypothesis_id, reading_window DESC",
            (str(as_of),),
        ).fetchall()
        replay = conn.execute(
            f"SELECT COUNT(*), COUNT(DISTINCT station_id||event_date),"
            f" COUNT(DISTINCT event_date), MAX(refreshed_at_utc)"
            f" FROM {SHADOW_SCHEMA}.{REPLAY_TABLE}"
        ).fetchone()
    except sqlite3.Error:
        return out
    out.update({
        "available": True, "as_of_date": str(as_of),
        "replayed": int(replay[0] or 0), "station_days": int(replay[1] or 0),
        "event_days": int(replay[2] or 0), "refreshed_at_utc": replay[3],
        "rows": [
            {"hypothesis_id": r[0], "title": r[1], "prediction": r[2],
             "at_registration": r[3], "registered_at_utc": r[4],
             "reading_window": r[5], "n_treatment": r[6], "n_control": r[7],
             "event_days": r[8], "roi_treatment": r[9], "roi_control": r[10],
             "contrast": r[11], "ci_lo": r[12], "ci_hi": r[13],
             "p_at_or_below_zero": r[14], "p_permutation": r[15]}
            for r in rows
        ],
    })
    return out


def collect_tiebreak_lane(conn: sqlite3.Connection) -> dict[str, Any]:
    """「秤砣线」-- the tiebreak lane's own statistics (charter 146).

    User ruling 2026-09-18: 前端增加可自行调整每笔预算和单独的统计.  Three
    reads, each from where the lane itself writes: the lane switches and
    the stake from the operator file; every first decision the lane scored
    from ``tiebreak_lane_evaluation`` (fired or not, with the reason a fired
    one did not send); and the trades from the live book, restricted to the
    lane's own decision rows (``tiebreak_decision_*``), scored against the
    settled bucket exactly as every other live leg is.

    The acceptance the charter names is printed as three conditions, not a
    verdict: realised minus the price actually paid, with a day-clustered
    lower bound above zero, both halves the same sign, and at least thirty
    event days.  ``ask_paid`` keeps its name and is what it always was --
    the filled notional over the filled shares -- but since charter 163 the
    lane rests at bid+1t rather than crossing, so the rows before and after
    2026-09-20 are priced on different sides of the book and are told apart
    by ``rule_version`` (…_spread_v2_1 against …_spread_maker_v2_2).
    """

    lanes = _load_strategy_lanes()
    tiebreak = lanes["lanes"].get("tiebreak") or {}
    out: dict[str, Any] = {
        "available": True,
        "computed_at_utc": _now().isoformat().replace("+00:00", "Z"),
        "settings": {
            "enabled": tiebreak.get("enabled") is True,
            "stake_usdc": tiebreak.get("stake_usdc"),
            "min_market_share_on_model_mode": tiebreak.get(
                "min_market_share_on_model_mode"
            ),
            "first_decision_fresh_seconds": tiebreak.get(
                "first_decision_fresh_seconds"
            ),
            # v2 (user ruling 2026-09-18): the rule the file selects and the
            # band's ceiling; v1 rows stay in the table under their own
            # rule_version.
            "rule": tiebreak.get("rule"),
            "max_market_share_on_model_mode": tiebreak.get(
                "max_market_share_on_model_mode"
            ),
            # v2.1: the model bucket's spread ceiling.
            "max_spread_on_model_mode": tiebreak.get("max_spread_on_model_mode"),
            # v2.3 (charter 175): the ceiling is the rung's own price.
            "max_paid_price": tiebreak.get("max_paid_price"),
            # Charter 229: the stages whose first decision may open.
            "opening_stages": tiebreak.get("opening_stages"),
            "source": lanes.get("source"),
            "updated_at_utc": lanes.get("updated_at_utc"),
        },
        "lanes": {
            name: bool(lane.get("enabled") is True)
            for name, lane in lanes["lanes"].items()
        },
        "evaluations": {"available": False},
        "trades": {"available": False},
    }
    has_eval = conn.execute(
        "SELECT 1 FROM sqlite_master WHERE type='table'"
        " AND name='tiebreak_lane_evaluation'"
    ).fetchone() is not None
    if has_eval:
        total, fired, days, first_at, last_at = conn.execute(
            "SELECT COUNT(*), COALESCE(SUM(fired),0), COUNT(DISTINCT event_date),"
            " MIN(evaluated_at_utc), MAX(evaluated_at_utc)"
            " FROM tiebreak_lane_evaluation"
        ).fetchone()
        refusals = [
            {"refusal": str(r[0] or "sent"), "count": int(r[1]), "fired": int(r[2] or 0)}
            for r in conn.execute(
                "SELECT COALESCE(refusal,''), COUNT(*), SUM(fired)"
                " FROM tiebreak_lane_evaluation GROUP BY COALESCE(refusal,'')"
                " ORDER BY COUNT(*) DESC LIMIT 14"
            )
        ]
        fired_rows = [
            {
                "station_id": r[0], "event_date": r[1], "stage": r[2],
                "model_mode": r[3], "market_mode": r[4],
                "market_share_on_model_mode": r[5],
                "model_mode_share": r[6], "refusal": r[7],
                "order_intent_id": r[8], "evaluated_at_utc": r[9],
            }
            for r in conn.execute(
                "SELECT station_id, event_date, stage, model_mode, market_mode,"
                " market_share_on_model_mode, model_mode_share, refusal,"
                " order_intent_id, evaluated_at_utc"
                " FROM tiebreak_lane_evaluation WHERE fired=1"
                " ORDER BY evaluated_at_utc DESC LIMIT 40"
            )
        ]
        by_rule = [
            {"rule_version": str(r[0] or ""), "evaluated": int(r[1]), "fired": int(r[2] or 0),
             "sent": int(r[3] or 0), "first_at_utc": r[4], "last_at_utc": r[5]}
            for r in conn.execute(
                "SELECT rule_version, COUNT(*), SUM(fired),"
                " SUM(CASE WHEN fired=1 AND refusal IS NULL THEN 1 ELSE 0 END),"
                " MIN(evaluated_at_utc), MAX(evaluated_at_utc)"
                " FROM tiebreak_lane_evaluation GROUP BY rule_version"
                " ORDER BY MIN(evaluated_at_utc)"
            )
        ]
        by_day = [
            {"event_date": r[0], "evaluated": int(r[1]), "fired": int(r[2] or 0),
             "sent": int(r[3] or 0)}
            for r in conn.execute(
                "SELECT event_date, COUNT(*), SUM(fired),"
                " SUM(CASE WHEN fired=1 AND refusal IS NULL THEN 1 ELSE 0 END)"
                " FROM tiebreak_lane_evaluation GROUP BY event_date"
                " ORDER BY event_date DESC LIMIT 21"
            )
        ]
        out["evaluations"] = {
            "available": True, "total": int(total or 0), "fired": int(fired or 0),
            "event_days": int(days or 0), "first_at_utc": first_at,
            "last_at_utc": last_at, "refusals": refusals,
            "fired_rows": fired_rows, "by_day": by_day, "by_rule": by_rule,
        }
    # A station-day can repost several intents.  The evaluation row only
    # points at its latest one, so it cannot label earlier fills.  The
    # decision signature is the immutable rule that minted every intent.
    version_by_decision: dict[str, str] = {}
    for decision_id, details_json in conn.execute(
        "SELECT decision_id, details_json FROM auto_trade_decisions"
        " WHERE decision_id LIKE 'tiebreak_decision_%'"
    ):
        signature = (json.loads(details_json).get("decision_signature") or {})
        version = str(signature.get("rule") or "")
        if not version.startswith("tiebreak_"):
            raise ValueError(f"tiebreak_decision_rule_missing:{decision_id}")
        version_by_decision[str(decision_id)] = version
    book = _render_live_book(conn)
    settled = book.get("settled") or {}
    if "sold_by_intent" not in book:
        raise ValueError("tiebreak_sale_allocation_missing")
    sold_by_intent = book["sold_by_intent"]
    legs = [
        leg for leg in (book.get("legs") or [])
        if str(leg.get("decision_id") or "").startswith("tiebreak_decision_")
    ]
    trades: list[dict[str, Any]] = []
    for leg in legs:
        key = (leg["station_id"], leg["event_date"])
        landed = settled.get(key)
        filled = float(leg.get("filled_size") or 0.0)
        notional = float(leg.get("filled_notional_usdc") or 0.0)
        sold_size, sale_proceeds = sold_by_intent.get(
            str(leg.get("order_intent_id") or ""), (0.0, 0.0)
        )
        hit = (landed[0] == leg["bucket"]) if (landed and filled > 0) else None
        payout = (
            sale_proceeds + (filled - sold_size if hit else 0.0)
            if hit is not None else None
        )
        trades.append({
            "order_intent_id": leg.get("order_intent_id"),
            "station_id": leg["station_id"], "event_date": leg["event_date"],
            "stage": leg.get("stage"), "bucket": leg["bucket"],
            "limit_price": leg.get("limit_price"),
            "requested_size": leg.get("requested_size"),
            "requested_notional_usdc": leg.get("requested_notional_usdc"),
            "filled_size": filled, "filled_notional_usdc": notional,
            "sold_size": sold_size, "sale_proceeds_usdc": sale_proceeds,
            "ask_paid": (notional / filled) if filled > 0 else None,
            "claimed_probability": leg.get("claimed_probability"),
            "state": leg.get("state"), "created_at": leg.get("created_at"),
            "settled_bucket": landed[0] if landed else None,
            "hit": hit, "payout_usdc": payout,
            "pnl_usdc": (payout - notional) if payout is not None else None,
            "rule_version": version_by_decision.get(str(leg.get("decision_id") or "")),
        })
    trades.sort(key=lambda t: (t["event_date"], t["station_id"]), reverse=True)
    filled_rows = [t for t in trades if t["filled_size"] > 0]
    settled_rows = [t for t in filled_rows if t["hit"] is not None]
    stake = sum(t["filled_notional_usdc"] for t in settled_rows)
    payout = sum(t["payout_usdc"] or 0.0 for t in settled_rows)
    shares = sum(t["filled_size"] for t in settled_rows)
    hits = sum(1 for t in settled_rows if t["hit"])
    avg_ask = (stake / shares) if shares > 0 else None
    hit_rate = (hits / len(settled_rows)) if settled_rows else None
    def unit_edge(t: dict[str, Any]) -> float:
        """Cash received per filled share, less its actual paid price."""

        return (t["payout_usdc"] - t["filled_notional_usdc"]) / t["filled_size"]

    def edge_summary(rows: list[dict[str, Any]]) -> tuple[float | None, list[float] | None, dict[str, Any] | None, int]:
        edge_rows = [(unit_edge(t), t["event_date"]) for t in rows]
        edge = (sum(e for e, _d in edge_rows) / len(edge_rows)) if edge_rows else None
        event_days = sorted({d for _e, d in edge_rows})
        ci = None
        if len(edge_rows) >= 5 and len(event_days) >= 3:
            rng = random.Random(146)
            by_day_edges: dict[str, list[float]] = defaultdict(list)
            for e, d in edge_rows:
                by_day_edges[d].append(e)
            draws: list[float] = []
            for _ in range(10000):
                pool = [e for d in (rng.choice(event_days) for _ in event_days)
                        for e in by_day_edges[d]]
                draws.append(sum(pool) / len(pool))
            draws.sort()
            ci = [draws[int(0.05 * len(draws))], draws[int(0.95 * len(draws))]]
        halves = None
        if len(event_days) >= 2:
            cut = event_days[len(event_days) // 2]
            first = [e for e, d in edge_rows if d < cut]
            second = [e for e, d in edge_rows if d >= cut]
            halves = {
                "split_event_date": cut,
                "first": (sum(first) / len(first)) if first else None,
                "second": (sum(second) / len(second)) if second else None,
            }
        return edge, ci, halves, len(event_days)

    edge, ci, halves, event_days = edge_summary(settled_rows)
    # v2.1 (user ruling 2026-09-18): the recorded feature, split the way the
    # reading was -- the market's move on the model's bucket since the
    # station-day's previous decision -- and, per bin, what the lane's own
    # trades realised.  Recorded, never gated on; this is where the forward
    # sample says whether the momentum split holds.
    #
    # The reference point is NOT a market clock, it is the stage schedule.
    # The lane only ever scores a stage's FIRST decision, so the decision
    # before it necessarily belongs to the PREVIOUS stage: 2026-09-20, all
    # 207 rows carrying the feature split 106 P1<-P0-M, 99 P0-M<-P0, 2
    # P1<-P0, and none within a stage.  The two transitions are an order of
    # magnitude apart -- P0-M rows sit a median 47 minutes from their
    # reference and put 10.1% of themselves in the >=3 point bin, P1 rows
    # sit a median 739 minutes out and put 55.6% there -- so the pooled bin
    # "converged >= 3 points" reads, to first order, "this is a P1 row".
    # ``feature_split_by_stage`` therefore holds the transition fixed, and
    # every bin carries its own reference gap so the confound is on the
    # board rather than in a note.  ``population`` scores the model's mode
    # bucket against the market's price on it over EVERY evaluation row of
    # a settled station-day, fired or not: the docstring's promise is that
    # the forward sample is the whole population, and 113 rows say
    # something nine trades cannot.
    feature_split: list[dict[str, Any]] = []
    feature_split_by_stage: list[dict[str, Any]] = []
    if has_eval and any(
        row[1] == "market_move_on_model_mode"
        for row in conn.execute("PRAGMA table_info(tiebreak_lane_evaluation)")
    ):
        by_intent = {t["order_intent_id"]: t for t in trades if t.get("order_intent_id")}
        bins = [
            ("靠拢 ≥3 点", lambda v: v >= 0.03),
            ("靠拢 0–3 点", lambda v: 0.0 <= v < 0.03),
            ("没动或远离", lambda v: v < 0.0),
        ]
        rows_feat = [
            {
                "move": float(r[0]), "fired": r[1], "refusal": r[2],
                "intent": r[3], "spread": r[4], "stage": str(r[5] or ""),
                "gap": (float(r[6]) if r[6] is not None else None),
                "station_id": str(r[7]), "event_date": str(r[8]),
                "model_mode": (str(r[9]) if r[9] is not None else None),
                "price": (float(r[10]) if r[10] is not None else None),
            }
            for r in conn.execute(
                "SELECT market_move_on_model_mode, fired, refusal, order_intent_id,"
                " spread_on_model_mode, stage, prev_gap_minutes, station_id, event_date,"
                " model_mode, market_share_on_model_mode"
                " FROM tiebreak_lane_evaluation WHERE market_move_on_model_mode IS NOT NULL"
            )
        ]
        # The population's own verdict: did the model's mode bucket land, and
        # what was the market charging for it.  Settled buckets come from the
        # book's own resolver (truth lane fallback included), never restated.
        pop_settled = _live_settled_buckets(
            conn, {(r["station_id"], r["event_date"]) for r in rows_feat},
        )
        for row in rows_feat:
            landed = pop_settled.get((row["station_id"], row["event_date"]))
            row["pop_hit"] = (
                int(landed[0] == row["model_mode"])
                if landed and row["model_mode"] is not None else None
            )

        def _bin_stats(sel: list[dict[str, Any]], label: str) -> dict[str, Any]:
            fired_n = sum(1 for r in sel if r["fired"])
            sent_n = sum(1 for r in sel if r["fired"] and r["refusal"] is None)
            settled_t = [
                by_intent[r["intent"]] for r in sel
                if r["intent"] in by_intent and by_intent[r["intent"]].get("hit") is not None
            ]
            hits = sum(1 for t in settled_t if t["hit"])
            shares_t = sum(t["filled_size"] for t in settled_t)
            stake_t = sum(t["filled_notional_usdc"] for t in settled_t)
            gaps = sorted(r["gap"] for r in sel if r["gap"] is not None)
            pop = [r for r in sel if r["pop_hit"] is not None and r["price"] is not None]
            pop_rate = (sum(r["pop_hit"] for r in pop) / len(pop)) if pop else None
            pop_price = (sum(r["price"] for r in pop) / len(pop)) if pop else None
            return {
                "bin": label, "evaluated": len(sel), "fired": fired_n, "sent": sent_n,
                "settled": len(settled_t), "hits": hits,
                "hit_rate": (hits / len(settled_t)) if settled_t else None,
                "avg_ask": (stake_t / shares_t) if shares_t > 0 else None,
                "realised_minus_ask": (
                    sum(unit_edge(t) for t in settled_t) / len(settled_t)
                    if settled_t else None
                ),
                "median_gap_minutes": (gaps[len(gaps) // 2] if gaps else None),
                "stage_mix": {
                    stage: sum(1 for r in sel if r["stage"] == stage)
                    for stage in sorted({r["stage"] for r in sel})
                },
                "population": len(pop), "population_hits": (
                    sum(r["pop_hit"] for r in pop) if pop else 0
                ),
                "population_hit_rate": pop_rate,
                "population_avg_price": pop_price,
                "population_realised_minus_price": (
                    pop_rate - pop_price if pop_rate is not None and pop_price is not None
                    else None
                ),
            }

        for label, test in bins:
            feature_split.append(
                _bin_stats([r for r in rows_feat if test(r["move"])], label),
            )
        feature_split.append({
            "bin": "无上一决策（不可比）", "evaluated": int(conn.execute(
                "SELECT COUNT(*) FROM tiebreak_lane_evaluation"
                " WHERE market_move_on_model_mode IS NULL AND rule_version LIKE '%v2_1'"
            ).fetchone()[0]), "fired": None, "sent": None, "settled": None, "hits": None,
            "hit_rate": None, "avg_ask": None, "realised_minus_ask": None,
            "median_gap_minutes": None, "stage_mix": {}, "population": 0,
            "population_hits": None, "population_hit_rate": None,
            "population_avg_price": None, "population_realised_minus_price": None,
        })
        # The same bins with the stage transition held fixed.  A stage is
        # named by where it arrives, because where it came from is fixed:
        # the previous decision is always the previous stage's.
        for stage in sorted({r["stage"] for r in rows_feat if r["stage"]}):
            in_stage = [r for r in rows_feat if r["stage"] == stage]
            # The stage's own drift.  The recorded move is not centred on
            # zero: between two stages the market's quoted ladder narrows,
            # so the normalised share on ANY bucket tends to rise.
            # 2026-09-20, over the rows whose station-day has settled, the
            # move averages +3.1 points on the rows where the model's mode
            # bucket LOST (+4.0 on P1, +0.6 on P0-M) -- a fixed "+3 points"
            # therefore reads as "above drift" on P0-M and "below drift" on
            # P1, which is how the same bin comes out the opposite sign in
            # the two.  The neutral point is the stage's own median, and the
            # losers' median is where a threshold would have to sit to mean
            # "converged more than the ladder did by itself".
            moves = sorted(r["move"] for r in in_stage)
            losers = sorted(
                r["move"] for r in in_stage
                if r["pop_hit"] is not None and r["pop_hit"] == 0
            )
            neutral = moves[len(moves) // 2] if moves else None
            loser_neutral = losers[len(losers) // 2] if losers else None
            for label, test in bins:
                sel = [r for r in in_stage if test(r["move"])]
                if not sel:
                    continue
                stats = _bin_stats(sel, label)
                stats["stage"] = stage
                stats["stage_median_move"] = neutral
                stats["stage_loser_median_move"] = loser_neutral
                stats["stage_losers"] = len(losers)
                feature_split_by_stage.append(stats)
    # The same three numbers per rule version, so the 09-25 review reads the
    # resting rule on its own sample (charter 163).
    by_version: list[dict[str, Any]] = []
    for version in sorted({str(t.get("rule_version") or "") for t in filled_rows}):
        rows_v = [t for t in filled_rows if str(t.get("rule_version") or "") == version]
        settled_v = [t for t in rows_v if t["hit"] is not None]
        shares_v = sum(t["filled_size"] for t in settled_v)
        stake_v = sum(t["filled_notional_usdc"] for t in settled_v)
        hits_v = sum(1 for t in settled_v if t["hit"])
        by_version.append({
            "rule_version": version or "(未评分)",
            # Every maker rule rests (v2.2 charter 163, v2.3 charter 175).
            "resting": "_maker" in version,
            "filled": len(rows_v), "settled": len(settled_v), "hits": hits_v,
            "event_days": len({t["event_date"] for t in settled_v}),
            "stake_usdc": stake_v,
            "payout_usdc": sum(t["payout_usdc"] or 0.0 for t in settled_v),
            "hit_rate": (hits_v / len(settled_v)) if settled_v else None,
            "avg_price": (stake_v / shares_v) if shares_v > 0 else None,
            "realised_minus_price": (
                sum(unit_edge(t) for t in settled_v) / len(settled_v)
                if settled_v else None
            ),
        })
    from bayes_basket_target.strategy_lanes import opening_stages  # noqa: PLC0415
    from bayes_basket_target.tiebreak_lane import rule_version_for  # noqa: PLC0415

    current_version = rule_version_for(tiebreak.get("rule"))
    current_stages = opening_stages(tiebreak)
    current_rows = [
        t for t in settled_rows
        if t["rule_version"] == current_version and t["stage"] in current_stages
    ]
    current_edge, current_ci, current_halves, current_days = edge_summary(current_rows)
    out["by_rule_version"] = by_version
    out["feature_split"] = feature_split
    out["feature_split_by_stage"] = feature_split_by_stage
    # Charter 164: the registered hypotheses, read off the replay's own file.
    # Nine trades decide nothing and never will; the replay is 388
    # station-days over 37 event days and grows daily.  Absent file, absent
    # section -- the daily job builds it.
    out["registered_hypotheses"] = _tiebreak_registered_hypotheses(conn)
    out["trades"] = {
        "available": True,
        "sent": len(trades), "filled": len(filled_rows),
        "settled": len(settled_rows), "hits": hits,
        "open": len(filled_rows) - len(settled_rows),
        "stake_usdc": stake, "payout_usdc": payout, "pnl_usdc": payout - stake,
        "roi": ((payout - stake) / stake) if stake > 0 else None,
        "avg_ask": avg_ask, "hit_rate": hit_rate,
        "realised_minus_ask": edge, "realised_minus_ask_ci90": ci,
        "halves": halves, "event_days": event_days,
        "acceptance": {
            "rule_version": current_version,
            "opening_stages": sorted(current_stages),
            "settled": len(current_rows),
            "pnl_usdc": sum(t["pnl_usdc"] for t in current_rows),
            "realised_minus_price": current_edge,
            "ci90": current_ci,
            "halves": current_halves,
            "lower_bound_positive": bool(current_ci and current_ci[0] > 0),
            "halves_same_sign": bool(
                current_halves and current_halves["first"] is not None
                and current_halves["second"] is not None
                and (current_halves["first"] > 0) == (current_halves["second"] > 0)
            ),
            "event_days": current_days, "event_days_needed": 30,
        },
        "rows": filled_rows,
    }
    return out


def collect_p1_consensus_lane(conn: sqlite3.Connection) -> dict[str, Any]:
    """同心线 -- the P1 consensus lane's own statistics (charter 203).

    User ruling 2026-09-23 「前端增加新上的策略线的显式」.  Read from where the
    lane writes: its switch and dials from the operator file, every P1
    decision it judged inside the 6-10 h window from
    ``p1_consensus_lane_evaluation`` (fired or not, the four centres on the
    row), and its trades from the live book restricted to its own decision
    rows.

    Two readings exist only here: how often the four centres agreed at all
    (the rule's own base rate, the denominator of every "fired"), and the
    overlap with the tiebreak lane -- the user ruled 「照买，不避让」, so the
    page says how often this lane bought a bucket the tiebreak lane already
    held, and how often a different one.

    The money is read the way the tiebreak lane's is (user ruling 2026-09-24
    「同心线看不到订单和盈亏，做成和秤砣线一样的」): every order the lane sent,
    placed or not, with stake, payout, P&L, realised minus the price paid
    and its day-clustered interval, and the same split by the rule that
    minted the order -- v1 crossed the ask, v2 rests at bid+1t.
    """

    # The rung's life is the venue's floor plus what production signs above
    # it -- production's two numbers, read rather than restated on the page.
    from bayes_basket_target.production import (  # noqa: PLC0415
        GTD_SIGNING_MARGIN_SECONDS,
        VENUE_GTD_MINIMUM_HORIZON_SECONDS,
    )

    lanes = _load_strategy_lanes()
    cfg = lanes["lanes"].get("p1_consensus") or {}
    out: dict[str, Any] = {
        "available": True,
        "settings": {
            "enabled": cfg.get("enabled") is True,
            "stake_usdc": cfg.get("stake_usdc"),
            "rule": cfg.get("rule"),
            "min_remaining_hours": cfg.get("min_remaining_hours"),
            "max_remaining_hours": cfg.get("max_remaining_hours"),
            "min_ask": cfg.get("min_ask"),
            "max_ask": cfg.get("max_ask"),
            "max_paid_price": cfg.get("max_paid_price"),
            "fact_fresh_seconds": cfg.get("fact_fresh_seconds"),
            "max_buys_per_station_day": cfg.get("max_buys_per_station_day"),
            "max_buys_per_bucket": cfg.get("max_buys_per_bucket"),
            "min_minutes_between_buys": cfg.get("min_minutes_between_buys"),
            "resting_horizon_seconds": (
                VENUE_GTD_MINIMUM_HORIZON_SECONDS + GTD_SIGNING_MARGIN_SECONDS
            ),
            "source": lanes.get("source"),
            "updated_at_utc": lanes.get("updated_at_utc"),
        },
        "evaluations": {"available": False},
        "trades": {"available": False},
    }
    table = "p1_consensus_lane_evaluation"
    has_eval = conn.execute(
        "SELECT 1 FROM sqlite_master WHERE type='table' AND name=?", (table,)
    ).fetchone() is not None
    if has_eval:
        total, four, fired, sent, days, first_at, last_at = conn.execute(
            "SELECT COUNT(*), COALESCE(SUM(four_same),0), COALESCE(SUM(fired),0),"
            " SUM(CASE WHEN order_intent_id IS NOT NULL THEN 1 ELSE 0 END),"
            f" COUNT(DISTINCT event_date), MIN(evaluated_at_utc), MAX(evaluated_at_utc) FROM {table}"
        ).fetchone()
        refusals = [
            {"refusal": str(r[0] or "sent"), "count": int(r[1]), "fired": int(r[2] or 0)}
            for r in conn.execute(
                f"SELECT COALESCE(refusal,''), COUNT(*), SUM(fired) FROM {table}"
                " GROUP BY COALESCE(refusal,'') ORDER BY COUNT(*) DESC LIMIT 14"
            )
        ]
        fired_rows = [
            {
                "station_id": r[0], "event_date": r[1], "decision_at_utc": r[2],
                "remaining_hours": r[3], "bucket": r[4], "best_ask": r[5],
                "best_bid": r[6], "market_share": r[7], "model_share": r[8],
                "held_buckets": r[9], "open_order_lane": r[10],
                "open_order_bucket": r[11], "station_day_buys": r[12],
                "refusal": r[13], "order_intent_id": r[14], "fact_age_seconds": r[15],
            }
            for r in conn.execute(
                "SELECT station_id, event_date, decision_at_utc, remaining_hours, market_mode,"
                " best_ask, best_bid, market_share, model_share, held_buckets, open_order_lane,"
                " open_order_bucket, station_day_buys, refusal, order_intent_id, fact_age_seconds"
                f" FROM {table} WHERE fired=1 ORDER BY evaluated_at_utc DESC LIMIT 40"
            )
        ]
        overlap_same = overlap_other = overlap_open = 0
        for r in conn.execute(
            f"SELECT market_mode, held_buckets, open_order_lane FROM {table}"
            " WHERE fired=1 AND order_intent_id IS NOT NULL"
        ):
            held = {b for b in str(r[1] or "").split(",") if b}
            if held and str(r[0]) in held:
                overlap_same += 1
            elif held:
                overlap_other += 1
            if r[2]:
                overlap_open += 1
        by_day = [
            {"event_date": r[0], "evaluated": int(r[1]), "four_same": int(r[2] or 0),
             "fired": int(r[3] or 0), "sent": int(r[4] or 0)}
            for r in conn.execute(
                "SELECT event_date, COUNT(*), SUM(four_same), SUM(fired),"
                " SUM(CASE WHEN order_intent_id IS NOT NULL THEN 1 ELSE 0 END)"
                f" FROM {table} GROUP BY event_date ORDER BY event_date DESC LIMIT 21"
            )
        ]
        by_rule = [
            {"rule_version": str(r[0] or ""), "evaluated": int(r[1]), "fired": int(r[2] or 0),
             "sent": int(r[3] or 0), "first_at_utc": r[4], "last_at_utc": r[5]}
            for r in conn.execute(
                "SELECT rule_version, COUNT(*), SUM(fired),"
                " SUM(CASE WHEN order_intent_id IS NOT NULL THEN 1 ELSE 0 END),"
                " MIN(evaluated_at_utc), MAX(evaluated_at_utc)"
                f" FROM {table} GROUP BY rule_version ORDER BY MIN(evaluated_at_utc)"
            )
        ]
        out["evaluations"] = {
            "available": True, "total": int(total or 0), "four_same": int(four or 0),
            "fired": int(fired or 0), "sent": int(sent or 0), "event_days": int(days or 0),
            "first_at_utc": first_at, "last_at_utc": last_at, "refusals": refusals,
            "fired_rows": fired_rows, "by_day": by_day, "by_rule": by_rule,
            "overlap_tiebreak_same_bucket": overlap_same,
            "overlap_tiebreak_other_bucket": overlap_other,
            "overlap_open_order": overlap_open,
        }
    book = _render_live_book(conn)
    settled = book.get("settled") or {}
    legs = [
        leg for leg in (book.get("legs") or [])
        if str(leg.get("decision_id") or "").startswith("p1_consensus_decision_")
    ]
    # Which rule minted each order, off the intent itself: a v2 repost
    # rewrites its evaluation row's order_intent_id in place, so the table
    # names only the newest of a station-day's intents.  v1 crossed the ask
    # (FOK), v2 rests at bid+1t (GTD) -- two strategies priced on two sides
    # of the book, scored apart the way the tiebreak lane's are (charter
    # 163).  ``not_placed`` is why an order never reached the book: the
    # evaluation row's own send refusal where it still names this intent,
    # else the reconciliation's blocking reason.
    minted: dict[str, tuple[str, str, str]] = {}
    ids = [str(leg.get("order_intent_id") or "") for leg in legs]
    for start in range(0, len(ids), 500):
        chunk = ids[start:start + 500]
        for r in conn.execute(
            "SELECT i.order_intent_id, json_extract(i.intent_json,'$.rule'),"
            " json_extract(i.intent_json,'$.order_type'), COALESCE(r.blocking_reason,'')"
            " FROM basket_target_order_intents i"
            " LEFT JOIN basket_target_order_reconciliations r"
            "   ON r.order_intent_id=i.order_intent_id"
            f" WHERE i.order_intent_id IN ({','.join('?' * len(chunk))})",
            chunk,
        ):
            minted[str(r[0])] = (str(r[1] or ""), str(r[2] or ""), str(r[3] or ""))
    send_refusal: dict[str, str] = {}
    if has_eval:
        send_refusal = {
            str(r[0]): str(r[1])
            for r in conn.execute(
                f"SELECT order_intent_id, refusal FROM {table}"
                " WHERE order_intent_id IS NOT NULL AND refusal LIKE 'send:%'"
            )
        }
    trades: list[dict[str, Any]] = []
    for leg in legs:
        landed = settled.get((leg["station_id"], leg["event_date"]))
        filled = float(leg.get("filled_size") or 0.0)
        notional = float(leg.get("filled_notional_usdc") or 0.0)
        hit = (landed[0] == leg["bucket"]) if (landed and filled > 0) else None
        payout = filled if hit else (0.0 if hit is False else None)
        intent_id = str(leg.get("order_intent_id") or "")
        rule, order_type, blocking = minted.get(intent_id, ("", "", ""))
        state = str(leg.get("state") or "")
        trades.append({
            "order_intent_id": leg.get("order_intent_id"),
            "station_id": leg["station_id"], "event_date": leg["event_date"],
            "stage": leg.get("stage"), "bucket": leg["bucket"],
            "limit_price": leg.get("limit_price"),
            "requested_size": leg.get("requested_size"),
            "requested_notional_usdc": leg.get("requested_notional_usdc"),
            "filled_size": filled, "filled_notional_usdc": notional,
            "ask_paid": (notional / filled) if filled > 0 else None,
            "claimed_probability": leg.get("claimed_probability"),
            "state": state, "created_at": leg.get("created_at"),
            "order_type": order_type or None,
            "not_placed": (
                send_refusal.get(intent_id) or blocking or None
                if state == "failed" else None
            ),
            "settled_bucket": landed[0] if landed else None,
            "hit": hit, "payout_usdc": payout,
            "pnl_usdc": (payout - notional) if payout is not None else None,
            "rule_version": rule or None,
        })
    trades.sort(key=lambda t: (t["event_date"], str(t["created_at"] or ""), t["station_id"]), reverse=True)
    filled_rows = [t for t in trades if t["filled_size"] > 0]
    settled_rows = [t for t in filled_rows if t["hit"] is not None]
    stake_sum = sum(t["filled_notional_usdc"] for t in settled_rows)
    payout_sum = sum(t["payout_usdc"] or 0.0 for t in settled_rows)
    shares = sum(t["filled_size"] for t in settled_rows)
    hits = sum(1 for t in settled_rows if t["hit"])
    edge_rows = [
        ((1.0 if t["hit"] else 0.0) - (t["ask_paid"] or 0.0), t["event_date"])
        for t in settled_rows if t["ask_paid"] is not None
    ]
    edge = (sum(e for e, _d in edge_rows) / len(edge_rows)) if edge_rows else None
    ci = None
    event_days = sorted({t["event_date"] for t in settled_rows})
    if len(edge_rows) >= 5 and len(event_days) >= 3:
        import random as _random  # noqa: PLC0415

        rng = _random.Random(203)
        by_day_edges: dict[str, list[float]] = defaultdict(list)
        for e, d in edge_rows:
            by_day_edges[d].append(e)
        days_list = list(by_day_edges)
        draws: list[float] = []
        for _ in range(500):
            picked = [rng.choice(days_list) for _ in days_list]
            pool = [e for d in picked for e in by_day_edges[d]]
            draws.append(sum(pool) / len(pool))
        draws.sort()
        ci = [draws[int(0.05 * len(draws))], draws[int(0.95 * len(draws))]]
    halves = None
    if len(event_days) >= 2:
        cut = event_days[len(event_days) // 2]
        first = [e for e, d in edge_rows if d < cut]
        second = [e for e, d in edge_rows if d >= cut]
        halves = {
            "split_event_date": cut,
            "first": (sum(first) / len(first)) if first else None,
            "second": (sum(second) / len(second)) if second else None,
        }
    by_version: list[dict[str, Any]] = []
    for version in sorted({str(t.get("rule_version") or "") for t in trades}):
        rows_v = [t for t in trades if str(t.get("rule_version") or "") == version]
        filled_v = [t for t in rows_v if t["filled_size"] > 0]
        settled_v = [t for t in filled_v if t["hit"] is not None]
        shares_v = sum(t["filled_size"] for t in settled_v)
        stake_v = sum(t["filled_notional_usdc"] for t in settled_v)
        hits_v = sum(1 for t in settled_v if t["hit"])
        by_version.append({
            "rule_version": version or "(未记规则)",
            "resting": any(t.get("order_type") == "GTD" for t in rows_v),
            "sent": len(rows_v),
            "not_placed": sum(1 for t in rows_v if t["state"] == "failed"),
            "filled": len(filled_v), "settled": len(settled_v), "hits": hits_v,
            "event_days": len({t["event_date"] for t in settled_v}),
            "stake_usdc": stake_v,
            "payout_usdc": sum(t["payout_usdc"] or 0.0 for t in settled_v),
            "hit_rate": (hits_v / len(settled_v)) if settled_v else None,
            "avg_price": (stake_v / shares_v) if shares_v > 0 else None,
            "realised_minus_price": (
                (hits_v / len(settled_v)) - (stake_v / shares_v)
                if settled_v and shares_v > 0 else None
            ),
        })
    out["by_rule_version"] = by_version
    out["trades"] = {
        "available": True,
        "rows": trades[:60],
        "count": len(trades),
        "sent": len(trades),
        "not_placed": sum(1 for t in trades if t["state"] == "failed"),
        "filled": len(filled_rows),
        "open": len(filled_rows) - len(settled_rows),
        "settled": len(settled_rows),
        "event_days": len(event_days),
        "stake_usdc": stake_sum,
        "payout_usdc": payout_sum,
        "pnl_usdc": payout_sum - stake_sum,
        "roi": ((payout_sum - stake_sum) / stake_sum) if stake_sum > 0 else None,
        "pnl_per_dollar": ((payout_sum - stake_sum) / stake_sum) if stake_sum > 0 else None,
        "avg_ask": (stake_sum / shares) if shares > 0 else None,
        "hits": hits,
        "hit_rate": (hits / len(settled_rows)) if settled_rows else None,
        "realised_minus_ask": edge, "realised_minus_ask_ci90": ci,
        "halves": halves,
    }
    return out



def collect_tail_short_lane(conn: sqlite3.Connection) -> dict[str, Any]:
    """H1 readout from its evaluation, intent and reconciliation lineage."""

    lanes = _load_strategy_lanes()
    cfg = lanes["lanes"].get("tail_short") or {}
    out: dict[str, Any] = {
        "available": True,
        "settings": {k: cfg.get(k) for k in (
            "enabled", "rule", "opening_stages", "min_hours_to_settlement",
            "max_market_price", "min_rungs_from_mode", "min_yes_bid",
            "stake_usdc", "max_legs_per_station_day", "max_daily_cost_usdc",
            "send_book_fresh_seconds",
        )},
        "evaluations": {"available": False},
        "trades": {"available": False},
    }
    table = "tail_short_lane_evaluation"
    if not _table_exists(conn, table):
        return out
    total, sent, first_at, last_at = conn.execute(
        f"SELECT COUNT(*),COALESCE(SUM(sent),0),MIN(evaluated_at_utc),"
        f" MAX(evaluated_at_utc) FROM {table}"
    ).fetchone()
    refusals = [
        {"reason": str(reason or "sent"), "count": int(count)}
        for reason, count in conn.execute(
            f"SELECT refusal,COUNT(*) FROM {table} GROUP BY refusal"
            " ORDER BY COUNT(*) DESC LIMIT 15"
        )
    ]
    recent = [
        {"station_id": r[0], "event_date": r[1], "bucket": r[2],
         "yes_bid": r[3], "market_q": r[4], "rungs_from_mode": r[5],
         "refusal": r[6], "evaluated_at_utc": r[7]}
        for r in conn.execute(
            f"SELECT station_id,event_date,bucket,yes_bid,market_q,"
            f" rungs_from_mode,refusal,evaluated_at_utc FROM {table}"
            " ORDER BY evaluated_at_utc DESC LIMIT 30"
        )
    ]
    out["evaluations"] = {
        "available": True, "total": int(total), "sent": int(sent),
        "first_at_utc": first_at, "last_at_utc": last_at,
        "refusals": refusals, "recent": recent,
    }
    if not all(_table_exists(conn, t) for t in (
        "basket_target_order_intents", "basket_target_order_reconciliations",
        "basket_target_execution_cycles",
    )):
        return out
    orders = conn.execute(
        f"SELECT e.station_id,e.event_date,e.bucket,e.yes_bid,e.market_q,"
        " e.rungs_from_mode,e.book_source,e.book_age_seconds,"
        " i.order_intent_id,i.limit_price,i.requested_size,i.state,i.created_at,"
        " COALESCE(r.filled_size,0),COALESCE(r.filled_notional_usdc,0),"
        " r.exchange_order_id,r.state,i.token_id,e.sent"
        f" FROM {table} e"
        " JOIN basket_target_order_intents i ON i.order_intent_id=e.order_intent_id"
        " LEFT JOIN basket_target_order_reconciliations r"
        " ON r.order_intent_id=i.order_intent_id"
        " WHERE i.live_submit_authorized=1 AND i.side='NO' AND i.order_action='BUY'"
        " ORDER BY i.created_at DESC"
    ).fetchall()
    # A recycle sell can close a NO position before settlement.  Attribute a
    # shared token's proceeds in proportion to each buy's filled shares.
    no_flows = conn.execute(
        "SELECT c.station_id,c.event_date,i.bucket,i.token_id,i.order_action,"
        " SUM(r.filled_size),SUM(r.filled_notional_usdc)"
        " FROM basket_target_order_intents i"
        " JOIN basket_target_execution_cycles c ON c.cycle_id=i.cycle_id"
        " JOIN basket_target_order_reconciliations r ON r.order_intent_id=i.order_intent_id"
        " WHERE i.live_submit_authorized=1 AND i.side='NO'"
        " AND r.state IN ('resolved_filled','resolved_partial') AND r.filled_size>0"
        " GROUP BY c.station_id,c.event_date,i.bucket,i.token_id,i.order_action"
    ).fetchall()
    flows: dict[tuple[str, str, str, str], dict[str, float]] = {}
    for station, day, bucket, token, action, shares, amount in no_flows:
        slot = flows.setdefault((str(station), str(day), str(bucket), str(token)), {})
        slot[str(action)] = float(shares or 0.0)
        slot[str(action) + "_amount"] = float(amount or 0.0)
    h1_tokens = {str(r[17]) for r in orders}
    recycle_sells = [
        {"order_intent_id": str(intent), "token_id": str(token),
         "state": str(state), "reconciliation_state": str(recon or ""),
         "exchange_order_id": str(exchange_id or ""),
         "filled_size": float(filled or 0.0)}
        for intent, token, state, recon, exchange_id, filled in conn.execute(
            "SELECT i.order_intent_id,i.token_id,i.state,r.state,r.exchange_order_id,"
            " COALESCE(r.filled_size,0)"
            " FROM basket_target_order_intents i"
            " LEFT JOIN basket_target_order_reconciliations r"
            " ON r.order_intent_id=i.order_intent_id"
            " WHERE i.side='NO' AND i.order_action='SELL'"
            " AND i.live_submit_authorized=1 AND i.order_intent_id LIKE 'recycle998_%'"
        )
        if str(token) in h1_tokens
    ]
    uncertain_sale_tokens = {
        r["token_id"] for r in recycle_sells
        if r["state"] == "reconcile_required"
        or (r["filled_size"] > 0 and r["reconciliation_state"] not in (
            "resolved_filled", "resolved_partial"
        ))
    }
    settled = dict(_render_live_book(conn).get("settled") or {})
    # The common live book starts from decision-backed legs.  H1's own
    # decision id has no auto_trade_decisions row, so ask the same canonical
    # settlement resolver for H1 scopes the book did not already cover.
    h1_scopes = {(str(r[0]), str(r[1])) for r in orders}
    settled.update(live_book.settled_buckets(conn, h1_scopes - set(settled)))
    trades = []
    for r in orders:
        station, day, bucket, token = str(r[0]), str(r[1]), str(r[2]), str(r[17])
        filled, cost = float(r[13] or 0.0), float(r[14] or 0.0)
        flow = flows.get((station, day, bucket, token)) or {}
        bought = flow.get("BUY", 0.0)
        sold = min(filled, flow.get("SELL", 0.0) * filled / bought) if bought > 0 else 0.0
        proceeds = flow.get("SELL_amount", 0.0) * filled / bought if bought > 0 else 0.0
        landed = settled.get((station, day))
        hit = (landed[0] != bucket) if landed and filled > 0 else None
        # A confirmed sale realizes its proceeds even before the event's
        # official truth arrives.  An unsold remainder still needs that truth.
        closed_by_sale = filled > 0 and sold >= filled - 1e-9
        payout = (
            proceeds + (filled - sold if hit else 0.0)
            if token not in uncertain_sale_tokens and (hit is not None or closed_by_sale)
            else None
        )
        paid_price = cost / filled if filled > 0 else None
        open_cost = cost * max(filled - sold, 0.0) / filled if filled > 0 else 0.0
        sale_pnl = proceeds - cost * sold / filled if filled > 0 else 0.0
        remaining = max(0.0, filled - sold)
        settlement_pnl = (
            (remaining if hit else 0.0) - cost * remaining / filled
            if hit is not None and filled > 0 else 0.0
        )
        realised_pnl = (
            sale_pnl + settlement_pnl
            if token not in uncertain_sale_tokens and filled > 0 else None
        )
        trades.append({
            "station_id": station, "event_date": day, "bucket": bucket,
            "yes_bid": r[3], "market_q": r[4], "rungs_from_mode": r[5],
            "book_source": r[6], "book_age_seconds": r[7],
            "order_intent_id": r[8], "limit_price": r[9],
            "requested_size": r[10], "state": r[11], "created_at": r[12],
            "sent": bool(r[18]),
            "filled_size": filled, "filled_notional_usdc": cost,
            "exchange_order_id": r[15], "reconciliation_state": r[16],
            "sold_size": sold, "sale_proceeds_usdc": proceeds,
            "sale_realised_pnl_usdc": sale_pnl if token not in uncertain_sale_tokens else None,
            "realised_pnl_usdc": realised_pnl,
            "paid_price": paid_price,
            "net_odds": (1.0 - paid_price) / paid_price if paid_price and paid_price < 1 else None,
            "open_cost_usdc": 0.0 if payout is not None else open_cost,
            "close_reason": "sale" if closed_by_sale else ("settlement" if hit is not None else None),
            "settled_bucket": landed[0] if landed else None, "hit": hit,
            "payout_usdc": payout,
            "pnl_usdc": payout - cost if payout is not None else None,
        })
    filled_rows = [r for r in trades if r["filled_size"] > 0]
    closed_rows = [r for r in filled_rows if r["payout_usdc"] is not None]
    stake = sum(r["filled_notional_usdc"] for r in closed_rows)
    payout = sum(r["payout_usdc"] or 0.0 for r in closed_rows)
    closed_shares = sum(r["filled_size"] for r in closed_rows)
    wins = sum(r["pnl_usdc"] > 0 for r in closed_rows)
    out["trades"] = {
        "available": True, "rows": trades[:100],
        "sent": sum(1 for r in trades if r["sent"]),
        "filled": len(filled_rows),
        "filled_shares": sum(r["filled_size"] for r in filled_rows),
        "spent_usdc": sum(r["filled_notional_usdc"] for r in filled_rows),
        "recycled_shares": sum(r["sold_size"] for r in filled_rows),
        "recycle_proceeds_usdc": sum(r["sale_proceeds_usdc"] for r in filled_rows),
        "recycle_realised_pnl_usdc": sum(
            r["sale_realised_pnl_usdc"] or 0.0 for r in filled_rows
        ),
        "realised_pnl_usdc": sum(r["realised_pnl_usdc"] or 0.0 for r in filled_rows),
        "recycle_order_count": len(recycle_sells),
        "recycle_submitted": sum(1 for r in recycle_sells if r["exchange_order_id"]),
        "recycle_reconcile_required": sum(
            1 for r in recycle_sells if r["state"] == "reconcile_required"
        ),
        "in_flight_usdc": sum(r["open_cost_usdc"] for r in filled_rows),
        "unresolved": sum(1 for r in trades if r["state"] in ("prepared", "submitting", "submitted", "reconcile_required")
                          and r["reconciliation_state"] not in ("resolved_filled", "resolved_partial", "resolved_not_placed")),
        "official_settled": sum(r["hit"] is not None for r in filled_rows),
        "closed": len(closed_rows), "wins": wins,
        "win_rate": wins / len(closed_rows) if closed_rows else None,
        "avg_paid_price": stake / closed_shares if closed_shares else None,
        "net_odds": (closed_shares - stake) / stake if stake else None,
        "stake_usdc": stake,
        "payout_usdc": payout, "pnl_usdc": payout - stake,
        "roi": (payout - stake) / stake if stake > 0 else None,
    }
    return out


# Station days whose Proper-lane orders the operator took out of the lane's
# statistics (user 2026-10-05: 「Proper 下注线去掉CYYZ 2026-09-29这个订单的统计」
# -- its one order, 20°C YES, filled 2026-09-28 05:03Z under the v2 rule).
# The order stays in the order table, marked, and in no count, sum or rate.
PROPER_BET_STATS_EXCLUDED_DAYS = frozenset({("CYYZ", "2026-09-29")})


def collect_copy_follow_lane(conn: sqlite3.Connection) -> dict[str, Any]:
    """跟单线 -- the copy-follow lane's own statistics (charters 256 and 257).

    User ruling 2026-10-09 「前端增加对应的跟单线数据统计看板」.  Read only:
    the lane's switch and dials from the operator file, every source trade
    it saw (``copy_follow_source_trades``, admitted or refused by name),
    every plan it wrote (``copy_follow_lane_evaluation``) and its legs'
    intents and reconciliations, settled against the same canonical
    settlement the live book reads.  Nothing here computes a probability."""

    lanes = _load_strategy_lanes()
    cfg = lanes["lanes"].get("copy_follow") or {}
    out: dict[str, Any] = {
        "available": True,
        "settings": {k: cfg.get(k) for k in (
            "enabled", "rule", "stake_usdc", "max_daily_cost_usdc", "max_sends_per_pass",
            "model_margin", "max_slippage", "lead_hours", "station_units", "model_stages",
            "episode_gap_seconds", "mirror_sells", "enabled_at_utc", "paused_at_utc",
            "stake_tiers", "big_episode_usdc", "big_episode_window_seconds", "big_episode_multiplier",
        )},
        "source_wallets": len(cfg.get("source_users") or ([cfg["source_user"]] if cfg.get("source_user") else [])),
        "follow_from": [],
        "sources": {"available": False},
        "evaluations": {"available": False},
        "trades": {"available": False},
    }
    src_table, eval_table, state_table = (
        "copy_follow_source_trades", "copy_follow_lane_evaluation", "copy_follow_state",
    )
    if _table_exists(conn, state_table):
        out["follow_from"] = [
            {"source_user": str(u), "follow_from_utc": str(at)}
            for u, at in conn.execute(f"SELECT source_user, follow_from_utc FROM {state_table} ORDER BY follow_from_utc")
        ]
    if _table_exists(conn, src_table):
        total, admitted, wallets, first_at, last_at = conn.execute(
            f"SELECT COUNT(*), COALESCE(SUM(refusal IS NULL),0), COUNT(DISTINCT source_user),"
            f" MIN(source_at_utc), MAX(source_at_utc) FROM {src_table}"
        ).fetchone()
        has_v2 = "our_p" in {str(r[1]) for r in conn.execute(f"PRAGMA table_info({src_table})")}
        extra = ", our_p, price_cap, model_stage, taker" if has_v2 else ", NULL, NULL, NULL, NULL"
        out["sources"] = {
            "available": True, "total": int(total), "admitted": int(admitted), "wallets": int(wallets),
            "first_at_utc": first_at, "last_at_utc": last_at,
            "refusals": [
                {"reason": str(reason or "admitted"), "count": int(count)}
                for reason, count in conn.execute(
                    f"SELECT CASE WHEN refusal IS NULL THEN NULL ELSE substr(refusal, 1, instr(refusal||':', ':')-1) END,"
                    f" COUNT(*) FROM {src_table} GROUP BY 1 ORDER BY COUNT(*) DESC LIMIT 15"
                )
            ],
            "by_wallet": [
                {"source_user": str(u), "seen": int(n), "admitted": int(a), "last_at_utc": last}
                for u, n, a, last in conn.execute(
                    f"SELECT source_user, COUNT(*), COALESCE(SUM(refusal IS NULL),0), MAX(source_at_utc)"
                    f" FROM {src_table} GROUP BY source_user ORDER BY COUNT(*) DESC"
                )
            ],
            "by_day": [
                {"day": str(d), "seen": int(n), "admitted": int(a)}
                for d, n, a in conn.execute(
                    f"SELECT substr(source_at_utc,1,10), COUNT(*), COALESCE(SUM(refusal IS NULL),0)"
                    f" FROM {src_table} GROUP BY 1 ORDER BY 1 DESC LIMIT 31"
                )
            ],
            "recent": [
                {"source_at_utc": r[0], "source_user": str(r[1])[:10], "station_id": r[2], "event_date": r[3],
                 "bucket": r[4], "side": r[5], "price": r[6], "size": r[7], "refusal": r[8],
                 "our_p": r[9], "price_cap": r[10], "model_stage": r[11], "taker": r[12]}
                for r in conn.execute(
                    f"SELECT source_at_utc, source_user, station_id, event_date, bucket, outcome_side, price, size,"
                    f" refusal{extra} FROM {src_table} ORDER BY source_ts DESC, source_key LIMIT 40"
                )
            ],
        }
    if not _table_exists(conn, eval_table):
        return out
    total, sent, first_at, last_at = conn.execute(
        f"SELECT COUNT(*), COALESCE(SUM(sent),0), MIN(evaluated_at_utc), MAX(evaluated_at_utc) FROM {eval_table}"
    ).fetchone()
    has_eval_v2 = "our_p" in {str(r[1]) for r in conn.execute(f"PRAGMA table_info({eval_table})")}
    ev_extra = ", our_p, price_cap, model_stage" if has_eval_v2 else ", NULL, NULL, NULL"
    out["evaluations"] = {
        "available": True, "total": int(total), "sent": int(sent), "first_at_utc": first_at, "last_at_utc": last_at,
        "refusals": [
            {"reason": str(reason or "planned"), "count": int(count)}
            for reason, count in conn.execute(
                f"SELECT CASE WHEN refusal IS NULL THEN NULL ELSE substr(refusal, 1, instr(refusal||':', ':')-1) END,"
                f" COUNT(*) FROM {eval_table} GROUP BY 1 ORDER BY COUNT(*) DESC LIMIT 15"
            )
        ],
        "recent": [
            {"evaluated_at_utc": r[0], "station_id": r[1], "event_date": r[2], "bucket": r[3], "side": r[4],
             "order_action": r[5], "order_kind": r[6], "limit_price": r[7], "shares": r[8], "source_price": r[9],
             "refusal": r[10], "sent": r[11], "our_p": r[12], "price_cap": r[13], "model_stage": r[14]}
            for r in conn.execute(
                f"SELECT evaluated_at_utc, station_id, event_date, bucket, side, order_action, order_kind,"
                f" limit_price, shares, source_price, refusal, sent{ev_extra} FROM {eval_table}"
                " ORDER BY evaluated_at_utc DESC LIMIT 30"
            )
        ],
    }
    if not all(_table_exists(conn, t) for t in (
        "basket_target_order_intents", "basket_target_order_reconciliations",
    )):
        return out
    orders = conn.execute(
        f"SELECT e.station_id, e.event_date, e.bucket, e.side, e.source_price, e.order_kind,"
        f" i.order_intent_id, i.limit_price, i.requested_size, i.state, i.created_at,"
        " COALESCE(r.filled_size,0), COALESCE(r.filled_notional_usdc,0), r.exchange_order_id, r.state,"
        f" i.token_id, e.sent{ev_extra}, e.source_user"
        f" FROM {eval_table} e"
        " JOIN basket_target_order_intents i ON i.order_intent_id=e.order_intent_id"
        " LEFT JOIN basket_target_order_reconciliations r ON r.order_intent_id=i.order_intent_id"
        " WHERE i.live_submit_authorized=1 AND i.order_action='BUY'"
        " ORDER BY i.created_at DESC"
    ).fetchall()
    tokens = {str(r[15]) for r in orders}
    sells: dict[str, dict[str, float]] = {}
    for token, shares, amount, state in conn.execute(
        "SELECT i.token_id, COALESCE(r.filled_size,0), COALESCE(r.filled_notional_usdc,0), COALESCE(r.state,'')"
        " FROM basket_target_order_intents i"
        " LEFT JOIN basket_target_order_reconciliations r ON r.order_intent_id=i.order_intent_id"
        " WHERE i.order_action='SELL' AND i.live_submit_authorized=1"
    ):
        if str(token) not in tokens:
            continue
        slot = sells.setdefault(str(token), {"shares": 0.0, "amount": 0.0, "uncertain": 0.0})
        if str(state) in ("resolved_filled", "resolved_partial"):
            slot["shares"] += float(shares or 0.0)
            slot["amount"] += float(amount or 0.0)
        elif float(shares or 0.0) > 0:
            slot["uncertain"] += 1.0
    settled = dict(_render_live_book(conn).get("settled") or {})
    scopes = {(str(r[0]), str(r[1])) for r in orders}
    settled.update(live_book.settled_buckets(conn, scopes - set(settled)))
    bought_by_token: dict[str, float] = {}
    for r in orders:
        bought_by_token[str(r[15])] = bought_by_token.get(str(r[15]), 0.0) + float(r[11] or 0.0)
    trades = []
    for r in orders:
        station, day, bucket, side, token = str(r[0]), str(r[1]), str(r[2]), str(r[3]), str(r[15])
        filled, cost = float(r[11] or 0.0), float(r[12] or 0.0)
        flow = sells.get(token) or {}
        bought = bought_by_token.get(token, 0.0)
        share = filled / bought if bought > 0 else 0.0
        sold = min(filled, flow.get("shares", 0.0) * share)
        proceeds = flow.get("amount", 0.0) * share
        uncertain = flow.get("uncertain", 0.0) > 0
        landed = settled.get((station, day))
        hit = None
        if landed and filled > 0:
            hit = (landed[0] == bucket) if side == "YES" else (landed[0] != bucket)
        remaining = max(0.0, filled - sold)
        closed_by_sale = filled > 0 and remaining <= 1e-9
        payout = (proceeds + (remaining if hit else 0.0)
                  if not uncertain and (hit is not None or closed_by_sale) else None)
        paid = cost / filled if filled > 0 else None
        trades.append({
            "station_id": station, "event_date": day, "bucket": bucket, "side": side,
            "source_price": r[4], "order_kind": r[5], "order_intent_id": r[6], "limit_price": r[7],
            "requested_size": r[8], "state": r[9], "created_at": r[10], "sent": bool(r[16]),
            "our_p": r[17], "price_cap": r[18], "model_stage": r[19], "source_user": str(r[20] or "")[:10],
            "filled_size": filled, "filled_notional_usdc": cost, "paid_price": paid,
            "exchange_order_id": r[13], "reconciliation_state": r[14],
            "sold_size": sold, "sale_proceeds_usdc": proceeds,
            "settled_bucket": landed[0] if landed else None, "hit": hit,
            "payout_usdc": payout, "pnl_usdc": payout - cost if payout is not None else None,
            "open_cost_usdc": 0.0 if payout is not None else cost * remaining / filled if filled > 0 else 0.0,
        })
    filled_rows = [t for t in trades if t["filled_size"] > 0]
    closed_rows = [t for t in filled_rows if t["payout_usdc"] is not None]
    stake = sum(t["filled_notional_usdc"] for t in closed_rows)
    payout = sum(t["payout_usdc"] or 0.0 for t in closed_rows)
    by_day: dict[str, dict[str, float]] = {}
    for t in closed_rows:
        slot = by_day.setdefault(t["event_date"], {"legs": 0, "stake_usdc": 0.0, "pnl_usdc": 0.0, "wins": 0})
        slot["legs"] += 1
        slot["stake_usdc"] += t["filled_notional_usdc"]
        slot["pnl_usdc"] += t["pnl_usdc"] or 0.0
        slot["wins"] += int((t["pnl_usdc"] or 0.0) > 0)
    out["trades"] = {
        "available": True, "rows": trades[:120],
        "sent": sum(1 for t in trades if t["sent"]), "filled": len(filled_rows),
        "filled_shares": sum(t["filled_size"] for t in filled_rows),
        "spent_usdc": sum(t["filled_notional_usdc"] for t in filled_rows),
        "in_flight_usdc": sum(t["open_cost_usdc"] for t in filled_rows),
        "closed": len(closed_rows), "wins": sum(1 for t in closed_rows if (t["pnl_usdc"] or 0.0) > 0),
        "win_rate": (sum(1 for t in closed_rows if (t["pnl_usdc"] or 0.0) > 0) / len(closed_rows)) if closed_rows else None,
        "avg_paid_price": (stake / sum(t["filled_size"] for t in closed_rows)) if closed_rows else None,
        "stake_usdc": stake, "payout_usdc": payout, "pnl_usdc": payout - stake,
        "roi": (payout - stake) / stake if stake > 0 else None,
        "yes_legs": sum(1 for t in filled_rows if t["side"] == "YES"),
        "no_legs": sum(1 for t in filled_rows if t["side"] == "NO"),
        "taken": sum(1 for t in filled_rows if t["order_kind"] == "take"),
        "rested": sum(1 for t in filled_rows if t["order_kind"] == "rest"),
        "by_day": [{"event_date": d, **v} for d, v in sorted(by_day.items(), reverse=True)],
    }
    return out


def collect_proper_bet_lane(conn: sqlite3.Connection) -> dict[str, Any]:
    """Proper 下注线 -- the log-proper lane's own statistics (charter 231).

    User ruling 2026-09-26 「前端没有proper线相关内容」.  Read from where the
    lane writes: its switch and settings from the operator file, every P0
    first decision it judged from ``proper_bet_lane_evaluation`` (the weather
    model p, the market q, the position s = log(p/q), D = KL(q||p), the plan
    the rung pass keeps posting and where it stands), and its legs from the
    live book restricted to its own decision rows.  YES and NO legs both: a
    YES leg pays when its bucket settles, a NO leg when it does not.
    """

    lanes = _load_strategy_lanes()
    cfg = lanes["lanes"].get("proper_bet") or {}
    out: dict[str, Any] = {
        "available": True,
        "settings": {
            "enabled": cfg.get("enabled") is True,
            "rule": cfg.get("rule"),
            "opening_stages": cfg.get("opening_stages"),
            "min_hours_to_settlement": cfg.get("min_hours_to_settlement"),
            "first_decision_fresh_seconds": cfg.get("first_decision_fresh_seconds"),
            "send_book_fresh_seconds": cfg.get("send_book_fresh_seconds"),
            "live_ws_book": cfg.get("live_ws_book"),
            "stake_usdc": cfg.get("stake_usdc"),
            "enabled_at_utc": cfg.get("enabled_at_utc"),
            "source": lanes.get("source"),
            "updated_at_utc": lanes.get("updated_at_utc"),
        },
        "evaluations": {"available": False},
        "trades": {"available": False},
    }
    table = "proper_bet_lane_evaluation"
    if _table_exists(conn, table):
        cols = {str(row[1]) for row in conn.execute(f"PRAGMA table_info({table})")}
        has_plan = "plan_state" in cols
        total, days, first_at, last_at, planned, legs_sum, cost_sum = conn.execute(
            "SELECT COUNT(*), COUNT(DISTINCT event_date), MIN(evaluated_at_utc),"
            " MAX(evaluated_at_utc), SUM(CASE WHEN planned_legs>0 THEN 1 ELSE 0 END),"
            f" COALESCE(SUM(planned_legs),0), COALESCE(SUM(planned_cost_usdc),0) FROM {table}"
        ).fetchone()
        refusals = [
            {"refusal": str(r[0] or "planned"), "count": int(r[1])}
            for r in conn.execute(
                f"SELECT COALESCE(refusal,''), COUNT(*) FROM {table}"
                " GROUP BY COALESCE(refusal,'') ORDER BY COUNT(*) DESC LIMIT 14"
            )
        ]
        by_rule = [
            {"rule_version": str(r[0] or ""), "evaluated": int(r[1]),
             "planned": int(r[2] or 0), "first_at_utc": r[3], "last_at_utc": r[4]}
            for r in conn.execute(
                "SELECT rule_version, COUNT(*), SUM(CASE WHEN planned_legs>0 THEN 1 ELSE 0 END),"
                f" MIN(evaluated_at_utc), MAX(evaluated_at_utc) FROM {table}"
                " GROUP BY rule_version ORDER BY MIN(evaluated_at_utc)"
            )
        ]
        plan_states = (
            {
                str(r[0] or "none"): int(r[1])
                for r in conn.execute(
                    f"SELECT plan_state, COUNT(*) FROM {table} GROUP BY plan_state"
                )
            }
            if has_plan else {}
        )
        by_day = [
            {"event_date": r[0], "evaluated": int(r[1]), "planned": int(r[2] or 0),
             "legs": int(r[3] or 0), "cost_usdc": float(r[4] or 0.0)}
            for r in conn.execute(
                "SELECT event_date, COUNT(*), SUM(CASE WHEN planned_legs>0 THEN 1 ELSE 0 END),"
                f" SUM(planned_legs), SUM(planned_cost_usdc) FROM {table}"
                " GROUP BY event_date ORDER BY event_date DESC LIMIT 21"
            )
        ]
        plan_cols = (
            ", hours_to_settlement, plan_state, plan_state_reason, passes, legs_state_json"
            if has_plan else ""
        )
        recent = []
        for r in conn.execute(
            "SELECT station_id, event_date, stage, decision_at_utc, divergence_kl,"
            " planned_legs, planned_cost_usdc, refusal, s_json, rule_version"
            f"{plan_cols} FROM {table}"
            " WHERE planned_legs>0 OR refusal IS NULL"
            "    OR refusal NOT IN ('settlement_day_closed','first_decision_stale')"
            " ORDER BY evaluated_at_utc DESC LIMIT 40"
        ):
            try:
                s_by_bucket = json.loads(r[8]) if r[8] else {}
            except (TypeError, ValueError):
                s_by_bucket = {}
            # The legs by |s|: the lane sizes x = lambda * |s|, so the largest
            # magnitudes are the position's backbone.
            top = sorted(
                ((str(b), float(v)) for b, v in (s_by_bucket or {}).items()
                 if isinstance(v, (int, float))),
                key=lambda kv: -abs(kv[1]),
            )[:6]
            row = {
                "station_id": r[0], "event_date": r[1], "stage": r[2],
                "decision_at_utc": r[3], "divergence_kl": r[4],
                "planned_legs": int(r[5] or 0), "planned_cost_usdc": r[6],
                "refusal": r[7], "rule_version": r[9],
                "top_positions": [{"bucket": b, "s": v} for b, v in top],
            }
            if has_plan:
                row.update({
                    "hours_to_settlement": r[10], "plan_state": r[11],
                    "plan_state_reason": r[12], "passes": r[13],
                })
            recent.append(row)
        out["evaluations"] = {
            "available": True, "total": int(total or 0), "event_days": int(days or 0),
            "first_at_utc": first_at, "last_at_utc": last_at,
            "planned": int(planned or 0), "planned_legs": int(legs_sum or 0),
            "planned_cost_usdc": float(cost_sum or 0.0), "refusals": refusals,
            "by_rule": by_rule, "plan_states": plan_states, "by_day": by_day,
            "recent": recent,
        }
    book = _render_live_book(conn)
    settled = book.get("settled") or {}
    legs = [
        leg for leg in (book.get("legs") or [])
        if str(leg.get("decision_id") or "").startswith("proper_bet_decision_")
    ]
    # One order per station day, bucket and side: the rung pass reposts an
    # unfilled leg every fifteen minutes, and every repost is its own intent
    # row -- CYYZ 2026-09-29 20°C YES is 106 rows and one fill (user:
    # 「同一个站点同一笔订单合并在一起」).  The rungs of one order are summed
    # into it: shares and notional add, the price is the fill-weighted mean.
    # The rungs themselves are not shown -- no count, no first or last post
    # (user: 「不要显示cancelled订单、挂单次数、首次、末次挂单」).
    orders: dict[tuple[str, str, str, str], list[dict[str, Any]]] = {}
    for leg in legs:
        side = str(leg.get("side") or "YES").upper()
        orders.setdefault(
            (leg["station_id"], leg["event_date"], leg["bucket"], side), []
        ).append(leg)
    trades: list[dict[str, Any]] = []
    for (station_id, event_date, bucket, side), rungs in orders.items():
        rungs.sort(key=lambda leg: str(leg.get("created_at") or ""))
        filled = sum(float(leg.get("filled_size") or 0.0) for leg in rungs)
        notional = sum(float(leg.get("filled_notional_usdc") or 0.0) for leg in rungs)
        target = max(float(leg.get("requested_size") or 0.0) for leg in rungs)
        # A rung still working at the venue (not failed, cancelled or filled).
        working = [
            str(leg.get("state") or "") for leg in rungs
            if str(leg.get("state") or "") not in ("failed", "cancelled", "filled")
        ]
        # An order that never filled and has nothing working is not a trade
        # -- every failed send and unfilled cancelled rung (the rule the
        # tiebreak page reads by).  Dropped before anything is shown.
        if filled <= 0 and not working:
            continue
        if working:
            state = working[-1]
        elif target > 0 and filled >= target - 1e-9:
            state = "filled"
        else:
            state = "partially_filled"
        landed = settled.get((station_id, event_date))
        hit = None
        if landed and filled > 0:
            on_bucket = landed[0] == bucket
            hit = on_bucket if side == "YES" else not on_bucket
        payout = filled if hit else (0.0 if hit is False else None)
        trades.append({
            "station_id": station_id, "event_date": event_date,
            "stage": rungs[-1].get("stage"), "bucket": bucket, "side": side,
            "posted_at": rungs[0].get("created_at"),
            "last_limit_price": rungs[-1].get("limit_price"),
            "avg_fill_price": (notional / filled) if filled > 0 else None,
            "requested_size": target,
            "filled_size": filled, "filled_notional_usdc": notional,
            "state": state,
            "settled_bucket": landed[0] if landed else None,
            "hit": hit, "payout_usdc": payout,
            "pnl_usdc": (payout - notional) if payout is not None else None,
            "stats_excluded": (station_id, event_date) in PROPER_BET_STATS_EXCLUDED_DAYS,
        })
    trades.sort(
        key=lambda t: (t["event_date"], str(t["posted_at"] or ""), t["station_id"]),
        reverse=True,
    )
    for t in trades:
        del t["posted_at"]
    counted = [t for t in trades if not t["stats_excluded"]]
    filled_rows = [t for t in counted if t["filled_size"] > 0]
    settled_rows = [t for t in filled_rows if t["hit"] is not None]
    stake_sum = sum(t["filled_notional_usdc"] for t in settled_rows)
    payout_sum = sum(t["payout_usdc"] or 0.0 for t in settled_rows)
    hits = sum(1 for t in settled_rows if t["hit"])
    out["trades"] = {
        "available": True,
        "rows": trades,
        "orders": len(counted),
        "stats_excluded": [
            {"station_id": t["station_id"], "event_date": t["event_date"],
             "bucket": t["bucket"], "side": t["side"]}
            for t in trades if t["stats_excluded"]
        ],
        "filled": len(filled_rows),
        "filled_yes": sum(1 for t in filled_rows if t["side"] == "YES"),
        "filled_no": sum(1 for t in filled_rows if t["side"] == "NO"),
        "open": len(filled_rows) - len(settled_rows),
        "settled": len(settled_rows),
        "stake_usdc": stake_sum,
        "payout_usdc": payout_sum,
        "pnl_usdc": payout_sum - stake_sum,
        "roi": ((payout_sum - stake_sum) / stake_sum) if stake_sum > 0 else None,
        "hits": hits,
        "hit_rate": (hits / len(settled_rows)) if settled_rows else None,
        "in_flight_usdc": sum(
            t["filled_notional_usdc"] for t in filled_rows if t["hit"] is None
        ),
    }
    return out

#: Charter 254: where the realisation layer's nightly fit is written
#: (``bayes_basket_target.realisation_store.ARTIFACT_DIR``), read as a file.
REALISATION_LAYER_ACTIVE = ROOT / "data" / "realisation_layer" / "active.json"
REALISATION_SHADOW_TABLE = "realisation_layer_shadow"


def collect_realisation_layer(conn: sqlite3.Connection) -> dict[str, Any]:
    """兑现层（影子）-- charter 254 (user rulings 2026-10-05 「上影子」,
    「前端增加对应显式看板」).

    Read only: the nightly fit's artifact as the backend wrote it (its
    walk-forward calibration gate, its parameters, and the settled shadow legs
    scored against what landed), and the shadow rows the two betting lanes
    wrote for every leg they judged -- ``b``, its band and the edge on the
    leg's own price -- beside the settled bucket and the order's state.
    """

    out: dict[str, Any] = {"available": True, "fit": {"available": False}, "shadow": {"available": False}}
    try:
        artifact = json.loads(REALISATION_LAYER_ACTIVE.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        artifact = None
    if artifact:
        gate = dict(artifact.get("gate") or {})
        try:
            fitted = datetime.fromisoformat(str(artifact.get("fitted_at_utc")).replace("Z", "+00:00"))
            age_hours = round((datetime.now(timezone.utc) - fitted).total_seconds() / 3600.0, 1)
        except ValueError:
            age_hours = None
        out["fit"] = {
            "available": True,
            "fit_id": artifact.get("fit_id"), "rule": artifact.get("rule"),
            "fitted_at_utc": artifact.get("fitted_at_utc"), "age_hours": age_hours,
            "cutoff_utc": artifact.get("cutoff_utc"), "window_days": artifact.get("window_days"),
            "build_sec": artifact.get("build_sec"),
            "population": artifact.get("population") or {},
            "theta": artifact.get("theta_named") or {},
            "gate": {k: gate.get(k) for k in (
                "state", "rule", "scored_days", "first_scored_day", "last_scored_day", "scored_decisions",
                "cells_judged", "cells_outside", "cells_allowed", "calibration_line", "logscore", "top_bucket",
            )},
            "cells": [c for c in (gate.get("cells") or []) if c.get("group") == "all" or c.get("outside")],
            "realised": artifact.get("shadow") or {},
        }
    if _table_exists(conn, REALISATION_SHADOW_TABLE):
        table = REALISATION_SHADOW_TABLE
        counts = [
            {"lane": r[0], "kind": r[1], "state": r[2], "rows": int(r[3]), "last_at_utc": r[4]}
            for r in conn.execute(
                f"SELECT lane, kind, CASE WHEN state LIKE 'error:%' THEN 'error' ELSE state END,"
                f" COUNT(*), MAX(judged_at_utc) FROM {table} GROUP BY 1, 2, 3 ORDER BY 1, 2, 3"
            )
        ]
        recent = []
        for r in conn.execute(
            f"SELECT s.judged_at_utc, s.lane, s.kind, s.station_id, s.event_date, s.bucket, s.side,"
            f" s.price, s.fee_per_share, s.p, s.q, s.b, s.b_low, s.b_high, s.edge, s.edge_sure,"
            f" s.outcome, s.state, s.centres_agree, s.fit_state, s.hours_to_settlement, s.order_intent_id,"
            " i.state, COALESCE(x.filled_size, 0),"
            " (SELECT l.settled_bucket FROM basket_station_day_settlement_label l"
            "   WHERE l.station_id=s.station_id AND l.event_date=s.event_date"
            "   ORDER BY l.truth_revision_no DESC LIMIT 1)"
            f" FROM {table} s"
            " LEFT JOIN basket_target_order_intents i ON i.order_intent_id = s.order_intent_id"
            " LEFT JOIN basket_target_order_reconciliations x ON x.order_intent_id = s.order_intent_id"
            " ORDER BY s.judged_at_utc DESC LIMIT 60"
        ):
            recent.append({
                "judged_at_utc": r[0], "lane": r[1], "kind": r[2], "station_id": r[3], "event_date": r[4],
                "bucket": r[5], "side": r[6], "price": r[7], "fee_per_share": r[8], "p": r[9], "q": r[10],
                "b": r[11], "b_low": r[12], "b_high": r[13], "edge": r[14], "edge_sure": r[15],
                "outcome": r[16], "state": r[17], "centres_agree": r[18], "fit_state": r[19],
                "hours_to_settlement": r[20], "order_intent_id": r[21], "order_state": r[22],
                "filled_size": float(r[23] or 0.0), "settled_bucket": r[24],
            })
        out["shadow"] = {"available": True, "counts": counts, "recent": recent}
    out["go_live"] = realisation_go_live(out["fit"], collect_board_evidence()["entries"].get("realisation_proper_filter"))
    return out


# What "上线" would have to clear (user 2026-10-05 「兑现层：给我一个可以上线的
# 明确看板或总结」).  The layer's belief is judged by the nightly gate; the
# change it would make -- the Proper lane posting on b instead of p, a
# change to charter 231's 「p＝天气模型」 -- by the settled shadow legs and by
# the research replay beside the current rule.  Ten event days is the count
# charter 254(五) set for the re-read.
REALISATION_GO_LIVE_MIN_EVENT_DAYS = 10


def realisation_go_live(fit: Mapping[str, Any], evidence: Mapping[str, Any] | None) -> dict[str, Any]:
    """Each criterion as (value, state) with state ``pass`` / ``fail`` / ``wait``.

    ``belief`` is ready when the calibration gate admits the fit and it beats
    the market as it stands; ``trade`` (reading b in the Proper filter) needs
    every criterion: enough settled event days, filled legs realising above
    zero after fees with b saying what lands, and the replay showing reading
    b does not do worse per leg than the rule it replaces.
    """

    def ci_state(interval: Any, want_below: bool) -> str:
        if not isinstance(interval, (list, tuple)) or len(interval) < 3:
            return "wait"
        low, high = float(interval[1]), float(interval[2])
        return "pass" if (high < 0 if want_below else low > 0) else "fail"

    checks: list[dict[str, Any]] = []
    gate = dict((fit or {}).get("gate") or {})
    if not (fit or {}).get("available"):
        checks.append({"key": "gate", "group": "belief", "label": "校准门", "value": None, "state": "wait"})
    else:
        line = dict(gate.get("calibration_line") or {})
        checks.append({
            "key": "gate", "group": "belief", "label": "校准门（说多少中多少）",
            "value": {"state": gate.get("state"), "outside": gate.get("cells_outside"),
                      "allowed": gate.get("cells_allowed"), "slope": line.get("slope")},
            "state": {"ADMITTED": "pass", "REFUSED": "fail"}.get(str(gate.get("state")), "wait"),
        })
        logscore = dict(gate.get("logscore") or {})
        checks.append({"key": "vs_market", "group": "belief", "label": "比市场原样准（LogScore 差）",
                       "value": logscore.get("layer_minus_market"),
                       "state": ci_state(logscore.get("layer_minus_market"), True)})
        checks.append({"key": "model_increment", "group": "info", "label": "天气模型在市场之外的增量",
                       "value": logscore.get("layer_minus_market_only_pool"),
                       "state": ci_state(logscore.get("layer_minus_market_only_pool"), True)})
    realised = dict((fit or {}).get("realised") or {})
    proper_filled = next((r for r in realised.get("filled") or []
                          if r.get("lane") == "proper_bet" and r.get("side") == "YES"), None)
    proper_decided = next((r for r in realised.get("decided") or []
                           if r.get("lane") == "proper_bet" and r.get("side") == "YES"), None)
    days = int((proper_decided or {}).get("event_days") or 0)
    enough = days >= REALISATION_GO_LIVE_MIN_EVENT_DAYS
    checks.append({"key": "event_days", "group": "trade", "label": "Proper 影子腿已结算事件日",
                   "value": {"days": days, "need": REALISATION_GO_LIVE_MIN_EVENT_DAYS},
                   "state": "pass" if enough else "wait"})
    checks.append({"key": "filled_realised", "group": "trade", "label": "Proper 已成交腿扣费后兑现（¢/份）",
                   "value": (proper_filled or {}).get("realised"),
                   "state": ci_state((proper_filled or {}).get("realised"), False) if enough else "wait"})
    belief_gap = (proper_decided or {}).get("belief_minus_landed")
    gap_state = "wait"
    if enough and isinstance(belief_gap, (list, tuple)) and len(belief_gap) >= 3:
        gap_state = "pass" if float(belief_gap[1]) <= 0.0 <= float(belief_gap[2]) else "fail"
    checks.append({"key": "belief_on_legs", "group": "trade", "label": "影子腿上 b 说多少中多少（b−命中）",
                   "value": belief_gap, "state": gap_state})
    values = dict((evidence or {}).get("values") or {})
    if values:
        worse = float(values["b_margin_pts"]) < float(values["current_margin_pts"])
        added_low = float((values.get("added_ci") or [0.0])[0])
        checks.append({
            "key": "replay_vs_current", "group": "trade", "label": "回放：改读 b 对现行「挂价<p」",
            "value": {k: values.get(k) for k in (
                "current_days", "current_margin_pts", "current_ci", "b_days", "b_margin_pts", "b_ci",
                "added_days", "added_margin_pts", "added_ci", "p_only_days")},
            "state": "fail" if (worse or added_low <= 0.0) else "pass",
            "measured_on": (evidence or {}).get("measured_on"),
        })
    else:
        checks.append({"key": "replay_vs_current", "group": "trade", "label": "回放：改读 b 对现行「挂价<p」",
                       "value": None, "state": "wait"})
    belief_ready = all(c["state"] == "pass" for c in checks if c["group"] == "belief")
    trade_ready = belief_ready and all(c["state"] == "pass" for c in checks if c["group"] == "trade")
    trade_blocked = any(c["state"] == "fail" for c in checks if c["group"] == "trade")
    return {
        "checks": checks,
        "belief_ready": belief_ready,
        "trade": "ready" if trade_ready else ("blocked" if trade_blocked else "waiting"),
        "min_event_days": REALISATION_GO_LIVE_MIN_EVENT_DAYS,
    }


def charter_ev_identity(
    rows: Sequence[Mapping[str, Any]],
) -> dict[str, Any]:
    """The user's charter (2026-09-12), as arithmetic: edge = the market's
    error minus the model's error.

    Per bucket ``b`` of a ladder, with truth ``t_b`` (1 in the settled bucket,
    0 elsewhere), market mid ``m_b`` and served claim ``p_b``:

        e_q = m_b - t_b        the market's error
        e_p = p_b - t_b        the model's error

    Buying ``(p_b - m_b)`` shares of every bucket at the mid returns
    ``(p_b - m_b)(t_b - m_b) = e_q^2 - e_p e_q`` per bucket, so the strategy's
    expected profit per station-day is ``Var(e_q) - Cov(e_p, e_q)``: how much
    the market is wrong, less how much of that the model is wrong in the same
    direction.  ``k = Cov / Var(e_q)`` is the regression slope of the model's
    error on the market's: 1 means the model's error contains the whole of the
    market's error plus noise of its own; only below 1 is there anything to
    collect.  The model's own variance never enters -- the charter does not
    ask the model to be more accurate than the market, only to be wrong
    differently.

    ``rows`` carry ``p`` and ``m`` (vectors over the same ladder), ``label``,
    ``date`` and ``weight`` (each station-day's decisions sum to one, so the
    averages are per station-day).  The realised profit of the strategy is
    summed beside the identity rather than derived from it, so a reader --
    and the test -- sees the algebra hold on the data.

    ``EV`` is at the mid.  A row that carries ``half_spread`` (per bucket,
    on the vector's scale) also prices what the strategy pays to cross the
    book, ``sum |p_b - m_b| * half_spread_b``, which is the hurdle the
    charter sets for a live gate: the lower bound of EV above this cost.
    """

    var_market = var_model = cov = profit = spread = weight_total = 0.0
    spread_weight = 0.0
    by_day: dict[str, dict[str, float]] = {}
    station_days: set[tuple[str, str]] = set()
    for row in rows:
        p = row["p"]
        m = row["m"]
        label = str(row["label"])
        w = float(row.get("weight", 1.0) or 1.0)
        half = row.get("half_spread")
        vq = vp = c = pr = sc = 0.0
        for bucket in set(p) | set(m):
            t = 1.0 if str(bucket) == label else 0.0
            e_q = float(m.get(bucket, 0.0)) - t
            e_p = float(p.get(bucket, 0.0)) - t
            vq += e_q * e_q
            vp += e_p * e_p
            c += e_p * e_q
            pr += (e_p - e_q) * (-e_q)
            if half:
                sc += abs(e_p - e_q) * float(half.get(bucket, 0.0) or 0.0)
        var_market += w * vq
        var_model += w * vp
        cov += w * c
        profit += w * pr
        weight_total += w
        if half:
            spread += w * sc
            spread_weight += w
        day = by_day.setdefault(
            str(row["date"]),
            {"w": 0.0, "var_market": 0.0, "var_model": 0.0, "cov": 0.0},
        )
        day["w"] += w
        day["var_market"] += w * vq
        day["var_model"] += w * vp
        day["cov"] += w * c
        station_days.add((str(row["station"]), str(row["date"])))
    if weight_total <= 0.0:
        return {
            "decisions": 0, "station_days": 0, "days": 0,
            "var_market": None, "var_model": None, "cov": None,
            "ev": None, "k": None, "strategy_profit": None,
            "spread_cost": None, "days_ev_positive": None, "by_day": {},
        }
    var_q = var_market / weight_total
    return {
        "decisions": len(rows),
        "station_days": len(station_days),
        "days": len(by_day),
        "var_market": var_q,
        "var_model": var_model / weight_total,
        "cov": cov / weight_total,
        "ev": (var_market - cov) / weight_total,
        "k": (cov / var_market) if var_market > 0.0 else None,
        "strategy_profit": profit / weight_total,
        "spread_cost": (
            spread / spread_weight if spread_weight > 0.0 else None
        ),
        "days_ev_positive": sum(
            1 for day in by_day.values() if day["var_market"] > day["cov"]
        ),
        "by_day": by_day,
    }


def _charter_ev_reading(
    rows: Sequence[Mapping[str, Any]], *, draws: int, seed: int,
) -> dict[str, Any]:
    """The identity plus a by-day bootstrap on EV and k.

    Whole event days are resampled, as the valuation and beta lanes do: a
    fleet shares its weather, so station-days inside a day are not
    independent draws.  The interval is the 5th to 95th percentile.
    """

    reading = charter_ev_identity(rows)
    by_day = reading.pop("by_day")
    reading["ev_ci"] = None
    reading["k_ci"] = None
    keys = list(by_day)
    if len(keys) >= 2 and draws > 0:
        rng = random.Random(int(seed))
        evs: list[float] = []
        ks: list[float] = []
        for _ in range(int(draws)):
            picked = [by_day[key] for key in rng.choices(keys, k=len(keys))]
            w = sum(day["w"] for day in picked)
            vq = sum(day["var_market"] for day in picked)
            c = sum(day["cov"] for day in picked)
            if w > 0.0:
                evs.append((vq - c) / w)
            if vq > 0.0:
                ks.append(c / vq)

        def _band(values: list[float]) -> list[float] | None:
            if not values:
                return None
            ordered = sorted(values)
            lo = ordered[min(len(ordered) - 1, int(0.05 * len(ordered)))]
            hi = ordered[max(0, int(0.95 * len(ordered)) - 1)]
            return [lo, hi]

        reading["ev_ci"] = _band(evs)
        reading["k_ci"] = _band(ks)
    return reading


#: What ``population`` derived from each (envelope, snapshot) pair, kept
#: across builds: both rows are immutable, so only pairs new since the last
#: build read their JSON.  Every build re-read all ~60k pairs of the 28-day
#: window -- a random envelope page and a snapshot's whole book each -- and
#: that was nearly all of this page's 1,601 s on 2026-10-02.
CHARTER_EV_DECISION_MEMO = "_charter_ev_decision_memo.json"


class _TrackedMemo(dict):
    """The memo, noting which entries this build asked for, so the file
    keeps exactly the window's pairs and sheds the ones it has slid past."""

    def __init__(self, prior: Mapping[str, Any]) -> None:
        super().__init__(prior)
        self.used: set[str] = set()

    def get(self, key: str, default: Any = None) -> Any:  # noqa: D401
        self.used.add(key)
        return super().get(key, default)


def _charter_ev_memo_code() -> str:
    from bayes_basket_target import valuation_store  # noqa: PLC0415
    from bayes_basket_target.basket_kernel.valuation_v1 import (  # noqa: PLC0415
        market_reference_v1,
    )

    return _section_fingerprint(
        valuation_store.population,
        _section_fingerprint(valuation_store._decision_vectors)
        + _section_fingerprint(market_reference_v1),
    )


def _charter_ev_decision_memo(
    name: str = CHARTER_EV_DECISION_MEMO,
) -> _TrackedMemo:
    kept = _load_closed_readings(name)
    if kept.get("code") != _charter_ev_memo_code():
        kept = {}
    return _TrackedMemo(kept.get("entries") or {})


def _save_charter_ev_decision_memo(
    memo: _TrackedMemo, name: str = CHARTER_EV_DECISION_MEMO,
) -> None:
    # Not ``_save_closed_readings``: it sorts keys, and a vector's bucket
    # order is the order its sums run in -- a sorted memo moved P1's
    # ic_forward in the last place (2026-10-02).  Insertion order is kept.
    payload = {
        "code": _charter_ev_memo_code(),
        "entries": {key: memo[key] for key in memo.used if key in memo},
    }
    try:
        SECTION_CACHE_DIR.mkdir(parents=True, exist_ok=True)
        tmp = SECTION_CACHE_DIR / f"{name}.{os.getpid()}.tmp"
        tmp.write_text(json.dumps(payload), encoding="utf-8")
        tmp.replace(SECTION_CACHE_DIR / name)
    except OSError:
        pass


def collect_charter_ev(conn: sqlite3.Connection) -> dict[str, Any]:
    """Charter EV identity per stage: Var(e_q), Cov(e_p,e_q), Var - Cov, k.

    Reads the valuation lane's population -- one row per decision with the
    committed envelope's vector, the market mid vector rebuilt from the WS
    snapshot the decision priced against, and the settled bucket -- so this
    page and charter 132's fit describe the same sample.  Two readings per
    stage: the rolling 28-day research population, and the rows since the
    stage's serving-arithmetic anchor, which is the only sample that says
    anything about the vector served today.  Every row of the sample is a
    settled decision; nothing here is a fit and nothing here serves.
    """

    out: dict[str, Any] = {"available": False}
    try:
        from bayes_basket_target.center_width_store import (  # noqa: PLC0415
            evidence_anchor,
        )
        from bayes_basket_target.valuation_store import (  # noqa: PLC0415
            BOOTSTRAP_DRAWS,
            BOOTSTRAP_SEED,
            STAGE_SCOPES,
            WINDOW_DAYS,
            population,
        )
    except ImportError:
        return out
    scopes: list[dict[str, Any]] = []
    window: dict[str, Any] = {}
    p0_anchor: str | None = None
    p0_window: tuple[Any, Any] = (None, None)
    memo = _charter_ev_decision_memo()
    for scope in ("P0", "P0-M", "P1"):
        try:
            rows, meta = population(
                conn, stage_scope=scope, anchored=False, decision_memo=memo,
            )
        except (sqlite3.Error, ValueError) as exc:
            scopes.append({"scope": scope, "error": f"{type(exc).__name__}:{exc}"})
            continue
        if meta.get("error"):
            scopes.append({"scope": scope, "error": str(meta["error"])})
            continue
        window = {
            "days": int(WINDOW_DAYS),
            "floor_day": meta.get("floor_day"),
            "as_of_event_date": meta.get("as_of_event_date"),
        }
        anchor: str | None = None
        anchor_state = "ok"
        try:
            anchor = evidence_anchor(
                conn, stage=STAGE_SCOPES[scope][0],
            )
        except Exception:  # noqa: BLE001 -- a broken anchor store is a reading, not a crash
            anchor_state = "error"
        since_anchor: list[Mapping[str, Any]] = []
        if anchor:
            anchor_at = datetime.fromisoformat(str(anchor).replace("Z", "+00:00"))
            since_anchor = [
                row for row in rows
                if datetime.fromisoformat(str(row["at"]).replace("Z", "+00:00"))
                >= anchor_at
            ]
        # The first decision of each station-day, which is the reading the
        # 2026-09-12 measurement was taken on.  For P1 the two differ by
        # construction: later decisions carry the day's observations, so the
        # all-decisions row reads a better vector than the first one did.
        first_at: dict[tuple[str, str], str] = {}
        for row in rows:
            key = (str(row["station"]), str(row["date"]))
            if key not in first_at or str(row["at"]) < first_at[key]:
                first_at[key] = str(row["at"])
        first_rows = [
            dict(row, weight=1.0) for row in rows
            if first_at.get((str(row["station"]), str(row["date"])))
            == str(row["at"])
        ]
        if scope == "P0":
            p0_anchor = anchor
            p0_window = (meta.get("floor_day"), meta.get("as_of_event_date"))
        scopes.append({
            "scope": scope,
            "research": _charter_ev_reading(
                rows, draws=BOOTSTRAP_DRAWS, seed=BOOTSTRAP_SEED,
            ),
            "first": _charter_ev_reading(
                first_rows, draws=BOOTSTRAP_DRAWS, seed=BOOTSTRAP_SEED,
            ),
            "anchor_utc": anchor,
            "anchor_state": anchor_state,
            "served": (
                _charter_ev_reading(
                    since_anchor, draws=BOOTSTRAP_DRAWS, seed=BOOTSTRAP_SEED,
                )
                if anchor else None
            ),
            "population": {
                key: meta.get(key) for key in (
                    "decisions_read", "no_label", "market_incomplete",
                    "label_outside_contract", "weather_vector_invalid",
                )
            },
        })
    # The P0 gap split into centre and shape (2026-09-22 audit, finding 1),
    # as the backend board-readings job computed it -- the board reads it.
    from bayes_basket_target.board_readings import load_reading  # noqa: PLC0415

    split = load_reading("centre_shape")
    out["centre_shape"] = (
        {**(split.get("value") or {}), "computed_at_utc": split.get("computed_at_utc")}
        if split else {"available": False, "error": "后端读数任务还没写出这一项"}
    )
    # Saved even when a scope failed: every entry is a finished derivation.
    _save_charter_ev_decision_memo(memo)
    out.update({
        "available": any("research" in scope for scope in scopes),
        "scopes": scopes,
        "window": window,
        "bootstrap_draws": int(BOOTSTRAP_DRAWS),
        "computed_at_utc": _now().isoformat().replace("+00:00", "Z"),
    })
    return out


def _load_closed_readings(name: str) -> dict[str, Any]:
    try:
        raw = json.loads((SECTION_CACHE_DIR / name).read_text(encoding="utf-8"))
        return dict(raw) if isinstance(raw, dict) else {}
    except (OSError, ValueError):
        return {}


def _save_closed_readings(name: str, readings: Mapping[str, Any]) -> None:
    try:
        SECTION_CACHE_DIR.mkdir(parents=True, exist_ok=True)
        tmp = SECTION_CACHE_DIR / f"{name}.{os.getpid()}.tmp"
        tmp.write_text(json.dumps(readings, sort_keys=True), encoding="utf-8")
        tmp.replace(SECTION_CACHE_DIR / name)
    except OSError:
        pass


def build_payload(db: Path) -> dict[str, Any]:
    # The connection lives exactly one payload and is closed on every path.
    # It used to be leaked, one per page refresh, and a leaked read-only
    # connection is not harmless on a WAL database: any cursor left
    # unexhausted keeps a read transaction open, checkpointing can never
    # advance past the oldest reader snapshot, and the WAL grew to 417MB --
    # at which point every writer's transaction slowed enough that ordinary
    # lock contention compounded into 45-minute P1 outages (2026-08-24).
    conn = _connect(db)
    started = time.perf_counter()
    if PAGED_RENDER:
        _paged_run_start(db)
        conn.set_progress_handler(_render_yield_check, 20_000)
    try:
        payload = _build_payload(conn, db)
    finally:
        conn.close()
    # Which payload keys each cache landed in, and what fed it, so each
    # section names its own stale inputs (user 2026-10-01).
    payload["section_cache"] = _section_cache_destinations(payload)
    # The render's own cost, on the page.  Reported because the page is a
    # file on a thirty-minute timer, not a live query: a reader who
    # refreshes right after a change sees the PREVIOUS build until the next
    # one lands, and without these two numbers there is no way to tell that
    # from a broken section.  2026-09-09 is the case -- P1's band table
    # moved at 03:23Z, the page on screen was built at 03:07Z, and the
    # build that would have shown the move was twenty-four minutes in.
    elapsed = time.perf_counter() - started
    slowest = sorted(
        (
            {
                "section": name,
                "build_sec": float(entry["build_sec"]),
                "cached": bool(entry.get("cached")),
            }
            for name, entry in _SECTION_CACHE_LOG.items()
            if entry.get("build_sec") is not None
        ),
        key=lambda row: -row["build_sec"],
    )
    payload["render"] = {
        "generated_at_utc": payload.get("generated_at_utc"),
        "build_sec": round(elapsed, 1),
        # What was actually computed this round.  A cached section that was
        # reused contributes nothing here, which is the point: the sum is
        # what THIS build paid, not what a cold build would.
        "computed_sec": round(sum(r["build_sec"] for r in slowest), 1),
        "computed_sections": len(slowest),
        "reused_sections": sum(
            1 for e in _SECTION_CACHE_LOG.values() if e.get("reused")
        ),
        "slowest": slowest[:12],
    }
    if _PAGED_RUN:
        _save_every_run_costs()
        _save_section_specs()
        # What this paged run could not compute and served from its last
        # page instead, and how long it spent waiting for production gaps.
        payload["render"]["paged"] = {
            "gap_wait_sec": round(float(_PAGED_RUN["gap_wait_sec"]), 1),
            "yields": int(_PAGED_RUN["yields"]),
            "stale_sections": dict(_PAGED_RUN["stale"]),
            "soft_budget_sec": RENDER_SOFT_BUDGET_SEC,
        }
        _PAGED_RUN.clear()
    return payload


REGIONAL_SWEEP_JSON = (
    ROOT / "data" / "runtime" / "bayes_basket_target_nwp"
    / "regional_hires_historical_oos.json"
)
# The regional point systems and how each one's archive behaves.
# ``backfillable`` decides how a stale lane reads: the NOAA buckets and
# the RISH mirror keep history, so a stale lane there is a delay; the DWD
# directory keeps only the newest run of each cycle, so a stale lane
# there is runs permanently lost.
REGIONAL_LANES = {
    "JMA_MSM_POINT": {
        "label": "JMA MSM 5km", "region": "东亚",
        "transport": "RISH 京都镜像·字节区间", "backfillable": True},
    "NCEP_HRRR_POINT": {
        "label": "HRRR 3km", "region": "美国",
        "transport": "NOAA S3·idx 区间", "backfillable": True},
    "NCEP_NBM_POINT": {
        "label": "NBM 混合", "region": "美国",
        "transport": "NOAA S3·idx 区间", "backfillable": True},
    "DWD_ICON_EU_POINT": {
        "label": "ICON-EU 7km", "region": "欧洲",
        "transport": "DWD opendata·全域场", "backfillable": False},
    # The aggregator serves only the run it currently holds, so like the DWD
    # lane a missed cycle is gone, not late.
    "CMA_GRAPES_GLOBAL_POINT": {
        "label": "CMA GRAPES 全球", "region": "全球（P1 只读中国 8 站）",
        "transport": "Open-Meteo 聚合·按名取轮", "backfillable": False},
    # Charter 201: the deterministic-forecast family's global members.  P0
    # feature inputs and shadow record only -- P1 never reads them.
    "ECMWF_AIFS_SINGLE_POINT": {
        "label": "AIFS Single 0.25°", "region": "全球",
        "transport": "ECMWF 开放数据 GCS·6 小时步", "backfillable": True},
    "ECMWF_IFS_9KM_RELAY_POINT": {
        "label": "IFS 9km（转发）", "region": "全球",
        "transport": "Open-Meteo 转发·按名取轮", "backfillable": False},
    "UKMO_GLOBAL_10KM_RELAY_POINT": {
        "label": "UKMO 10km（转发）", "region": "全球",
        "transport": "Open-Meteo 转发·按名取轮", "backfillable": False},
}
_SWEEP_MODEL_TO_SYSTEM = {
    "jma_msm": "JMA_MSM_POINT",
    "ncep_hrrr_conus": "NCEP_HRRR_POINT",
    "ncep_nbm_conus": "NCEP_NBM_POINT",
    "dwd_icon_eu": "DWD_ICON_EU_POINT",
}


def _capture_rosters() -> dict[str, set[str]]:
    """Which stations each lane is RULED IN at -- read from the lanes.

    Not inferred from which rows exist.  A station whose lane started an
    hour ago, or whose turn the per-pass cap has not reached, has no rows
    and is not a reversal; reading the roster off the corpus would print
    "measured reversed" over stations that were admitted.  The rosters
    live in the archive modules for exactly this second reader.
    """

    from bayes_basket_target import noaa_conus_archive
    from bayes_basket_target import dwd_icon_eu_point_archive
    from bayes_basket_target import jma_msm_archive  # noqa: F401
    from bayes_basket_target import cma_grapes_point_archive

    rosters = {
        "NCEP_HRRR_POINT": {
            s[0] for s in noaa_conus_archive.CAPTURE_STATIONS["HRRR"]
        },
        "NCEP_NBM_POINT": {
            s[0] for s in noaa_conus_archive.CAPTURE_STATIONS["NBM"]
        },
        "DWD_ICON_EU_POINT": {
            s[0] for s in dwd_icon_eu_point_archive.CAPTURE_STATIONS
        },
        "JMA_MSM_POINT": {
            s[0] for s in getattr(
                jma_msm_archive, "CAPTURE_STATIONS", ()
            )
        },
        # Charter 201: CMA and the family's global members are captured at
        # every roster station with coordinates.
        "CMA_GRAPES_GLOBAL_POINT": {
            s[0] for s in cma_grapes_point_archive.CAPTURE_STATIONS
        } | _global_family_roster(),
        "ECMWF_AIFS_SINGLE_POINT": _global_family_roster(),
        "ECMWF_IFS_9KM_RELAY_POINT": _global_family_roster(),
        "UKMO_GLOBAL_10KM_RELAY_POINT": _global_family_roster(),
    }
    return rosters


def _global_family_roster() -> set[str]:
    from bayes_basket_target.station_registry import _COORDINATES  # noqa: PLC0415

    return set(_COORDINATES)


def _run_rhythm(runs: Sequence[Mapping[str, Any]]) -> dict[str, Any]:
    """A lane's newest runs, its issue rhythm and its publication delay.

    ``runs`` newest first, each with run_utc / capture_utc and their ages.
    The rhythm is the median gap between issue times; the delay is the
    median of issue-to-first-landing.  The next run is due once both have
    elapsed -- the same reading the global families' lamps make.
    """

    runs = list(runs)
    gaps = [
        a["run_age_hours"] - b["run_age_hours"]
        for a, b in zip(runs[1:], runs[:-1])
        if a.get("run_age_hours") is not None and b.get("run_age_hours") is not None
    ][:8]
    lags = [
        r["run_age_hours"] - r["capture_age_hours"]
        for r in runs[:8]
        if r.get("run_age_hours") is not None and r.get("capture_age_hours") is not None
    ]
    cycle = _median([g for g in gaps if g > 0])
    lag = _median([x for x in lags if x >= 0])
    newest = runs[0] if runs else {}
    due = (
        cycle + lag - newest["run_age_hours"]
        if cycle and lag is not None and newest.get("run_age_hours") is not None
        else None
    )
    return {
        "runs_recent": runs[:6],
        "latest_run_capture_utc": newest.get("capture_utc"),
        "latest_run_stations": newest.get("stations"),
        "cycle_hours": cycle, "publish_lag_hours": lag, "due_in_hours": due,
    }


def collect_regional_lanes(conn: sqlite3.Connection) -> dict[str, Any]:
    """The regional capture lanes: corpus growth, race state, verdicts.

    Three questions in one section, because they are one story read at
    three moments: what the 46-pair sweep measured (the reason a lane
    exists), what each lane has captured so far (the corpus the gates
    will re-ask), and where each system stands in the OOS race (what a
    win will buy -- envelope evidence, never a membership seat).
    """

    lanes = []
    rosters = _capture_rosters()
    captured_stations: dict[str, set[str]] = {}
    # The lane P1 actually reads (charter 95 revised 2026-09-06: every run,
    # curve kept hour by hour).  This section used to count the P0 member
    # archive, which the lanes stopped feeding when they moved to P1 -- so
    # CMA, which only ever wrote here, could not appear at all, and the
    # others showed the corpus of a role they no longer have.
    per_station: dict[str, list[dict[str, Any]]] = {}
    for system_id, station, last_run, last_query, runs in conn.execute(
        "SELECT ensemble_system_id, station_id, MAX(run_init_utc),"
        " MAX(archive_query_at_utc), COUNT(DISTINCT run_init_utc)"
        " FROM calibration_regional_point_run"
        " GROUP BY ensemble_system_id, station_id"
    ).fetchall():
        per_station.setdefault(str(system_id), []).append({
            "station_id": str(station), "last_run_init": last_run,
            "run_age_hours": _age_hours(last_run),
            "last_capture_age_hours": _age_hours(last_query),
            "runs": runs,
        })
    # Recent runs per lane with the moment each first landed -- the page
    # head's 发布时间 table (user, 2026-09-18).  First capture, as for the
    # global families: that is when the run became available to us, and it
    # is this system's own definition of availability (knowable_at_utc is
    # written equal to it).  14k rows, one grouped pass.
    since = (_now() - timedelta(days=2)).strftime("%Y-%m-%dT%H:%M:%SZ")
    recent_runs: dict[str, list[dict[str, Any]]] = defaultdict(list)
    for system_id, run_init, stations_n, first_query in conn.execute(
        "SELECT ensemble_system_id, run_init_utc, COUNT(DISTINCT station_id),"
        " MIN(archive_query_at_utc) FROM calibration_regional_point_run"
        " WHERE run_init_utc >= ?"
        " GROUP BY ensemble_system_id, run_init_utc"
        " ORDER BY ensemble_system_id, run_init_utc DESC",
        (since,),
    ).fetchall():
        recent_runs[str(system_id)].append({
            "run_utc": run_init, "capture_utc": first_query,
            "stations": stations_n,
            "run_age_hours": _age_hours(run_init),
            "capture_age_hours": _age_hours(first_query),
        })
    for system_id, meta in REGIONAL_LANES.items():
        row = conn.execute(
            "SELECT COUNT(*), COUNT(DISTINCT station_id),"
            " COUNT(DISTINCT station_id || '|' || target_local_date),"
            " MAX(archive_query_at_utc), MAX(run_init_utc)"
            " FROM calibration_regional_point_run"
            " WHERE ensemble_system_id=?",
            (system_id,),
        ).fetchone()
        rows, stations, station_days, last_query, last_run = row
        captured_stations[system_id] = {
            entry["station_id"] for entry in per_station.get(system_id, [])
        }
        age = _age_hours(last_query)
        # A lane is judged by whether the hourly sweep is still landing
        # rows, on the clock of the product it captures (six-hourly runs,
        # a few hours of publication lag).  For the DWD lane a red is not
        # a delay but permanent loss, which the note says out loud.
        if rows == 0:
            health = "amber"
            note = "道已建，等第一批行落库"
        elif age is not None and age <= 26:
            health = "green"
            note = ""
        elif age is not None and age <= 50:
            health = "amber"
            note = "超过一天没有新行"
        else:
            health = "red"
            note = (
                "断采——DWD 不留历史，错过的 run 永久丢失"
                if not meta["backfillable"]
                else "断采——归档还在，可回填"
            )
        lanes.append({
            "system_id": system_id, **meta,
            "row_count": rows, "station_count": stations,
            # The roster's size beside the count that has rows: a lane
            # at 1/10 is either young or starved, and either way that is
            # the number to look at, not the row total.
            "roster_count": len(rosters.get(system_id, set())),
            "station_days": station_days,
            "last_capture_age_hours": age,
            "last_run_init": last_run,
            "run_age_hours": _age_hours(last_run),
            "health": health, "note": note,
            **_run_rhythm(recent_runs.get(system_id, [])),
        })

    # Race state, from the worker's own OOS ingress readiness -- the same
    # rows the admission gates read, not a reimplementation of them.
    readiness = []
    if STATUS_JSON.is_file():
        try:
            status = json.loads(STATUS_JSON.read_text())
            for entry in (
                status.get("production", {})
                .get("native_ensemble_oos_ingress", {})
                .get("readiness") or []
            ):
                if entry.get("ensemble_system_id") in REGIONAL_LANES:
                    readiness.append(entry)
        except (ValueError, OSError):
            pass

    # The sweep's verdicts, pinned: which pairs earned a lane and which
    # measured reversed.  Only the four systems that HAVE lanes -- the
    # rest of the 46 pairs stay in the evidence file.
    verdicts = []
    if REGIONAL_SWEEP_JSON.is_file():
        try:
            sweep = json.loads(REGIONAL_SWEEP_JSON.read_text())
            for candidate in sweep.get("candidates") or []:
                system_id = _SWEEP_MODEL_TO_SYSTEM.get(
                    str(candidate.get("model"))
                )
                if system_id is None:
                    continue
                station = str(candidate.get("station_id"))
                morning = candidate.get("morning_argmax") or {}
                verdicts.append({
                    "system_id": system_id,
                    "system_label": REGIONAL_LANES[system_id]["label"],
                    "station_id": station,
                    "passes_all_three": bool(
                        candidate.get("passes_all_three")
                    ),
                    "gates": candidate.get("gates") or {},
                    "holdout_days": candidate.get("holdout_days"),
                    "candidate_exact": (morning.get("candidate") or {})
                    .get("exact"),
                    "incumbent_exact": (morning.get("incumbent") or {})
                    .get("exact"),
                    "candidate_within_1": (morning.get("candidate") or {})
                    .get("within_1"),
                    # Two different questions, kept apart on purpose.
                    # ``in_roster`` is the ruling (is this pair captured
                    # at all); ``has_rows`` is progress (has its turn
                    # come yet).  Collapsing them prints "measured
                    # reversed" over stations that were admitted an hour
                    # ago and simply have no rows yet.
                    "in_roster": station in rosters.get(system_id, set()),
                    "has_rows": station in captured_stations[system_id],
                })
        except (ValueError, OSError):
            pass
    verdicts.sort(
        key=lambda v: (
            not v["in_roster"], not v["has_rows"],
            -(v["candidate_exact"] or 0.0),
        )
    )

    # The bias calibration (2026-09-18, global form): the station scope's
    # fitted shift per lane, read off the served artifact.  Fitted daily,
    # served nowhere -- the feature arm is off by measurement.
    calibration: dict[str, Any] = {}
    try:
        from bayes_basket_target import regional_point_debias as rpd  # noqa: PLC0415
        artifact = rpd.load_artifact() or {}
        calibration = {
            "trained_through": artifact.get("trained_through"),
            "rule": artifact.get("rule_version"),
            "feature_arm": bool(rpd.FEATURE_CALIBRATION),
            "stations": {
                system: {
                    station: {
                        "bias_c": (scope.get("station") or {}).get("bias_c"),
                        "train_days": (scope.get("station") or {}).get("train_days"),
                        "cycle_scopes": len(scope.get("cycles") or {}),
                    }
                    for station, scope in (entry.get("stations") or {}).items()
                }
                for system, entry in (artifact.get("systems") or {}).items()
            },
        }
    except Exception:  # noqa: BLE001 - a missing fit is a blank, not a crash
        calibration = {}
    from bayes_basket_target.regional_features import (  # noqa: PLC0415
        MAX_RUN_AGE_HOURS as max_age,
    )
    for system_id, entries in per_station.items():
        fits = (calibration.get("stations") or {}).get(system_id) or {}
        for entry in entries:
            fit = fits.get(entry["station_id"]) or {}
            entry["calibration_bias_c"] = fit.get("bias_c")
            entry["calibration_train_days"] = fit.get("train_days")
            entry["in_roster"] = entry["station_id"] in rosters.get(system_id, set())
            age = entry.get("run_age_hours")
            # Whether a decision now could read this run at all: the P1
            # covariates refuse a run older than this.
            entry["usable_now"] = age is not None and age <= max_age
        entries.sort(key=lambda e: e["station_id"])
    return {
        "lanes": lanes, "readiness": readiness, "verdicts": verdicts,
        "stations": {
            system: per_station.get(system, []) for system in REGIONAL_LANES
        },
        "max_run_age_hours": max_age,
        "calibration": calibration,
    }


# ---------------------------------------------------------------------------
# Section cache
#
# A render rebuilds every section from scratch, and the hosted sweep starts
# one every thirty minutes; measured 2026-09-02 a full build took about
# fourteen minutes, most of it recomputing answers that had not moved since
# the previous build.  Sections whose inputs change on the order of hours
# keep their last value on disk and are recomputed only when it ages out.
#
# What may be cached is decided by two safety rules, not by cost:
#
#   * Nothing that feeds ``alerts`` / ``overall_health``.  The banner is the
#     one thing on this page a reader trusts to mean "now" -- production sat
#     BLOCKED_FAIL_CLOSED for eleven hours behind a healthy heartbeat on
#     2026-08-26 -- so members, chain, band stages and truth materialization
#     are rebuilt every render however long they take.
#   * Nothing about the live book.  Live readiness, open orders and the
#     whole selection payload are what the page is opened for mid-session.
#
# And every cached section carries the moment it was computed, which the
# footer prints, so a cache that quietly stops refreshing reads as stale
# rather than as current.
SECTION_CACHE_DIR = ROOT / "data" / "dashboard_section_cache"
# Bumped by hand when a helper a cached collector calls changes without the
# collector's own body changing -- the fingerprint below sees the collector
# and nothing it calls.  A bump discards every cached section.
SECTION_CACHE_EPOCH = 1
# Lifetimes, deliberately unequal.  Renders come round every thirty minutes;
# equal lifetimes would expire the whole set on one render and put the
# fourteen minutes back in a single go.
SECTION_CACHE_TTL_SEC = {
    "truth_landing": 150 * 60,
    "scorecard": 180 * 60,
    # The previous version's span is closed, so its readings move only as
    # its last event days settle; the trend reads three weeks of both
    # tables (~30s).  Offset from every other lifetime so no two expire on
    # one render.
    "scorecard_previous": 183 * 60,
    # History depth and seats per model family (collect_member_depth): walks
    # every member row, moves by days, colours no light.
    "member_depth": 189 * 60,
    # Charter 206's certificate clock: its red is a certificate ending inside
    # three days or evidence a month old, so an hour's page is nothing
    # against it -- and it read for 38-208 s a render (per-scope counts over
    # the activation table).  Not one of the banner sources the section
    # cache's safety rule pins; it was put in the every-run set on
    # 2026-09-24 and taken out the same day.
    "certificate_authority": 53 * 60,
    # The refusal funnel's closed days (live_selection.closed_plan_summaries):
    # immutable once closed; keyed on (first day, through), so a new day
    # recomputes it and an older page stays exact for its own days.
    "refusal_history": 1375 * 60,
    # Row counts per chain link (collect_chain_volume): display only.
    # Five row counts that "move by the day and colour nothing" (the
    # collector's own words): a day.  At 191 min each ~500 s count fell due
    # eight times a day in a research render that could not keep up, and sat
    # 19 h "overdue" on 2026-10-02 behind the pages that change.
    "chain_volume": 23 * 60 * 60 + 47 * 60,  # a day, staggered off ssot_capacity
    "center_landing_previous": 258 * 60,
    # The served version's own span, for the board's version comparison
    # (charter 202 moved the served landing onto the evidence window).  A new
    # version settles a day at a time, so this refreshes hourly.
    "center_landing_version": 61 * 60,
    "model_accuracy_trend": 262 * 60,
    # 逐站校准排序's 7/30-day and cumulative windows: closed station-days are
    # kept across renders (RENDER_CLOSED_STATION_DAYS), so a read is the last
    # few event days; the key carries the date.
    "station_calibration_windows": 127 * 60,
    "h5_readiness": 195 * 60,
    "skill": 210 * 60,
    # Refits the fleet's bias under each half-life (~5 min); the verdict
    # moves with a settled day at most.
    "center_landing": 255 * 60,
    # Three populations of settled decisions with their books (~60s on the
    # 45GB store); every row is a settled station-day, so the reading moves
    # once a day when the truth lands.
    "charter_ev": 300 * 60,
    # Every settled P1 head over three weeks (~80k rows, one lineage key
    # each); the reading moves once a day when the truth lands.
    "p1_path_skill": 243 * 60,
    # The per-table growth walk counts rows over a day on ten tables, two
    # of which have no index on their time column.  The gauge above it is
    # read from status.json every build and is never cached; only the
    # composition is, and a composition that is half an hour old still
    # names the same tables.
    #
    # Measured 2026-09-17: the largest cached section of the page, by its
    # own build_sec -- 397s in the 12:14Z render, beside a production
    # cycle and a ledger rebuild; 77s read-only at 13:41Z with the disk
    # quiet.  All ten day-counts are scans (eight over covering indexes,
    # the registry and the settlement table over the table itself), and
    # the two maker_shadow tables alone are 36s of the quiet figure.  On a
    # 30-minute render clock a 45-minute TTL rebuilt the walk on nearly
    # every render, ~32 times a day.  The composition moves on the scale
    # of days -- the retention ruling reads it once a day at most -- so a
    # day costs the reading nothing (2026-10-02: six hours still left it 19 h
    # "overdue" behind the pages that change; the live gauge itself is the
    # resident's status, read on every render).
    "ssot_capacity": 24 * 60 * 60,
    # 降水分类评分: one pass over the observation archive's AWC lane
    # (~25s on the 15 GB file); the pairs move once a day, when a local
    # day closes somewhere, so three hours costs the reading nothing.
    # Seven minutes off the scorecard's three hours: cached sections expire
    # on distinct clocks so the slow ones never rebuild in the same render.
    "precip_classification": 3 * 60 * 60 + 7 * 60,
}
# Set by ``--no-section-cache`` so a reader who needs every number computed
# against this instant can have it, at the price of the long build.
SECTION_CACHE_ENABLED = True
#: Set by ``main`` for ``--html-out`` only; see ``RENDER_EVERY_RUN_SECTIONS``.
PAGED_RENDER = False
_SECTION_CACHE_LOG: dict[str, dict[str, Any]] = {}


def _loaded_source(obj: Any) -> str:
    """The source of ``obj`` as this process loaded it, never as the disk has it now.

    ``inspect.getsource`` re-reads the file whenever its mtime has moved and
    slices it at the line numbers the running code was compiled with.  A render
    takes forty minutes, and this file is edited by several sessions a day, so
    an edit landing mid-render handed the fingerprint a slice of the NEW file at
    the OLD offsets: a fragment that fails to tokenize and kills the render
    (2026-09-14: the 05:56Z run died on ``TokenError`` at 06:11Z, minutes after
    an edit to this file, and the page fell 91 minutes behind), or one that
    happens to parse and fingerprints the wrong function, which misses every
    cache and makes the render slower.

    A function defined in this module is sliced from the snapshot taken at
    import, whose line numbers are the running code's own.  Anything else goes
    through ``inspect`` and, if that fails for any reason, through its repr --
    a fingerprint is a cache key, and a render must never die computing one.
    """

    code = getattr(obj, "__code__", None)
    if (
        code is not None
        and _LOADED_SOURCE_LINES
        and getattr(obj, "__globals__", None) is globals()
    ):
        start = int(code.co_firstlineno) - 1
        if 0 <= start < len(_LOADED_SOURCE_LINES):
            try:
                return "".join(
                    inspect.getblock(_LOADED_SOURCE_LINES[start:])
                )
            except Exception:  # noqa: BLE001 - a cache key, never a failure
                pass
    try:
        return inspect.getsource(obj)
    except Exception:  # noqa: BLE001 - a cache key, never a failure
        return repr(obj)


def _section_fingerprint(collector: Any, salt: str = "") -> str:
    """What the cached value was computed from, as one hash.

    The collector's own source, plus whatever the caller declares it also
    reads.  Only the source is free to find; a module-level constant the
    collector merely names -- a band grid, a threshold -- is invisible here,
    so editing one would leave a stale file that still matches its
    fingerprint and keeps serving the retired shape until its TTL runs out.
    Callers pass those in as ``_salt``.
    """

    source = _loaded_source(collector)
    return hashlib.sha256(
        f"{SECTION_CACHE_EPOCH}\n{salt}\n{source}".encode("utf-8")
    ).hexdigest()


#: A section slower than this is written to stderr as it finishes.  The
#: per-section timings otherwise reach only the payload, and a render killed
#: at its deadline writes no payload: from 13:18Z on 2026-09-23 eleven
#: hours of renders died at 1,500 s and the log said nothing but "killed".
SLOW_SECTION_TRACE_SEC = 20.0


def _trace_slow_section(name: str, elapsed: float) -> None:
    if elapsed >= SLOW_SECTION_TRACE_SEC:
        print(
            f"[{_now().strftime('%Y-%m-%dT%H:%M:%SZ')}] section {name}"
            f" {elapsed:.1f}s",
            file=sys.stderr,
            flush=True,
        )


#: Paged rendering (user ruling 2026-09-24: 「能分区分页渲染吗？不要一次性，
#: 找生产的空隙」).  The page is built one section at a time, and every
#: section is a page of its own:
#:
#: * it starts reading only in a production gap -- no production cycle in
#:   flight and the store's WAL under the resident's maintenance line --
#:   so a render never reads beside a cycle and never starts a read the
#:   writer's truncating checkpoint would have to wait out;
#: * it gives its read up mid-statement if the WAL crosses that line (a
#:   progress handler interrupts it), and the section is served from its
#:   last page instead;
#: * it is written to the section cache the moment it is done, so a run
#:   that is killed or runs out of budget loses only the section in hand and
#:   the next run carries on from there;
#: * once the run's soft budget is spent, every section still due is served
#:   from its last page, with its age on the page, and the page is written.
#:
#: The render used to be one read of the whole store.  The last one to
#: finish (2026-09-23 06:53Z) took 7,337 s -- truth_landing alone 2,646 s --
#: and from 13:18Z every run was killed at the 1,500 s deadline, so the page
#: kept that payload for eighteen hours while the lamps on it went red.
#: Two of those runs were killed by hand because their reads held the WAL
#: the resident needed to truncate before it could reopen its writer.
#:
#: Only the ``--html-out`` render pages (``_PAGED_RUN`` is empty otherwise):
#: ``--json``, ``serve`` and the tests build exactly as before.
#:
#: Never paged, on every run: the sections where a stale answer is a wrong
#: answer (tests/test_dashboard_section_cache.py's two safety rules).
RENDER_EVERY_RUN_SECTIONS = frozenset({
    # The freshness lamps and clocks: a lamp that can be a page old is a
    # lamp that says green through an outage.
    "hosted_sweeps", "observation_intake",
    # The 发布时间 table's regional and TAF rows, whose "next run due" is
    # read against the viewer's clock: served from a page, the regional
    # section was 43 hours old on 2026-09-26 (no production gap since
    # 09-24 09:54Z) and the table read 「比常态晚 40.0 小时」 for lanes whose
    # newest run had landed within the hour.  1.6 s and 0.1 s to read.
    "regional", "taf_board",
    # Everything the banner's light is derived from.
    "members", "chain", "truth_materialization",
    # What each open day's P0 seats, and the runs behind it: a page of them
    # 10.7 h and 9.4 h old on 2026-10-01 left the 入围 lamps on the night
    # before and the 发布时间 arrivals blank.  2.7 s and 1.7 s to read.
    "member_admission", "recent_runs",
    "delta_v2_authority",
    # The live book: what the page is opened for mid-session.
    "live_readiness", "live_selection", "live_days", "live_money",
    # The remaining strategy lanes' money pages: the same live book, cut
    # by each lane's decision rows.  As
    # page-backed sections with a four-minute lifetime they were reached at
    # the end of the run, never inside a gap, and served "from its page (no
    # gap)" on every render from 2026-09-24 09:33Z: on 09-25 13:37Z the page
    # read 55 settled tiebreak legs at -27.45 USDC while the book held 71 at
    # -1.04, the day of the charter-146 review (user: 「但是前端显示的数据却不
    # 一样」).  A P&L a day old is a wrong P&L, not a slow one.
    "tiebreak_lane", "proper_bet_lane",
    "tail_short_lane",
    # Charter 257: the copy-follow lane's page, read on every run like the lanes above.
    "copy_follow_lane",
    # Charter 254: the lanes' shadow legs beside them -- one small table and
    # one file, read on every run like the lanes they shadow.
    "realisation_layer",
})
#: A section that cost at least this much last time is the research render's
#: to compute (``--refresh-research``, its own launchd clock, user ruling
#: 2026-09-24 「单开研究节渲染」): the page render serves its page and moves
#: on.  The page render's 1,500 s cannot hold them -- bias_half_life 1,249 s,
#: lambda_axis_realisation 793 s, band_residual_audit 651 s -- and a run that
#: starts one either dies at the deadline or leaves no room for the rest.
RESEARCH_SECTION_MIN_COST_SEC = 300.0
#: How each paged section was last called (collector, inputs, key), written
#: by the page render so the research render calls it the same way.
RENDER_SECTION_SPECS = "_section_specs.json"
#: The every-run sections' last costs, so a paged run leaves them room.
#: Recorded as each one finishes, not at the end: a run killed before its
#: end would otherwise never record the costs that would have saved it.
RENDER_EVERY_RUN_COSTS = "_every_run_costs.json"
#: Room kept for an every-run section with no recorded cost yet.
RENDER_EVERY_RUN_DEFAULT_COST_SEC = 60.0
#: Total a run may spend waiting for gaps, every section together.  A wait
#: only moves a read into a gap when one is near; the WAL line, not the wait,
#: is what protects production.  Per-section caps with no total let the
#: 03:30Z run spend 480 s of its budget waiting through back-to-back
#: catch-up cycles -- on sections fed by ``members`` (which changes every
#: run, so they never have a page) and on ones whose key moved that day.
#: 120 s since the 06:47Z run: with production cycles back to back, 240 s
#: of its 1,500 were spent waiting for gaps that did not come.
RENDER_GAP_WAIT_BUDGET_SEC = 120.0
#: How long a section without a lifetime of its own serves from its page.
#: One render interval: a section computed by one run is reused by the next
#: and recomputed by the one after, so the store is read about half as often
#: and an interrupted run resumes instead of starting over.
PAGED_SECTION_TTL_SEC = 1800
#: When the run stops computing and starts assembling.  Five minutes under
#: the sweep's 1,500 s kill, so the page is written before the deadline.
RENDER_SOFT_BUDGET_SEC = float(
    os.environ.get("PM_DASHBOARD_RENDER_SOFT_BUDGET_SEC", "1200")
)
#: When the run stops reading altogether, every-run sections included: the
#: read in hand is interrupted and each section still due is served from its
#: last value, marked overdue, so the page is written before the sweep's
#: 1,500 s kill.  The soft budget bounds only page-backed sections; the
#: every-run ones read on past it, and on a machine deep in swap one of them
#: can take ten times its usual cost -- 2026-10-01 11:25Z, 12:20Z and 13:15Z
#: were all killed at 1,500 s (regional 792 s and 691 s against its usual
#: 20-60 s, members 340 s), wrote nothing, and the whole board kept the
#: 10:54Z page: every lamp and every section frozen for three hours.
RENDER_HARD_DEADLINE_SEC = float(
    os.environ.get("PM_DASHBOARD_RENDER_HARD_DEADLINE_SEC", "1380")
)
#: Where an every-run section's last value is kept -- served only once the
#: run is past ``RENDER_HARD_DEADLINE_SEC``, always marked overdue, never as
#: this run's answer.
EVERY_RUN_LAST_DIR_NAME = "_every_run_last"
#: The resident's maintenance line (TARGET_SSOT_WARN_WAL_BYTES): above it
#: the resident tries to truncate the WAL, and a reader is what stops it.
#: No section STARTS a read above it (and the sweep does not start at all).
RENDER_MAX_WAL_BYTES = int(
    os.environ.get("PM_DASHBOARD_RENDER_MAX_WAL_BYTES", str(256 * 1024 * 1024))
)
#: The line a read already in progress gives way at (user ruling 2026-09-24
#: 「提线」).  At 256 MiB every-run sections of 30-460 s on the saturated
#: disk were interrupted run after run: the WAL rests at 64 MiB
#: (journal_size_limit) and production's own writes during one such read
#: carried it past 256.  384 MiB lets them finish and still leaves 128 MiB
#: before resource_bounds.MAX_TARGET_WAL_BYTES (512 MiB), where production
#: fails closed -- the price accepted: while a render read runs, the
#: resident's truncate at 256 MiB waits for it.
RENDER_YIELD_WAL_BYTES = int(
    os.environ.get("PM_DASHBOARD_RENDER_YIELD_WAL_BYTES", str(384 * 1024 * 1024))
)
RENDER_GAP_POLL_SEC = 5.0
#: One section waits at most this long for a gap when it cannot be served
#: from a page, then reads anyway: a page with no lamps is the worse outcome.
LIVE_SECTION_GAP_CAP_SEC = 60.0
#: A status file older than this cannot say whether a cycle is in flight.
RENDER_STATUS_FRESH_SEC = 180.0
_PAGED_RUN: dict[str, Any] = {}


class SectionNotReady(Exception):
    """A collector that builds its answer over several paged runs and has
    not finished: serve its page, else its stand-in; never cache anything."""


class RenderYielded(Exception):
    """The run stepped aside for the writer: the WAL crossed the line and
    the section in hand has no page to serve instead.  The page on disk is
    kept; the next interval is the retry (and starts only under the line).

    2026-09-24 02:12Z, the first paged run: ``members`` -- an every-run
    section, then exempt from yielding on the belief that such sections read
    for seconds -- read for 254 s while the post-recovery catch-up grew the
    WAL by ~700 MB, and the resident's 02:19:30Z truncate came back busy
    with 17,533 of 180,558 frames backfilled.  Production was fail-closed
    again from 02:27Z.  Nothing reads past the line now.
    """


def _paged_run_start(db: Path) -> None:
    _PAGED_RUN.clear()
    _PAGED_RUN.update({
        "started": time.monotonic(),
        "wal": db.with_name(db.name + "-wal"),
        "armed": False,
        "yielded": False,
        "wal_checked": 0.0,
        "wal_over": False,
        "gap_wait_sec": 0.0,
        "gap_wait_left": RENDER_GAP_WAIT_BUDGET_SEC,
        "yields": 0,
        "stale": {},
        "every_run_costs": _load_every_run_costs(),
    })


def _load_every_run_costs() -> dict[str, float]:
    try:
        raw = json.loads(
            (SECTION_CACHE_DIR / RENDER_EVERY_RUN_COSTS).read_text(encoding="utf-8")
        )
        return {
            str(k): float(v) for k, v in raw.items()
            if str(k) in RENDER_EVERY_RUN_SECTIONS
        }
    except (OSError, ValueError, TypeError, AttributeError):
        return {}


def _save_every_run_costs() -> None:
    costs = _PAGED_RUN.setdefault("every_run_costs", {})
    for name in RENDER_EVERY_RUN_SECTIONS:
        entry = _SECTION_CACHE_LOG.get(name) or {}
        if entry.get("build_sec") is not None:
            costs[name] = float(entry["build_sec"])
    try:
        SECTION_CACHE_DIR.mkdir(parents=True, exist_ok=True)
        tmp = SECTION_CACHE_DIR / f"{RENDER_EVERY_RUN_COSTS}.{os.getpid()}.tmp"
        tmp.write_text(json.dumps(costs, sort_keys=True), encoding="utf-8")
        tmp.replace(SECTION_CACHE_DIR / RENDER_EVERY_RUN_COSTS)
    except OSError:
        pass


def _every_run_reserve_sec() -> float:
    """What the every-run sections not yet reached will cost, from last time."""

    costs = _PAGED_RUN.get("every_run_costs") or {}
    return sum(
        costs.get(name, RENDER_EVERY_RUN_DEFAULT_COST_SEC)
        for name in RENDER_EVERY_RUN_SECTIONS
        if name not in _SECTION_CACHE_LOG
    )


def _build_live_selection(
    conn: sqlite3.Connection, closed: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """``live_selection.build`` on the run's one live book (it built its
    own: 246 s for the section on the 2026-09-24 06:22Z run), with the
    refusal funnel's closed days handed in (``refusal_history``)."""

    return live_selection.build(
        conn, book=_render_live_book(conn), closed=closed,
    )


def _refusal_history_window(conn: sqlite3.Connection) -> tuple[str | None, str]:
    """The live book's first day, and the last day that takes no more
    opening decisions (two back: P0 decides before its event day)."""

    legs = _render_live_book(conn).get("legs") or []
    first_day = min((str(leg["event_date"]) for leg in legs), default=None)
    through = (_now() - timedelta(days=2)).strftime("%Y-%m-%d")
    if first_day is None or first_day > through:
        return None, through
    return first_day, through


def _collect_refusal_history(
    conn: sqlite3.Connection, first_day: str, through: str,
) -> dict[str, Any]:
    return live_selection.closed_plan_summaries(conn, first_day, through)


def _render_live_book(conn: sqlite3.Connection) -> dict[str, Any]:
    """The live book, built once per paged run and shared by its sections.

    ``live_book.build`` caches per database state (``PRAGMA data_version``),
    and production commits between any two sections, so a render rebuilt
    the same book for each of the eight sections that read it.  One book per
    run is also one answer per page: the money cards and the station rows
    no longer read books a few minutes apart.  Outside a paged run the
    module's own cache is left to decide.
    """

    if not _PAGED_RUN:
        return live_book.build(conn)
    book = _PAGED_RUN.get("live_book")
    if book is None:
        book = live_book.build(conn)
        _PAGED_RUN["live_book"] = book
    return book


def _paged_elapsed() -> float:
    return time.monotonic() - float(_PAGED_RUN["started"])


def _render_deadline_alerts() -> list[dict[str, Any]]:
    """An every-run section this run served from its last value: the lamps
    it feeds are that value's age, not now, and the banner says so."""

    if not _PAGED_RUN.get("deadline_hit"):
        return []
    late = [
        name for name, reason in (_PAGED_RUN.get("stale") or {}).items()
        if reason == "deadline" and name in RENDER_EVERY_RUN_SECTIONS
    ]
    if not late:
        return []
    ages = {
        name: round(float((_SECTION_CACHE_LOG.get(name) or {}).get("age_sec") or 0) / 60)
        for name in late
    }
    return [{
        "health": "amber",
        "label": "看板本轮超时",
        "note": f"渲染到 {RENDER_HARD_DEADLINE_SEC:.0f} 秒截止，这些区块沿用上一轮："
        + "、".join(f"{name} {ages[name]} 分钟前" for name in sorted(late)),
    }]


def _paged_past_deadline() -> bool:
    """Past ``RENDER_HARD_DEADLINE_SEC``; latched, so every later section
    sees the same answer.  The research render (``force``) has its own
    launchd timeout and no page to write, so it never latches."""

    if not _PAGED_RUN or _PAGED_RUN.get("force"):
        return False
    if not _PAGED_RUN.get("deadline_hit") and _paged_elapsed() >= RENDER_HARD_DEADLINE_SEC:
        _PAGED_RUN["deadline_hit"] = True
    return bool(_PAGED_RUN.get("deadline_hit"))


def _every_run_last_path(name: str, collector: Any) -> Path:
    """Keyed on the collector's code, so whether a run has a last value it
    may serve is one ``stat`` -- never across a code change, as for pages."""

    fingerprint = _section_fingerprint(collector, "")[:16]
    return SECTION_CACHE_DIR / EVERY_RUN_LAST_DIR_NAME / f"{name}.{fingerprint}.json"


def _save_every_run_last(name: str, collector: Any, value: Any) -> None:
    """Keep an every-run section's value for a run that hits the deadline."""

    path = _every_run_last_path(name, collector)
    try:
        text = json.dumps(
            {
                "schema": "dashboard_every_run_last_v1",
                "section": name,
                "code_fingerprint": _section_fingerprint(collector, ""),
                "computed_at_utc": _now().isoformat().replace("+00:00", "Z"),
                "value": value,
            },
            ensure_ascii=False,
        )
        path.parent.mkdir(parents=True, exist_ok=True)
        tmp = path.with_name(f"{path.name}.{os.getpid()}.tmp")
        tmp.write_text(text, encoding="utf-8")
        tmp.replace(path)
        for older in path.parent.glob(f"{name}.*.json"):
            if older != path:
                older.unlink(missing_ok=True)
    except (OSError, TypeError, ValueError):
        pass


def _serve_every_run_last(name: str, collector: Any) -> tuple[bool, Any]:
    """An every-run section's last value, past the deadline, marked overdue.

    ``(False, None)`` when there is none from this code: never across a code
    change, as for pages.
    """

    try:
        blob = json.loads(_every_run_last_path(name, collector).read_text(encoding="utf-8"))
        if blob.get("code_fingerprint") != _section_fingerprint(collector, ""):
            return False, None
        stamp = str(blob["computed_at_utc"])
        age = (
            _now() - datetime.fromisoformat(stamp.replace("Z", "+00:00"))
        ).total_seconds()
        if "value" not in blob:
            return False, None
    except (OSError, ValueError, KeyError, TypeError, AttributeError):
        return False, None
    return True, _serve_stale_page(name, blob, 0, age, "deadline")


def _render_wal_bytes() -> int:
    try:
        return int(Path(_PAGED_RUN["wal"]).stat().st_size)
    except OSError:
        return 0


def _production_gap_blocker(
    wal_line: int | None = None,
) -> str | None:
    """Why a section should not start reading right now, or None.

    ``wal_line``: the WAL size past which it may not start -- the start line
    (``RENDER_MAX_WAL_BYTES``) by default; sections with nothing else to
    serve pass the yield line instead (see ``_await_production_gap``).
    """

    wal_bytes = _render_wal_bytes()
    if wal_bytes > (RENDER_MAX_WAL_BYTES if wal_line is None else wal_line):
        return f"wal {wal_bytes}"
    try:
        status = json.loads(STATUS_JSON.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return None
    age = _age_hours(status.get("heartbeat_at"))
    if (
        age is not None
        and age * 3600.0 <= RENDER_STATUS_FRESH_SEC
        and status.get("production_inflight")
    ):
        return "production cycle in flight"
    return None


def _await_production_gap(
    name: str, cap_sec: float, wal_line: int | None = None,
) -> str | None:
    """Wait for a production gap, at most ``cap_sec`` and at most what is
    left of the run's shared wait budget; the blocker left, if any.

    A section with a page starts only under the start line (256 MiB); one
    with nothing else to serve -- every-run, or pageless -- may start up to
    the yield line (384 MiB), the same line its read would give way at.
    Holding those to 256 made the 06:22Z run step aside whole on
    live_readiness at 305 MiB, a WAL a read already running would have been
    let through (user ruling 「提线」).
    """

    cap_sec = min(cap_sec, float(_PAGED_RUN["gap_wait_left"]))
    waited = 0.0
    blocker = _production_gap_blocker(wal_line)
    while blocker is not None:
        if waited >= cap_sec:
            break
        pause = min(RENDER_GAP_POLL_SEC, max(0.0, cap_sec - waited))
        time.sleep(pause)
        waited += pause
        blocker = _production_gap_blocker(wal_line)
    _PAGED_RUN["gap_wait_sec"] = float(_PAGED_RUN["gap_wait_sec"]) + waited
    _PAGED_RUN["gap_wait_left"] = max(
        0.0, float(_PAGED_RUN["gap_wait_left"]) - waited
    )
    if waited >= 30.0:
        print(
            f"[{_now().strftime('%Y-%m-%dT%H:%M:%SZ')}] section {name}"
            f" waited {waited:.0f}s for a production gap"
            + ("" if blocker is None else f"; still {blocker}"),
            file=sys.stderr,
            flush=True,
        )
    return blocker


def _render_yield_check() -> int:
    """Progress handler: interrupt a render read once the WAL crosses
    ``RENDER_YIELD_WAL_BYTES``.

    Checked at most once a second, and only while a section is armed --
    every section read under a paged render is.
    """

    if not _PAGED_RUN or not _PAGED_RUN.get("armed"):
        return 0
    if _PAGED_RUN.get("deadline_fallback") and _paged_past_deadline():
        _PAGED_RUN["yielded"] = True
        return 1
    now = time.monotonic()
    if now - float(_PAGED_RUN["wal_checked"]) >= 1.0:
        _PAGED_RUN["wal_checked"] = now
        _PAGED_RUN["wal_over"] = _render_wal_bytes() > RENDER_YIELD_WAL_BYTES
    if _PAGED_RUN["wal_over"]:
        _PAGED_RUN["yielded"] = True
        return 1
    return 0


def _paged_args_salt(args: tuple[Any, ...], kwargs: dict[str, Any]) -> str | None:
    """The inputs a paged section was computed from, as part of its key.

    Sections that take another section's output (``gaps`` takes members,
    stages and tables) may only reuse a page computed from the same inputs.
    None when the inputs cannot be written down: such a section is always
    computed.
    """

    if len(args) <= 1 and not kwargs:
        return ""
    try:
        text = json.dumps(
            [list(args[1:]), kwargs], sort_keys=True, ensure_ascii=False,
            default=str,
        )
    except (TypeError, ValueError):
        return None
    return hashlib.sha256(text.encode("utf-8")).hexdigest()


def _serve_stale_page(
    name: str, blob: dict[str, Any], ttl: float, age: float, reason: str,
    inputs_moved: bool = False,
) -> Any:
    if inputs_moved:
        reason = f"{reason}, inputs moved"
    _SECTION_CACHE_LOG[name] = {
        "computed_at_utc": str(blob["computed_at_utc"]),
        "age_sec": round(age),
        "ttl_sec": ttl,
        "reused": True,
        "cached": True,
        "stale": True,
        "stale_reason": reason,
    }
    _PAGED_RUN["stale"][name] = reason
    print(
        f"[{_now().strftime('%Y-%m-%dT%H:%M:%SZ')}] section {name}"
        f" served from its page ({reason}), {age / 60:.0f} min old",
        file=sys.stderr,
        flush=True,
    )
    return blob["value"]


#: ``_unavailable`` default: the section declared nothing to show instead.
_NO_UNAVAILABLE = object()


def _record_section_spec(
    name: str, collector: Any, args: tuple[Any, ...],
    kwargs: dict[str, Any], salt: str, unavailable: Any,
) -> None:
    """Note how a paged section was called, for the research render.

    Only calls it can repeat: a module-level collector whose inputs past the
    connection can be written down.  The page render writes these out at the
    end of its run (``_save_section_specs``).
    """

    try:
        module = str(collector.__module__)
        spec = {
            # The board itself runs as __main__ under launchd and as
            # calibration_dashboard when imported; one name for both.
            "module": (
                "calibration_dashboard" if module in ("__main__", __name__)
                else module
            ),
            "collector": str(collector.__qualname__),
            "args": json.loads(json.dumps(list(args[1:]))),
            "kwargs": json.loads(json.dumps(kwargs)),
            "salt": salt,
            "unavailable": (
                None if unavailable is _NO_UNAVAILABLE
                else {"value": json.loads(json.dumps(unavailable))}
            ),
        }
    except (TypeError, ValueError, AttributeError):
        return
    if "." in spec["collector"]:
        return
    specs = _PAGED_RUN.setdefault("specs", {})
    if specs.get(name) == spec:
        return
    specs[name] = spec
    # Written as each one is met, not at the end: a page render killed at
    # its deadline must still leave the research render its calls.
    on_disk = _PAGED_RUN.setdefault(
        "specs_on_disk", _load_closed_readings(RENDER_SECTION_SPECS)
    )
    if on_disk.get(name) != spec:
        on_disk[name] = spec
        _save_closed_readings(RENDER_SECTION_SPECS, on_disk)


def _save_section_specs() -> None:
    specs = _PAGED_RUN.get("specs") or {}
    if not specs:
        return
    kept = _live_specs(_load_closed_readings(RENDER_SECTION_SPECS))
    _save_closed_readings(RENDER_SECTION_SPECS, {**kept, **specs})


def _resolve_collector(spec: Mapping[str, Any]) -> Any:
    module_name = str(spec["module"])
    if module_name == "calibration_dashboard":
        module = sys.modules[__name__]
    else:
        module = sys.modules.get(module_name) or importlib.import_module(module_name)
    return getattr(module, str(spec["collector"]))


def _live_specs(specs: Mapping[str, Any]) -> dict[str, Any]:
    """The recorded calls whose collector the code still has.

    The spec file keeps every section a page render has met, and a section
    that leaves the page leaves its call behind: on 2026-09-26 the research
    render died at 16:55Z on the beta section's collector, removed from the
    page an hour earlier, and refreshed nothing.  A retired section is
    skipped here and dropped from the file at the next save.
    """

    live: dict[str, Any] = {}
    for name, spec in specs.items():
        try:
            _resolve_collector(spec)
        except (AttributeError, ImportError, KeyError, TypeError):
            continue
        live[name] = spec
    return live


#: A page the page render has not refreshed in this long is starved.  The
#: every-run sections alone spent 1,080 of the page render's 1,200 s on
#: 2026-09-26 (live_selection 408 s, live_days 221 s, live_readiness 165 s),
#: so every page-backed section met after them was served from its page run
#: after run, however cheap: the model weights (15 s), centre/width (30 s)
#: and OOS scores (17 s) sat 52 hours old and the scorecard 62, still saying
#: 「四大模型」 and printing a gate charter 228 had retired (user: 「全面检查旧
#: 的内容」).  The research render refreshes starved pages as well as heavy
#: ones, the most overdue first.
STARVED_PAGE_AGE_SEC = 3 * 3600
#: What one research run may spend: under its launchd timeout
#: (dashboard_research_sweep.sh, 3,300 s) with room for the section in hand.
RESEARCH_RUN_BUDGET_SEC = 1800.0
#: A heavy page that does not fit a run after the cheap ones is taken first
#: only while no cheap page is older than this (``research_due``).
RESEARCH_CHEAP_STARVE_CAP_SEC = 2 * STARVED_PAGE_AGE_SEC
#: The section a research run is building, written as it starts and removed
#: as it ends; found at the next run's start, it names the section the last
#: run died on (the sweep's timeout kills the process, not the section).
RESEARCH_ATTEMPT_FILE = "_research_attempt.json"
#: Sections a research run died on, with when (``RESEARCH_ATTEMPT_FILE``).
RESEARCH_KILLED_FILE = "_research_killed.json"
#: How long a section that killed a run waits behind the others.  The
#: oldest-first rotation otherwise hands it the next run straight back: on
#: 2026-10-02 bias_half_life (2,804 s last time) ran into the 3,300 s timeout
#: at 09:16Z, kept its old page, stayed the oldest, and would have taken
#: every hour after it.
RESEARCH_KILLED_BACKOFF_SEC = 6 * 3600
#: The page render, as the research sweep finds it (``pgrep -f``).
PAGE_RENDER_PATTERN = "calibration_dashboard.py --html-out"


def _page_render_running() -> bool:
    try:
        return subprocess.run(
            ["pgrep", "-f", PAGE_RENDER_PATTERN],
            capture_output=True, timeout=10, check=False,
        ).returncode == 0
    except (OSError, subprocess.SubprocessError):
        return False


def research_due(specs: Mapping[str, Any], now: datetime) -> list[tuple[float, str, float]]:
    """The sections a research run owes, most overdue first: every heavy
    section past its lifetime, and every other section whose page is older
    than ``STARVED_PAGE_AGE_SEC`` and its lifetime.  ``(age / lifetime, name,
    last build cost)``; a section with no page yet is infinitely overdue."""

    due: list[tuple[float, str, float]] = []
    _page_ages: dict[str, float] = {}
    killed_at = {
        name: stamp for name, stamp in (
            _load_closed_readings(RESEARCH_KILLED_FILE).get("killed") or {}
        ).items()
        if (stamp_at := _parse_utc_or_none(stamp)) is not None
        and (now - stamp_at).total_seconds() < RESEARCH_KILLED_BACKOFF_SEC
    }
    for name in specs:
        # The page render computes these every run and never keeps a page,
        # so a page file left from before they joined that set never ages
        # out: on 2026-10-01 tiebreak_lane, regional and taf_board ranked
        # first in every research run (overdue 333x, pages dated 09-24/25),
        # were recomputed for 5-15 minutes, saved nothing, and the run hit
        # the page render before reaching model_accuracy_trend (39 h old).
        if name in RENDER_EVERY_RUN_SECTIONS:
            continue
        path = SECTION_CACHE_DIR / f"{name}.json"
        try:
            blob = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            blob = {}
        cost = float(blob.get("build_sec") or 0.0)
        ttl = SECTION_CACHE_TTL_SEC.get(name) or PAGED_SECTION_TTL_SEC
        stamp = _parse_utc_or_none(blob.get("computed_at_utc"))
        age = (now - stamp).total_seconds() if stamp else float("inf")
        # A page the page render cannot serve is no page, whatever its date:
        # across a code change it is "not shown this run; it has no page
        # yet" on the board, and ranked here by its file's age it waited
        # behind older servable pages -- truth_landing, last built 09-30,
        # sat off the board through 10-02 while this read it as 48 h old.
        if blob.get("code_fingerprint"):
            try:
                current = _section_fingerprint(
                    _resolve_collector(specs[name]), ""
                )
            except Exception:  # noqa: BLE001 -- unresolvable: keep the file's age
                current = None
            if current is not None and blob.get("code_fingerprint") != current:
                age = float("inf")
        line = ttl if cost >= RESEARCH_SECTION_MIN_COST_SEC else max(ttl, STARVED_PAGE_AGE_SEC)
        if age >= line:
            due.append((age / ttl, name, cost))
            _page_ages[name] = age
    # The cheap pages first, then the heavy ones, each most overdue first.
    # By overdue alone a heavy page led every run: on 2026-10-01 run_cadence
    # took 1,972 s of one run's 1,800, and the cheap pages behind it --
    # certificate_authority 14 s, chain_volume 56 s, ssot_capacity 45 s --
    # sat 17-29 hours old on the board.  26 cheap pages cost ~1,540 s
    # together and fall due again only after STARVED_PAGE_AGE_SEC, so the
    # runs in between are the heavy pages'.
    #
    # The heavy pages among themselves go oldest page first, not most
    # overdue: their lifetimes (2.5-6 h) ask ~72,000 s of reading a day of a
    # render that has ~20,000, so every heavy page is overdue always, and by
    # age / lifetime the shortest lifetimes led every run -- on 2026-10-02
    # skill (3.5 h, 632 s) sat 56 hours old while truth_landing (2.5 h) and
    # scorecard (3 h) were refreshed again and again ahead of it.  Oldest
    # first is a rotation: no heavy page waits longer than one lap.
    due.sort(key=lambda item: (
        item[1] in killed_at,
        item[2] >= RESEARCH_SECTION_MIN_COST_SEC,
        -(_page_ages[item[1]] if item[2] >= RESEARCH_SECTION_MIN_COST_SEC else item[0]),
        item[1],
    ))
    # But a heavy page the run's own budget rule would pass over behind the
    # others never comes round at all: cheap pages fall due every few hours,
    # so a section whose cost does not fit after them was skipped run after
    # run -- on 2026-10-02 bias_half_life (2,804 s) was 102 hours old,
    # run_cadence (1,900 s) 11 and member_depth 37.  The most overdue of the
    # pages the run would skip goes first instead, as long as no cheap page
    # has been starved past ``RESEARCH_CHEAP_STARVE_CAP_SEC`` -- one run in
    # a few is the cheap pages' alone, so neither queue starves the other.
    oldest_cheap = max(
        (_page_ages[name] for _o, name, cost in due
         if cost < RESEARCH_SECTION_MIN_COST_SEC),
        default=0.0,
    )
    if oldest_cheap < RESEARCH_CHEAP_STARVE_CAP_SEC:
        spent, skipped = 0.0, []
        for item in due:
            if spent and spent + item[2] > RESEARCH_RUN_BUDGET_SEC:
                if (
                    item[2] >= RESEARCH_SECTION_MIN_COST_SEC
                    and item[1] not in killed_at
                ):
                    skipped.append(item)
                continue
            spent += item[2]
        if skipped:
            first = max(skipped, key=lambda item: (_page_ages[item[1]], item[1]))
            due.remove(first)
            due.insert(0, first)
    return due


#: What is left of the research run's gap-wait budget, shared by its
#: sections as the page render's are (``RENDER_GAP_WAIT_BUDGET_SEC``).  Each
#: section used to start a fresh budget, so each waited its full 60 s for a
#: gap that, with production cycles back to back, did not come: on
#: 2026-10-01 nearly every research section logged 「waited 60s ... still
#: production cycle in flight」 and then read anyway.
_RESEARCH_GAP_WAIT_LEFT: list[float] = []


def _note_research_death() -> None:
    """A section the last research run started and never finished killed it."""

    path = SECTION_CACHE_DIR / RESEARCH_ATTEMPT_FILE
    attempt = _load_closed_readings(RESEARCH_ATTEMPT_FILE)
    if not attempt:
        return
    ledger = _load_closed_readings(RESEARCH_KILLED_FILE)
    killed = dict(ledger.get("killed") or {})
    if attempt.get("name"):
        killed[str(attempt["name"])] = str(attempt.get("started_at_utc") or "")
    _save_closed_readings(RESEARCH_KILLED_FILE, {"killed": killed})
    try:
        path.unlink()
    except OSError:
        pass


def _refresh_one_section(db: Path, name: str, spec: Mapping[str, Any]) -> str:
    _save_closed_readings(RESEARCH_ATTEMPT_FILE, {
        "name": name,
        "started_at_utc": _now().isoformat().replace("+00:00", "Z"),
    })
    try:
        return _refresh_one_section_inner(db, name, spec)
    finally:
        try:
            (SECTION_CACHE_DIR / RESEARCH_ATTEMPT_FILE).unlink()
        except OSError:
            pass


def _refresh_one_section_inner(db: Path, name: str, spec: Mapping[str, Any]) -> str:
    collector = _resolve_collector(spec)
    conn = _connect(db)
    _paged_run_start(db)
    _PAGED_RUN["force"] = name
    if _RESEARCH_GAP_WAIT_LEFT:
        _PAGED_RUN["gap_wait_left"] = _RESEARCH_GAP_WAIT_LEFT[0]
    conn.set_progress_handler(_render_yield_check, 20_000)
    started = time.perf_counter()
    try:
        kwargs = dict(spec.get("kwargs") or {})
        unavailable = spec.get("unavailable")
        if unavailable is not None:
            kwargs["_unavailable"] = unavailable.get("value")
        _cached_section(
            name, collector, conn, *(spec.get("args") or []),
            _salt=str(spec.get("salt") or ""), **kwargs,
        )
    except RenderYielded as yielded:
        return f"{name} yielded to the writer ({yielded})"
    finally:
        conn.close()
        entry = dict(_SECTION_CACHE_LOG.get(name) or {})
        if _RESEARCH_GAP_WAIT_LEFT:
            _RESEARCH_GAP_WAIT_LEFT[0] = float(_PAGED_RUN.get("gap_wait_left") or 0.0)
        _PAGED_RUN.clear()
    elapsed = time.perf_counter() - started
    if entry.get("stale") or entry.get("unavailable"):
        return f"{name} not computed ({entry.get('stale_reason')})"
    return f"{name} computed in {elapsed:.0f}s"


def refresh_research_section(db: Path) -> str:
    """Refresh the overdue pages the page render cannot, most overdue first.

    The research render (``--refresh-research``; launchd
    com.weather.dashboard_research_render): every heavy section (last build
    ``RESEARCH_SECTION_MIN_COST_SEC`` or more) past its lifetime, and every
    starved one (``STARVED_PAGE_AGE_SEC``), each called exactly as the page
    render last called it (``RENDER_SECTION_SPECS``), one after another
    until ``RESEARCH_RUN_BUDGET_SEC`` -- a section whose last cost no longer
    fits is passed over for a cheaper one -- and never beside the page
    render: it stops as soon as one starts.  Same gap waits and the same WAL
    yield as the page render; it writes the sections' pages and nothing
    else, and the next page render serves them.
    """

    _note_research_death()
    specs = _live_specs(_load_closed_readings(RENDER_SECTION_SPECS))
    due = research_due(specs, _now())
    if not due:
        return "research render: nothing due"
    started = time.perf_counter()
    done: list[str] = []
    _RESEARCH_GAP_WAIT_LEFT[:] = [RENDER_GAP_WAIT_BUDGET_SEC]
    try:
        for _overdue, name, cost in due:
            spent = time.perf_counter() - started
            if done and spent + cost > RESEARCH_RUN_BUDGET_SEC:
                continue
            if done and _page_render_running():
                done.append("stopped: the page render started")
                break
            done.append(_refresh_one_section(db, name, specs[name]))
    finally:
        _RESEARCH_GAP_WAIT_LEFT.clear()
    return "research render: " + "; ".join(done)

def _serve_unavailable(name: str, value: Any, reason: str) -> Any:
    _SECTION_CACHE_LOG[name] = {
        "reused": False,
        "cached": False,
        "unavailable": True,
        "stale_reason": reason,
    }
    _PAGED_RUN["stale"][name] = f"unavailable ({reason})"
    print(
        f"[{_now().strftime('%Y-%m-%dT%H:%M:%SZ')}] section {name}"
        f" not shown this run ({reason}); it has no page yet",
        file=sys.stderr,
        flush=True,
    )
    return json.loads(json.dumps(value))


#: Each cached section's value this build, by name, so the page can say which
#: section reads which cache (user 2026-10-01: 把最下方的数据过期诊断放到各个板块).
_SECTION_CACHE_VALUES: dict[str, Any] = {}


def _cached_section(name: str, collector: Any, *args: Any, **kwargs: Any) -> Any:
    """``_cached_section_value``, and a record of what fed it.

    A section handed another section's value as an argument (members is fed
    run_cadence and member_depth) is only as fresh as that input, so the
    input's name rides on the entry as ``fed_by`` -- found by identity, the
    very object passed in, so no list of edges has to be kept by hand.
    """

    value = _cached_section_value(name, collector, *args, **kwargs)
    feeds = sorted(
        other for other, held in _SECTION_CACHE_VALUES.items()
        if held is not None and not isinstance(held, (str, int, float, bool))
        and any(held is arg for arg in args)
    )
    _SECTION_CACHE_VALUES[name] = value
    entry = _SECTION_CACHE_LOG.get(name)
    if entry is not None and feeds:
        entry["fed_by"] = feeds
    return value


def _section_cache_destinations(payload: Mapping[str, Any]) -> dict[str, Any]:
    """The cache log, each entry with the payload keys its value landed in.

    By identity again: a payload key whose value IS the cached value, or one
    of its top-level members (``daily`` is ``live_days["daily"]``).  The page
    reads these to put each section's staleness inside that section.
    """

    log = {name: dict(entry) for name, entry in _SECTION_CACHE_LOG.items()}
    for name, value in _SECTION_CACHE_VALUES.items():
        if name not in log or value is None or isinstance(value, (str, int, float, bool)):
            continue
        members = list(value.values()) if isinstance(value, dict) else []
        keys = sorted(
            key for key, held in payload.items()
            if key != "section_cache" and (
                held is value or any(held is member for member in members
                                     if not isinstance(member, (str, int, float, bool)) and member is not None)
            )
        )
        if keys:
            log[name]["payload_keys"] = keys
    return log


def _cached_section_value(
    name: str,
    collector: Any,
    *args: Any,
    _salt: str = "",
    _unavailable: Any = _NO_UNAVAILABLE,
    **kwargs: Any,
) -> Any:
    """The collector's value, reused from disk while it is still young.

    A miss round-trips the fresh value through JSON before returning it, so
    a hit and a miss hand the rest of the build byte-identical structures --
    otherwise a tuple would reach the page as a tuple on the render that
    computed it and as a list on the five that reused it.

    Under a paged render (``_PAGED_RUN``) every section without a lifetime
    of its own gets ``PAGED_SECTION_TTL_SEC`` unless it is one of
    ``RENDER_EVERY_RUN_SECTIONS``, and every read waits for a production gap.

    ``_unavailable``: what a paged section with no page yet shows when the
    WAL keeps it from reading, instead of making the whole run step aside.
    Only for sections whose readers already cope with it -- a new section's
    first read under heavy writes (member_depth, 2026-09-24 03:17Z) should
    not keep the lamps off the page.
    """

    paged = bool(_PAGED_RUN) and SECTION_CACHE_ENABLED
    ttl = SECTION_CACHE_TTL_SEC.get(name)
    if paged and not ttl and name not in RENDER_EVERY_RUN_SECTIONS:
        args_salt = _paged_args_salt(args, kwargs)
        if args_salt is not None:
            ttl = PAGED_SECTION_TTL_SEC
            _salt = _salt + args_salt
    if not ttl or not SECTION_CACHE_ENABLED:
        # Still timed.  Only the nine sections with a TTL passed through
        # here, so the nine that were already the known-slow ones were the
        # only ones anybody could see the cost of -- and the render was 24
        # minutes on 2026-09-09 with no record of where the other minutes
        # went.  A section without a lifetime is not a section without a
        # price.
        if paged and _paged_past_deadline():
            served, value = _serve_every_run_last(name, collector)
            if served:
                return value
        if paged:
            blocker = _await_production_gap(
                name, LIVE_SECTION_GAP_CAP_SEC, RENDER_YIELD_WAL_BYTES
            )
            # A cycle in flight is only disk contention, and this section
            # has nothing else to serve; a WAL past the line is the writer
            # waiting on readers, and this run is one.
            if blocker is not None and blocker.startswith("wal"):
                raise RenderYielded(f"{name}: {blocker}")
            _PAGED_RUN["armed"] = True
            _PAGED_RUN["yielded"] = False
            # Interrupted at the deadline only if it has a last value to
            # serve instead.  One with none reads on, as before the deadline
            # existed, and keeps a last value for the next run: the first
            # run under the deadline (2026-10-01 14:10Z) cut live_days at
            # 1,380 s with nothing in its place and wrote no page at all.
            _PAGED_RUN["deadline_fallback"] = _every_run_last_path(name, collector).is_file()
        started = time.perf_counter()
        try:
            value = collector(*args, **kwargs)
        except sqlite3.OperationalError as exc:
            if paged and _PAGED_RUN["yielded"]:
                if _paged_past_deadline():
                    served, value = _serve_every_run_last(name, collector)
                    if served:
                        return value
                raise RenderYielded(f"{name}: interrupted, WAL past the line") from exc
            raise
        finally:
            if paged:
                _PAGED_RUN["armed"] = False
        if paged and _PAGED_RUN["yielded"]:
            # Caught the interrupt itself and returned what it had: a lamp
            # or a banner input read short must not be shown as fresh.
            if _paged_past_deadline():
                served, value = _serve_every_run_last(name, collector)
                if served:
                    return value
            raise RenderYielded(f"{name}: interrupted, WAL past the line")
        _SECTION_CACHE_LOG[name] = {
            "build_sec": round(time.perf_counter() - started, 1),
            "reused": False,
            "cached": False,
        }
        _trace_slow_section(name, _SECTION_CACHE_LOG[name]["build_sec"])
        if paged and name in RENDER_EVERY_RUN_SECTIONS:
            _save_every_run_costs()
            _save_every_run_last(name, collector, value)
        return value
    fingerprint = _section_fingerprint(collector, _salt)
    # The code alone, without the declared inputs: what decides whether an
    # old page has this section's shape.
    code_fingerprint = _section_fingerprint(collector, "")
    path = SECTION_CACHE_DIR / f"{name}.json"
    now = _now()
    page: dict[str, Any] | None = None
    page_age = 0.0
    page_inputs_moved = False
    # What the last build of this section cost, from whatever file is there
    # -- even one this code may not serve -- so a run can tell whether a
    # read will fit before starting it.
    last_cost = 0.0
    try:
        blob = json.loads(path.read_text(encoding="utf-8"))
        last_cost = float(blob.get("build_sec") or 0.0)
        stamp = str(blob["computed_at_utc"])
        age = (
            now - datetime.fromisoformat(stamp.replace("Z", "+00:00"))
        ).total_seconds()
        if "value" in blob and (
            blob.get("fingerprint") == fingerprint
            or blob.get("code_fingerprint") == code_fingerprint
        ):
            # Same code: servable as a stale page even past its lifetime,
            # and even when its declared inputs have moved since -- a date
            # in the key, a version window, another section it was fed.
            # That is an older answer, not another shape.  Never across a
            # code change.  (model_accuracy_trend's key carries the date,
            # so every morning it had no page at all and was read whole,
            # 354 s, and was what the 04:25Z run was killed on.)
            page, page_age = blob, age
            page_inputs_moved = blob.get("fingerprint") != fingerprint
        if blob.get("fingerprint") == fingerprint and 0.0 <= age < ttl:
            _SECTION_CACHE_LOG[name] = {
                "computed_at_utc": stamp,
                "age_sec": round(age),
                "ttl_sec": ttl,
                "reused": True,
                "cached": True,
            }
            return blob["value"]
    except (OSError, ValueError, KeyError, TypeError):
        pass
    forced = paged and _PAGED_RUN.get("force") == name
    if paged:
        _record_section_spec(name, collector, args, kwargs, _salt, _unavailable)
    if paged and not forced:
        # A heavy section with a page is the research render's to refresh.
        if last_cost >= RESEARCH_SECTION_MIN_COST_SEC:
            if page is not None:
                return _serve_stale_page(name, page, ttl, page_age, "research lane", page_inputs_moved)
            if _unavailable is not _NO_UNAVAILABLE:
                return _serve_unavailable(name, _unavailable, "research lane")
        if _paged_past_deadline():
            if page is not None:
                return _serve_stale_page(name, page, ttl, page_age, "deadline", page_inputs_moved)
            if _unavailable is not _NO_UNAVAILABLE:
                return _serve_unavailable(name, _unavailable, "deadline")
        # Room left for this section: the soft budget, less what the
        # every-run sections still to come cost last time.
        remaining = (
            RENDER_SOFT_BUDGET_SEC - _paged_elapsed() - _every_run_reserve_sec()
        )
        expected = float((page or {}).get("build_sec") or 0.0)
        if page is not None and expected > remaining:
            return _serve_stale_page(name, page, ttl, page_age, "budget", page_inputs_moved)
        # No page at all and no room for what it cost last time: a section
        # that declared what to show instead shows it, rather than reading
        # whole into the deadline.  07:54Z: model_accuracy_trend, pageless
        # for the day, read from 08:09Z into the 1,500 s kill; 08:36Z: the
        # same from 08:49Z, with 432 s of budget left for a 531 s section.
        if (
            page is None and last_cost >= remaining
            and _unavailable is not _NO_UNAVAILABLE
        ):
            return _serve_unavailable(name, _unavailable, "budget")
        # A section with a page reads only if a gap is open right now; it
        # never sits waiting for one.  Waiting out the budget on the first
        # such section is what the 02:46Z and 03:08Z runs did (run_cadence,
        # 360 s each, while the catch-up cycles ran back to back) -- a run
        # that then serves every page anyway, only later.  Without a page
        # there is nothing else to serve: wait a lamp's while at most, then
        # read -- unless the WAL is what is in the way.
        cap = 0.0 if page is not None else LIVE_SECTION_GAP_CAP_SEC
        # A pageless section that declared what to show instead is held to
        # the start line: it has something to serve.
        line = (
            None if page is not None or _unavailable is not _NO_UNAVAILABLE
            else RENDER_YIELD_WAL_BYTES
        )
        blocker = _await_production_gap(name, cap, line)
        # A cycle in flight does not stop a section with a page: only the
        # WAL does.  Production cycles now run back to back, so on
        # 2026-10-02 the page render served 115 pages "no gap" against 62
        # reads (nearly all every-run), and certificate_authority, gaps and
        # truth_coverage sat 2-4 hours old although the every-run sections
        # and the research render read through those same cycles.  A reader
        # costs the writer nothing under WAL; the budget above already
        # bounds what this run reads.
        if blocker is not None and page is not None and blocker.startswith("wal"):
            return _serve_stale_page(name, page, ttl, page_age, "no gap", page_inputs_moved)
        if blocker is not None and page is not None:
            blocker = None
        if blocker is not None and blocker.startswith("wal"):
            if _unavailable is not _NO_UNAVAILABLE:
                return _serve_unavailable(name, _unavailable, blocker)
            raise RenderYielded(f"{name}: {blocker}")
        _PAGED_RUN["armed"] = True
        _PAGED_RUN["yielded"] = False
        _PAGED_RUN["deadline_fallback"] = (
            page is not None or _unavailable is not _NO_UNAVAILABLE
        )
        # Stamped when the read starts, not when the section was reached:
        # a page is as old as the snapshot it read.
        now = _now()
    elif forced:
        blocker = _await_production_gap(name, LIVE_SECTION_GAP_CAP_SEC, RENDER_YIELD_WAL_BYTES)
        if blocker is not None and blocker.startswith("wal"):
            raise RenderYielded(f"{name}: {blocker}")
        _PAGED_RUN["armed"] = True
        _PAGED_RUN["yielded"] = False
        now = _now()
    started = time.perf_counter()
    try:
        value = collector(*args, **kwargs)
    except SectionNotReady as exc:
        if not paged:
            raise
        _trace_slow_section(name, time.perf_counter() - started)
        if page is not None:
            return _serve_stale_page(name, page, ttl, page_age, f"catching up: {exc}", page_inputs_moved)
        if _unavailable is not _NO_UNAVAILABLE:
            return _serve_unavailable(name, _unavailable, f"catching up: {exc}")
        raise RenderYielded(f"{name}: {exc}") from exc
    except sqlite3.OperationalError as exc:
        if paged and _PAGED_RUN["yielded"]:
            _PAGED_RUN["yields"] = int(_PAGED_RUN["yields"]) + 1
            if page is not None:
                return _serve_stale_page(name, page, ttl, page_age, "yielded", page_inputs_moved)
            if _unavailable is not _NO_UNAVAILABLE:
                return _serve_unavailable(name, _unavailable, "interrupted")
            raise RenderYielded(f"{name}: interrupted, WAL past the line") from exc
        raise
    finally:
        if paged:
            _PAGED_RUN["armed"] = False
    elapsed = time.perf_counter() - started
    _trace_slow_section(name, elapsed)
    if paged and _PAGED_RUN["yielded"]:
        # The collector caught the interrupt itself and returned what it
        # had: a degraded value.  Never cache it as a page.
        _PAGED_RUN["yields"] = int(_PAGED_RUN["yields"]) + 1
        if page is not None:
            return _serve_stale_page(name, page, ttl, page_age, "yielded", page_inputs_moved)
        if _unavailable is not _NO_UNAVAILABLE:
            return _serve_unavailable(name, _unavailable, "interrupted")
        raise RenderYielded(f"{name}: interrupted, WAL past the line")
    stamp = now.isoformat().replace("+00:00", "Z")
    _SECTION_CACHE_LOG[name] = {
        "computed_at_utc": stamp,
        "age_sec": 0,
        "ttl_sec": ttl,
        "reused": False,
        "cached": True,
        "build_sec": round(elapsed, 1),
    }
    try:
        value = json.loads(json.dumps(value, ensure_ascii=False))
    except (TypeError, ValueError):
        # Not representable, so it cannot be cached either.  Serve it and
        # say so rather than pretending the section is cached.
        _SECTION_CACHE_LOG[name]["reused"] = False
        _SECTION_CACHE_LOG[name]["uncacheable"] = True
        return value
    try:
        SECTION_CACHE_DIR.mkdir(parents=True, exist_ok=True)
        for stale in SECTION_CACHE_DIR.glob(f"{path.name}.*.tmp"):
            # A render killed mid-write leaves one of these; nothing reads
            # them, so they would accumulate silently forever.
            try:
                if stale.stat().st_mtime < time.time() - 6 * 3600:
                    stale.unlink()
            except OSError:
                pass
        # Unique per process: the hosted sweep and a hand-run render can
        # overlap (measured: two builds in flight at 04:10 on 2026-09-02),
        # and a shared temp name lets one replace the file the other is
        # still writing.  Distinct names make last-writer-wins the only
        # outcome, and both writers leave a complete file behind.
        tmp = path.with_name(f"{path.name}.{os.getpid()}.tmp")
        tmp.write_text(
            json.dumps(
                {
                    "schema": "dashboard_section_cache_v1",
                    "section": name,
                    "fingerprint": fingerprint,
                    "code_fingerprint": code_fingerprint,
                    "computed_at_utc": stamp,
                    "build_sec": round(elapsed, 1),
                    "value": value,
                },
                ensure_ascii=False,
            ),
            encoding="utf-8",
        )
        tmp.replace(path)
    except (OSError, TypeError, ValueError):
        pass
    return value


def _build_payload(conn: sqlite3.Connection, db: Path) -> dict[str, Any]:
    _SECTION_CACHE_LOG.clear()
    _SECTION_CACHE_VALUES.clear()
    cadence = _cached_section("run_cadence", collect_run_cadence, conn)
    recent_runs = _cached_section("recent_runs", collect_recent_runs, conn)
    member_depth = _cached_section(
        "member_depth", collect_member_depth, conn, _unavailable={}
    )
    members = _cached_section(
        "members", collect_members, conn,
        _merge_recent_runs(cadence, recent_runs), member_depth,
    )
    member_admission = _cached_section(
        "member_admission", collect_member_admission, conn, members
    )
    # The every-run sections first (RENDER_EVERY_RUN_SECTIONS: the lamps, the
    # banner's inputs, the live book), so a paged run spends its budget on
    # them before any page-backed section, and a page is written on every run
    # that is not killed.  Until 2026-09-24 most of them sat at the end and
    # were what the 1,500 s deadline cut off (03:30Z and 04:25Z runs).
    #
    # Charter 162's two doors, and charters 153/154's cycle journal: both
    # read every render -- a freshness lamp that can be an hour stale is a
    # lamp that says green through an outage.
    observation_intake = _cached_section(
        "observation_intake", collect_observation_intake, conn
    )
    hosted_sweeps = _cached_section(
        "hosted_sweeps", collect_hosted_sweeps, conn
    )
    # The 发布时间 table's regional and TAF rows (every run, see
    # RENDER_EVERY_RUN_SECTIONS).
    regional = _cached_section("regional", collect_regional_lanes, conn)
    taf_board = _cached_section("taf_board", collect_taf_board, conn)
    delta_v2_authority = _cached_section(
        "delta_v2_authority", collect_delta_v2_authority, conn
    )
    certificate_authority = _cached_section(
        "certificate_authority", collect_certificate_authority, conn
    )
    chain_volume = _cached_section(
        "chain_volume", collect_chain_volume, conn, _unavailable={}
    )
    chain = _cached_section("chain", collect_chain, conn, chain_volume)
    truth_coverage = _cached_section(
        "truth_coverage", collect_truth_coverage, conn,
        _unavailable={"rows": [], "unavailable": True},
    )
    truth = _cached_section(
        "truth_materialization", collect_truth_materialization, conn,
        truth_coverage,
    )
    station_difficulty = _cached_section(
        "station_difficulty", collect_station_difficulty, conn,
        _unavailable={},
    )
    live_readiness = _cached_section(
        "live_readiness", collect_live_readiness, conn, station_difficulty,
    )
    live_money = _cached_section("live_money", collect_live_money, conn)
    # The strategy lanes' money pages: every-run, on the live book the
    # sections above already built this run.
    tiebreak_lane = _cached_section("tiebreak_lane", collect_tiebreak_lane, conn)
    proper_bet_lane = _cached_section(
        "proper_bet_lane", collect_proper_bet_lane, conn
    )
    tail_short_lane = _cached_section(
        "tail_short_lane", collect_tail_short_lane, conn
    )
    copy_follow_lane = _cached_section(
        "copy_follow_lane", collect_copy_follow_lane, conn
    )
    realisation_layer = _cached_section(
        "realisation_layer", collect_realisation_layer, conn
    )
    # The two heaviest live reads come after the money and the lanes
    # (2026-10-09): live_days and live_selection took 98-586 s a run,
    # and at 12:29Z their 856 s left the lanes, the live book's money and its
    # readiness to the deadline -- served an hour old -- on a run nothing in
    # them depended on.  A run that runs out now loses these two first.
    # 每日统计 and 逐站逐日明细 read the live book (user ruling, 2026-09-16).
    live_days = _cached_section("live_days", collect_live_days, conn)
    # The refusal funnel's closed days (live_selection.closed_plan_summaries):
    # their facts no longer change, so they are read once a day, not every
    # render; a page for an earlier ``through`` is still exact for its own
    # days, and the funnel reads everything after it.
    refusal_first_day, refusal_through = _refusal_history_window(conn)
    refusal_history = _cached_section(
        "refusal_history", _collect_refusal_history, conn,
        refusal_first_day, refusal_through,
        _salt=f"{refusal_first_day}|{refusal_through}",
        _unavailable=None,
    ) if refusal_first_day else None
    live_selection_payload = _cached_section(
        "live_selection", _build_live_selection, conn, refusal_history
    )
    previous_windows = _previous_version_windows(conn)
    previous_salt = json.dumps(previous_windows, sort_keys=True)
    center_landing_previous = _cached_section(
        "center_landing_previous", collect_center_landing, conn,
        windows=previous_windows, _salt=previous_salt + _center_landing_salt(),
    ) if previous_windows else {}
    # Charter 202: the served landing now reads the lanes' evidence window,
    # which spans every bump since the stage's epoch; the board's version
    # comparison ("本版 against 上一版") keeps reading the version itself.
    current_windows = {
        stage: {"since": window["until"], "until": "9999-12-31T00:00:00Z"}
        for stage, window in (previous_windows or {}).items()
    }
    center_landing_version = _cached_section(
        "center_landing_version", collect_center_landing, conn,
        windows=current_windows,
        _salt=json.dumps(current_windows, sort_keys=True) + _center_landing_salt(),
    ) if current_windows else {}
    trend_since = (
        _now() - timedelta(days=MODEL_ACCURACY_TREND_DAYS)
    ).strftime("%Y-%m-%dT00:00:00Z")
    model_accuracy_trend = _cached_section(
        "model_accuracy_trend", collect_model_accuracy_trend, conn,
        # Every reader on the page guards each field (``|| {}``, ``|| []``).
        _unavailable={},
        since=trend_since, _salt=trend_since + _center_landing_salt(),
    )
    station_calibration_windows = _cached_section(
        "station_calibration_windows", collect_station_calibration_windows,
        conn,
        _unavailable={},
        # The windows end today: a new day is a new answer.
        _salt=_now().strftime("%Y-%m-%d") + _center_landing_salt(),
    )
    scorecard_previous = _cached_section(
        "scorecard_previous", collect_calibration_scorecard, conn,
        window_override=previous_windows.get("P0"), _salt=previous_salt,
        # Heavy: built by the research render.  Without a page (first build,
        # or after a code change) the page render shows "not available"
        # instead of reading it whole past its deadline -- on 2026-10-02
        # scorecard_previous, pageless after 3ffee5a0, was read after the
        # deadline and the page render was killed three runs running.
        _unavailable={"available": False},
    ) if previous_windows.get("P0") else {"available": False}
    synoptic_cooling = _cached_section(
        "synoptic_cooling", collect_synoptic_cooling, conn
    )
    single_system_width = _cached_section(
        "single_system_width", collect_single_system_width, conn
    )
    consensus_bridge = _cached_section(
        "consensus_bridge", collect_consensus_bridge, conn
    )
    precip_classification = _cached_section(
        "precip_classification", collect_precip_classification, conn,
        _unavailable={"available": False},
    )
    regional_usage = _cached_section(
        "regional_usage", collect_regional_usage, conn
    )
    # Heavy pages from here down declare what to show without a page, so
    # the page render never reads one whole past its deadline (9d40f09a).
    p1_joint_likelihood = _cached_section(
        "p1_joint_likelihood", collect_p1_joint_likelihood, conn
    )
    p0m_taf_likelihood = _cached_section(
        "p0m_taf_likelihood", collect_p0m_taf_likelihood, conn
    )
    p1_path_skill = _cached_section(
        "p1_path_skill", collect_p1_path_skill, conn,
        _unavailable={"available": False},
    )
    tables = _cached_section(
        "correction_and_weights", collect_correction_and_weights, conn
    )
    ssot_capacity = _cached_section(
        "ssot_capacity", collect_ssot_capacity, conn,
        _unavailable={"available": False, "tables": []},
    )
    # The gauge is the resident's live status, read every render; only the
    # per-table composition is the cached daily page.  The lamp read the
    # page's copy until 2026-10-02, so a daily page would have held the
    # ceiling warning a day stale (and showed "3 天" from a one-hour growth
    # window long after the guard said 20.7).
    live_guard = _live_ssot_guard()
    if live_guard:
        ssot_capacity = {**(ssot_capacity or {}), **live_guard, "available": True}
    gaps = _cached_section(
        "gaps", collect_gaps, conn, members, tables
    )
    skill = _cached_section(
        "skill", collect_model_skill, conn,
        _unavailable={"rows": [], "totals": [], "summary": {}},
    )
    scores = _cached_section("oos_scores", collect_oos_scores, conn)
    serving_weights = _cached_section(
        "serving_weights", collect_serving_weights, conn
    )
    center_width = _cached_section(
        "center_width", collect_center_width, conn
    )
    center_landing = _cached_section(
        "center_landing", collect_center_landing, conn,
        _salt=_center_landing_salt(),
        _unavailable={},
    )
    scorecard = _cached_section(
        "scorecard", collect_calibration_scorecard, conn,
        _salt=_scorecard_salt(conn),
        _unavailable={"available": False},
    )
    truth_landing = _cached_section(
        "truth_landing", collect_truth_landing, conn,
        # The card is hidden when this is empty.
        _unavailable={},
        # The band grid lives outside the collector, so it has to be
        # declared: changing it has to expire the file, not wait it out.
        _salt=repr(TRUTH_LANDING_PRICE_BANDS)
        + repr(TRUTH_LANDING_GAP_GROUPS) + repr(TRUTH_LANDING_UNLIKELY),
    )
    worker = {}
    if STATUS_JSON.is_file():
        try:
            status = json.loads(STATUS_JSON.read_text())
            worker = {
                "heartbeat_at": status.get("heartbeat_at"),
                "heartbeat_age_hours": _age_hours(
                    status.get("heartbeat_at")
                ),
                "pid": status.get("pid"),
                "live_submit_authorized": status.get(
                    "live_submit_authorized"
                ),
                **_production_health(status),
                **_taf_capture_health(status),
                **_nwp_rotation_health(status),
                **_official_native_family_coverage(status),
                **_settlement_source_health(status),
                **_settlement_reconciliation_health(),
            }
        except (ValueError, OSError):
            worker = {}
    # The banner used to say "something below is red" and leave the reader
    # to scroll sixteen sections for the one red word.  Collect the
    # non-green rows from exactly the four sources the light is computed
    # from, so the banner can name them -- and derive the light from this
    # list, so the two can never disagree.
    alerts = (
        [
            {"health": m["health"], "label": f"模型 {m['label']}",
             "note": m.get("note") or ""}
            for m in members if m["health"] != "green"
        ]
        + [
            {"health": c["health"], "label": f"链路·{c['name']}",
             "note": c.get("note") or ""}
            for c in chain if c["health"] != "green"
        ]
        + (
            [{"health": truth["health"], "label": "真值物化",
              "note": truth.get("note") or ""}]
            if truth["health"] != "green" else []
        )
        # The resident's own health.  It was absent from this list until
        # 2026-08-26, when production sat BLOCKED_FAIL_CLOSED for eleven
        # hours behind a healthy heartbeat: the page showed a live pid and
        # a fresh timestamp while nothing was being produced, and the
        # outage surfaced only because someone audited refusals by hand.
        # A heartbeat says the process is alive; it does not say the
        # pipeline is working.
        + (
            [{"health": worker["production_health"],
              "label": "生产周期",
              "note": worker.get("production_note") or ""}]
            if worker.get("production_health") not in (None, "green") else []
        )
        # Supply, beside production.  A stalled TAF lane does not stop the
        # cycle -- it makes the cycle refuse scopes for a reason that names
        # the probability stage, so it has to be reported where the refusal
        # is read rather than left to be inferred from it.
        + (
            [{"health": worker["taf_capture_health"],
              "label": "TAF 采集",
              "note": worker.get("taf_capture_note") or ""}]
            if worker.get("taf_capture_health") not in (None, "green") else []
        )
        # The resident's maintenance lanes.  A lane that is taking its turn
        # and failing takes everyone behind it down with it under an
        # exclusive write domain, and it had no symptom anywhere on this
        # page until 2026-09-10.  Only the red ones, and a merely starved
        # lane only once the generation has lived an hour: every lane looks
        # starved a minute after a restart, and saying so would train the
        # banner to be ignored on exactly the days it matters.
        + [
            {"health": "red", "label": f"扫描车道·{lane['name']}",
             "note": lane.get("note") or ""}
            for lane in (hosted_sweeps.get("lanes") or [])
            if lane.get("health") == "red"
            and (
                lane.get("stuck")
                or (lane.get("last_state") or "ok") != "ok"
                or (hosted_sweeps.get("generation_age_sec") or 0.0) >= 3600.0
            )
        ]
        # The execution authority's clock.  An end here is a fleet-wide
        # refusal on a date, with no earlier symptom anywhere downstream.
        + (
            [{"health": delta_v2_authority.get("health") or "amber",
              "label": "执行授权有效期",
              "note": delta_v2_authority.get("note") or ""}]
            if delta_v2_authority.get("health") != "green" else []
        )
        # Charter 206: a P0 certificate never simply ends, so the thing to
        # say is which scopes serve on renewed (unrefreshed) evidence and
        # which the renewal lane has not reached.
        + (
            [{"health": certificate_authority.get("health") or "amber",
              "label": "P0 证书有效期",
              "note": certificate_authority.get("note") or ""}]
            if certificate_authority.get("health") != "green" else []
        )
        # The other supply lane, and the one whose stall has no other
        # symptom on this page: a stopped NWP rotation surfaces three layers
        # downstream as latest_stage_stale_fail_closed, which names a stage
        # selector and says nothing about a capture that never happened.
        + (
            [{"health": worker["nwp_rotation_health"],
              "label": "NWP 轮转",
              "note": worker.get("nwp_rotation_note") or ""}]
            if worker.get("nwp_rotation_health") not in (None, "green") else []
        )
        # A packet that shipped short of families.  Distinct from every row
        # above: the rotation advanced, the lane is alive, each family is
        # inside its own cadence, and the packets a decision reads still
        # carry two of four.  On 2026-09-10 that was true of all 37 of the
        # D+2 packets while this banner stayed silent.
        + (
            [{"health": worker["native_inbox_health"],
              "label": "包里的家族数",
              "note": "；".join(
                  f"{row['event_date']} 只有 {row['family_count']}"
                  f"/{row['expected_family_count']} 家"
                  + (f"（缺 {'、'.join(row['absent'])}）"
                     if row["absent"] else "")
                  for row in (worker.get("native_inbox_coverage") or [])
                  if row["event_date"]
                  in (worker.get("native_inbox_short_near_dates") or [])
              )}]
            if worker.get("native_inbox_health") not in (None, "green") else []
        )
        # Charter 205: whether the markets still settle on what the truth
        # lane computes.  The 08-23 NOAA rewording starved the fleet for a
        # day with nothing on this page.
        + (
            [{"health": worker["settlement_source_health"],
              "label": "结算源",
              "note": worker.get("settlement_source_note") or ""}]
            if worker.get("settlement_source_health") not in (None, "green")
            else []
        )
        # Charter 207: whether the buckets we settle on are the ones the
        # market paid.  A truth short of its afternoon settled KORD 63F on a
        # day the market paid 66-67F, and nothing compared the two.
        + (
            [{"health": worker["settlement_reconciliation_health"],
              "label": "真值对账",
              "note": worker.get("settlement_reconciliation_note") or ""}]
            if worker.get("settlement_reconciliation_health") not in (None, "green")
            else []
        )
        # Charter 197: whether the world is reachable and whether the P0 a
        # decision reads is fresh -- the two things that failed on
        # 2026-09-21/22 while every row above stayed green.
        + _supply_watch_alerts(db=db)
        + _render_deadline_alerts()
    )
    overall = (
        "red" if any(a["health"] == "red" for a in alerts)
        else ("amber" if alerts else "green")
    )
    return {
        "schema": "calibration_dashboard_v2",
        "generated_at_utc": _now().isoformat().replace("+00:00", "Z"),
        "overall_health": overall,
        "alerts": alerts,
        "live_selection": live_selection_payload,
        "daily": live_days["daily"],
        "live_roster": live_days["roster"],
        "members": members,
        "member_depth": member_depth,
        "refusal_history": {
            key: value for key, value in (refusal_history or {}).items()
            if key != "days"
        },
        "chain_volume": chain_volume,
        "member_admission": member_admission,
        "recent_runs": recent_runs,
        "synoptic_cooling": synoptic_cooling,
        "single_system_width": single_system_width,
        "consensus_bridge": consensus_bridge,
        # One short name per system for the page's own tables (the fusion
        # seat column cut ids at the first "_": two ECMWFs, two NOAAs).
        "system_labels": dict(MEMBER_FAMILY_LABELS),
        "taf_board": taf_board,
        "precip_classification": precip_classification,
        "observation_intake": observation_intake,
        "regional_usage": regional_usage,
        "p1_joint_likelihood": p1_joint_likelihood,
        "p0m_taf_likelihood": p0m_taf_likelihood,
        "p1_path_skill": p1_path_skill,
        "tables": tables,
        "truth_landing": truth_landing,
        "live_readiness": live_readiness,
        "tiebreak_lane": tiebreak_lane,
        "board_evidence": collect_board_evidence(),
        "proper_bet_lane": proper_bet_lane,
        "tail_short_lane": tail_short_lane,
        "copy_follow_lane": copy_follow_lane,
        "basket_shadow": collect_basket_shadow(),
        "traded_calibration": collect_traded_calibration(),
        "bucket_calibration": collect_bucket_calibration(),
        "realisation_layer": realisation_layer,
        "chain": chain,
        "hosted_sweeps": hosted_sweeps,
        "ssot_capacity": ssot_capacity,
        "delta_v2_authority": delta_v2_authority,
        "certificate_authority": certificate_authority,
        "gaps": gaps,
        "skill": skill,
        "truth": truth,
        "scores": scores,
        "serving_weights": serving_weights,
        "center_width": center_width,
        "center_landing": center_landing,
        "scorecard": scorecard,
        # The version before the served one, over its own span, for the
        # side-by-side (user, 2026-09-18: 显示，做对比).
        "previous_version_windows": previous_windows,
        "center_landing_previous": center_landing_previous,
        "center_landing_version": center_landing_version,
        "scorecard_previous": scorecard_previous,
        "model_accuracy_trend": model_accuracy_trend,
        "station_calibration_windows": station_calibration_windows,
        # 48 index seeks; the link on every station name.
        "station_markets": collect_station_markets(conn),
        "fusion_candidates": collect_fusion_candidates(),
        "h5_readiness": _cached_section(
            "h5_readiness", collect_h5_readiness, conn,
            # The card reads ``days || []`` and hides when there are none.
            _unavailable={}
        ),
        "charter_ev": _cached_section(
            "charter_ev", collect_charter_ev, conn,
            _unavailable={"available": False},
            # The arithmetic lives in two helpers the fingerprint cannot
            # see; without this a change to either keeps serving the old
            # reading for the section's whole lifetime.
            _salt=_loaded_source(charter_ev_identity)
            + _loaded_source(_charter_ev_reading),
        ),
        # The account, off the live book (user ruling, 2026-09-16).  The
        # paper book's own risk metrics and nine numbers left the page with
        # it: the ledger is a rule comparator, not the account.
        "live_money": live_money,
        "regional": regional,
        "worker": worker,
        "section_cache": dict(_SECTION_CACHE_LOG),
    }


